import React from 'react';
import {
  Card,
  Grid,
  TextField,
  Button,
  Typography,
  Box,
} from "@mui/material";
import { getCookie } from "../../Services/Cookies";
import axiosInstance from "../../Services/AxiosInstance";
import { renderSubmitErrorAlert, useSuccessAndResetAlert } from "../../RAS_updates/Heplers";
import { useRecoilState } from "recoil";
import { siFundMasterAtom, siFundGlobatMasterIdAtom, siStateListAtom, siFundReleaseTableAtom, siFundTotalSancAtom, siFundTotalSancTableAtom, siFundSiNameListAtom } from "../../RAS_updates/Heplers";
import RestartAltRounded from "@mui/icons-material/RestartAltRounded";
import AutorenewIcon from '@mui/icons-material/Autorenew';
import { SiWOMasterUploadFile } from "../SiWorkOrder/SiWoMasterUploadFile";
import { CusReqDropdownSIPayment } from "../../Shobha_updates/SIPayments/CusReqDropdownSIPayment"

export default function SiFundMasterCard() {
  const [fundMaster, setFundMaster] = useRecoilState(siFundMasterAtom);
  const successAlertAndReset = useSuccessAndResetAlert(siFundMasterAtom);
  const [globalFundMasterId, setGlobalFundMasterId] = useRecoilState(siFundGlobatMasterIdAtom);
  const [siNameList, setSiNameList] = useRecoilState(siFundSiNameListAtom);
  const [form, setForm] = useRecoilState(siFundTotalSancAtom);


  const handleChange = (field) => (event) => {
    setFundMaster((prev) => ({
      ...prev,
      [field]: event.target.value,
    }));
  };

  const handleClear = () => {
    setFundMaster({
      stateUt: "",
      utilized: "",
      balance: "",
      nextFundToBeRelease: "",
      centreShareInterestAmtYetToBeDeposit: "",
      siWODoc: "",
      deficitAmt: "",
    });
  };

  const handleSave = async () => {
    const user_id = getCookie("resourceId");

    const payload = {
      createdBy: user_id,
      id: globalFundMasterId,
      stateUt: fundMaster.stateUt.id,
      utilized: fundMaster.utilized,
      balance: fundMaster.balance,
      nextFundToBeRelease: fundMaster.nextFundToBeRelease,
      centreShareInterestAmtYetToBeDeposit: fundMaster.centreShareInterestAmtYetToBeDeposit,
      docPath: fundMaster.siWODoc,
      deficitAmt: fundMaster.deficitAmt
    };

    try {
      const res = await axiosInstance.post("/siFundMaster/update", payload);
      if (res.status === 200 && res.data.message) {
        successAlertAndReset(res.data.message);
      } else {
        renderSubmitErrorAlert(res.data.error || "Submission failed");
      }
    } catch (err) {
      renderSubmitErrorAlert("An error occurred while saving");
    }
  };

  return (
  <Grid item xs={12} sx={{ p: 2 }}>
    <Card sx={{ p: 3, width: "100%" }}>
      <Typography variant="h6" sx={{ mb: 2 }}>SI Fund Master</Typography>
      <Grid container spacing={2}>
        <Grid item xs={12} md={4}>
          <CusReqDropdownSIPayment
            //@ts-ignore
            formDataAtom={siFundMasterAtom}
            listDataAtom={siStateListAtom}
            ddLabel="State/ UT"
            dropdownName="stateUt"
            fetchMasterDataURL="fetchStateMasterData_CusReq"
            //@ts-ignore
            optionLabel={["StateNameAndCode", "name", "short_name", "code"]}
            defVal={fundMaster.stateUt}
            value={fundMaster.stateUt || ""}
            onChange={handleChange("stateUt")}
            required
          />
        </Grid>

        <Grid item xs={12} md={4}>
          <TextField
            label="Utilized"
            type="number"
            fullWidth
            value={fundMaster.utilized || ""}
            onChange={handleChange("utilized")}
          />
        </Grid>

        <Grid item xs={12} md={4}>
          <TextField
            label="Balance"
            type="number"
            fullWidth
            value={fundMaster.balance || ""}
            onChange={handleChange("balance")}
          />
        </Grid>

        <Grid item xs={12} md={4}>
          <TextField
            label="Next Fund To Be Released"
            type="number"
            fullWidth
            value={fundMaster.nextFundToBeRelease || ""}
            onChange={handleChange("nextFundToBeRelease")}
          />
        </Grid>

        <Grid item xs={12} md={4}>
          <TextField
            label="Interest Amount Yet To Be Deposited"
            type="number"
            fullWidth
            value={fundMaster.centreShareInterestAmtYetToBeDeposit || ""}
            onChange={handleChange("centreShareInterestAmtYetToBeDeposit")}
          />
        </Grid>

        <Grid item xs={12} md={4}>
          <TextField
            label="Deficit Amount"
            type="number"
            fullWidth
            value={fundMaster.deficitAmt || ""}
            onChange={handleChange("deficitAmt")}
          />
        </Grid>

        <Grid item xs={12} md={8}>
          <SiWOMasterUploadFile formAtom={siFundMasterAtom} />
        </Grid>
      </Grid>

      <Box sx={{ display: "flex", justifyContent: "flex-end", gap: 1, mt: 2 }}>
        <Button
          onClick={handleSave}
          variant="contained"
          color="success"
        >
          Update <AutorenewIcon sx={{ width: 20, ml: 1 }} />
        </Button>
        <Button
          variant="contained"
          color="warning"
          onClick={handleClear}
        >
          Clear <RestartAltRounded sx={{ width: 20, ml: 1 }} />
        </Button>
      </Box>
    </Card>
    </Grid>
    );
}
