import {FormControlLabel, FormLabel, Grid, Paper, Radio, RadioGroup, TextField, Typography} from "@mui/material";
import {
    currentDate, currentDatePlus14,
    cusReqMasterDataAtom, cusReqShowstopperListAtom,
    cusReqStateListAtom,
    ErrorLabelAtom, formatDate, genUUID,
    isEmptyObject,
    isObjectCus,
    renderInputErrorLabel,
    SubmitErrorAlertAtom,
    useRecoilState, yesNoArr
} from "../../../../Heplers";
import React, {useEffect, useMemo} from "react";
import {CusReqDropdown, RadioYesNo} from "..";
import {CardGreenHeader} from "../../../CustomizationRequest/Components/CardGreenHeader";
import {defTextFieldOnChange} from "../../../CustomizationRequest/Components";

export const OperationalPractices= ({readOnly}) => {

    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);

    const defTextFieldOnChangeComParams = {
        setAtom, SubmitErrorAlert, setSubmitErrorAlert
    }

    useEffect(() => {
        // Setting Default Value
        // console.log(Atom)
        // For Update Form
        if (!isEmptyObject(Atom)) {
            // console.log("Sett params", Atom.edor, formatDate(Atom.edor, 'db-yyyy-mm-dd'))
            defTextFieldOnChange(formatDate(Atom.dor, 'db-yyyy-mm-dd'), "dor", defTextFieldOnChangeComParams);
            defTextFieldOnChange(formatDate(Atom.edor, 'db-yyyy-mm-dd'), 'edor', defTextFieldOnChangeComParams);
            defTextFieldOnChange(Atom.descrip, "descrip", defTextFieldOnChangeComParams);
            defTextFieldOnChange(Atom.addto, "addto", defTextFieldOnChangeComParams);
        } else {
            // console.log(" New Form Default Set like dates");

            defTextFieldOnChange(currentDate, "dor", defTextFieldOnChangeComParams);
            defTextFieldOnChange(currentDatePlus14, "edor", defTextFieldOnChangeComParams);
        }
    }, []);

    return useMemo(() => {
        return (
            <Paper elevation={2} sx={{mb: 2}} className={"greenBorder"}>
                <CardGreenHeader text={"Operational Practices"}/>

                <Grid p={2} spacing={2} container>

                    <Grid item xs={12} md={6}>
                        <RadioYesNo radioName={"op_pra1"} ddLabel={"Is the PACS center operational every day? How often is the personnel opens PACS center"}  />
                    </Grid>
                    <Grid item xs={12} md={6}>
                        <RadioYesNo radioName={"op_pra2"} ddLabel={"Is there any unique practice of the PACS which can be replicated to others"}  />
                    </Grid>
                    <Grid item xs={12} md={6}>
                        <RadioYesNo radioName={"op_pra3"} ddLabel={"Does the personnel switch on computer every time the PACS center is operational"} ddLabelID={""}  />
                    </Grid>

                    <Grid item xs={12} md={6}>
                        <TextField
                            label="What other issues are hampering daily day-end"
                            multiline
                            variant="outlined"
                            rows={2}
                            fullWidth

                            InputLabelProps={{
                                shrink: true,
                            }}
                            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.descrip : null}
                            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "descrip", defTextFieldOnChangeComParams)}

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}
                        />

                    </Grid>

                </Grid>
            </Paper>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
