import React, {useEffect, useMemo} from "react";
import "../../../Heplers/TableStyle.css";
import {
    Button,
    Card,
    Chip,
    Divider,
    Fab,
    Grid,
    Tooltip,
    Typography,
} from "@mui/material";
import CusReqListingHeader from "./CusReqDataListingTableHeader";
import {
    cusReqDataListingAtom, CUSTOMIZATIONREQUEST_LINK,
    dataListingLoadingAtom,
    genUUID, isARDBCusReqTabActive, overViewTabAtom,
    paramsFromURL,
    stagesArr,
    useRecoilState,
    useRecoilValue,
} from "../../../Heplers";
import {Link, useNavigate} from "react-router-dom";
import {AlignHorizontalCenter, Visibility} from "@mui/icons-material";
import {DataListingLoadingElem} from "./PageLoadingElem";
import moment from "moment";

export const chipSX = {
    color: "#FFF",
    minWidth: "unset",
    borderRadius: 10,
    p: "0.2px 10px",
};
export const renderReviewDates = (data, width = "100%") => {
    return data.map((v, i) => {
        switch (i + 1) {
            case 1:
                return "First: " + v;
            case 2:
                return (
                    <>
                        <Divider sx={{mb: 1, width: width}}/>
                        Second: {v}
                    </>
                );
            case 3:
                return (
                    <>
                        <Divider sx={{mb: 1, width: width}}/>
                        Third: {v}
                    </>
                );
            case 4:
                return (
                    <>
                        <Divider sx={{mb: 1, width: width}}/>
                        Fourth: {v}
                    </>
                );
            case 5:
                return (
                    <>
                        <Divider sx={{mb: 1, width: width}}/>
                        Fifth Review : {v}
                    </>
                );

            default:
                break;
        }
    });
};
const renderInputsChips = (data, inputs_closed, cusReqTabIndex) => {

    // console.log(data, inputs_closed)

    if (data === null) {
        return null;
    }
    data = JSON.parse(data);
    const dataArr = [];

    Object.keys(data).forEach(function (key, idx, arr) {
        // console.log("renderInputsChips", data[key], key, typeof data[key], cusReqTabIndex);

        // Means  Pending still pending
        if (
            data[key] === null ||
            data[key] == "Not Approved" ||
            data[key] == "Input Received"
        ) {
            if (isARDBCusReqTabActive(cusReqTabIndex) === "Yes") {
                // Renaming ARDB stakeholders
                switch (key.toUpperCase()){
                    case "PACS_STATUS":
                        dataArr.push("scardb_su_status");
                        break;
                    case "STCB_STATUS":
                        dataArr.push("scardb_ho_status");
                        break;
                    case "NLPSV_STATUS":
                        dataArr.push("nusv_status");
                        break;
                    default:
                        dataArr.push(key);
                        break;
                }
            } else {

                // console.log(key.toUpperCase())
                // Removing ARDB only stakeholders
                if (
                    key.toUpperCase() !== "SCARDB_BRANCH_STATUS" &&
                    key.toUpperCase() !== "PCARDB_BRANCH_STATUS" &&
                    key.toUpperCase() !== "PCARDB_HO_STATUS"
                ) {
                    dataArr.push(key);
                }

            }

        }

        // return dataArr.push(key)
    });

    return (
        <Grid>
            {(dataArr.length === 0 || inputs_closed === 'Yes') ? (
                <Chip label="Closed" color="success" sx={chipSX}/>
            ) : (
                dataArr.map((v) => (
                    <Chip
                        key={v}
                        className="inputRecChip"
                        label={String(v)
                            .replace(/_/g, " ")
                            .replace(/status/g, "")
                            .toUpperCase()}
                        sx={{
                            backgroundColor: "#B71C1C",
                            color: "#FFF",
                            mr: 0.5,
                            mt: 0.5,
                            minWidth: "unset",
                            borderRadius: 10,
                            p: "0.2px 10px",
                        }}
                        size="small"
                    />
                ))
            )}
        </Grid>
    );
};

export const renderPriorityChips = (data) => {
    if (data === null) {
        return null;
    }
    let bgColor = "#B71C1C";
    switch (String(data).toLowerCase()) {
        case "high":
            bgColor = "#E53935";
            break;
        case "medium":
            bgColor = "#E65100";
            break;
        case "low":
            bgColor = "#01579B";
            break;

        default:
            break;
    }

    return (
        <Chip
            className="inputRecChip"
            label={data}
            sx={{backgroundColor: bgColor, ...chipSX}}
            size="small"
        />
    );
};

const checkUpdateAndViewURLSuffix = () => {
    const urlParams = paramsFromURL({
        linkToSplit: CUSTOMIZATIONREQUEST_LINK + "listing/",
    });

    if (String(urlParams.paramId).toLowerCase().indexOf("business") !== -1) {
        return "brf";
    } else if (
        String(urlParams.paramId).toLowerCase().indexOf("development") !== -1
    ) {
        return "dev";
    } else if (String(urlParams.paramId).toLowerCase().indexOf("user") !== -1) {
        return "uat";
    } else {
        return "";
    }
};

export default function CusReqDatalisting() {
    const urlParams = paramsFromURL({
        linkToSplit: CUSTOMIZATIONREQUEST_LINK + "listing/",
    });

    const [dLLoading, setdlLoading] = useRecoilState(dataListingLoadingAtom);
    const Atom = useRecoilValue(cusReqDataListingAtom);

    const cusReqTabIndex = useRecoilValue(overViewTabAtom);

    useEffect(() => {
        // console.log({ PageLoading });
        return () => {
            setdlLoading(false);
        };
    }, []);

    const endingCommonCell = (v) => {
        // Fab button dimension
        const width = 35,
            height = 10;
        return (
            <>
                <td data-label="Action" className="mdTextAlignCenter">
                    <Grid
                        container
                        display="flex"
                        direction="row"
                        justifyContent={"right"}
                    >
                        <Tooltip
                            title={
                                <p>
                                    <b>View Details of CUI:</b> {v.cui}
                                    {v.old_uic !== null && <><br/><b>OLD UIC:</b> {v.old_uic}</>}
                                </p>
                            }
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Link
                                to={`/${CUSTOMIZATIONREQUEST_LINK}${checkUpdateAndViewURLSuffix()}/${
                                    v.cui
                                }`}
                            >
                                <Fab
                                    color="info"
                                    variant="circular"
                                    sx={{
                                        width: `${width}px !important`,
                                        height: `${height}px !important`,
                                        mr: 1,
                                    }}
                                >
                                    <Visibility sx={{fontSize: 16}}/>
                                </Fab>
                            </Link>
                        </Tooltip>

                        <Tooltip
                            title={
                                <p>
                                    <b>Checkout Timeline of CUI:</b> {v.cui}
                                </p>
                            }
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Link to={`/${CUSTOMIZATIONREQUEST_LINK}timeline/${v.cui}`}>
                                <Fab
                                    color="info"
                                    variant="circular"
                                    sx={{
                                        width: `${width}px !important`,
                                        height: `${height}px !important`,
                                    }}
                                >
                                    <AlignHorizontalCenter sx={{fontSize: 16}}/>
                                </Fab>
                            </Link>
                        </Tooltip>
                    </Grid>
                </td>
            </>
        );
    };

    const renderStagesWithRestriction = (v, forLinkedStageCheck, cui) => {
        // if previous stage added then only you can add brf -> dev -> uat

        // console.log(v, forLinkedStageCheck, cui);

        let actionNameBrf = v.brf === null ? "Add" : "View";
        let brfEnabled = v.inputs_closed === "Yes";

        let actionNameDev = v.dev === null ? "Add" : "View";
        // v.brf get the data from input_closed
        let devEnabled = brfEnabled && v.brf === "Yes";

        let actionNameUat = v.uat === null ? "Add" : "View";
        let uatEnabled = devEnabled && v.dev === "Yes";

        const stageStatus = (v) => <Typography
            sx={{fontSize: 10, textAlign: 'center', mt: 0.3, color: v == 'Yes' ? 'green' : 'red'}}>
            {v == 'Yes' ? 'Closed' : v == 'No' ? 'Open' : 'Not Created'}
        </Typography>
        switch (forLinkedStageCheck) {
            case "preparation":
                return (
                    <>
                        <Tooltip
                            key={genUUID()}
                            title={<p>{actionNameBrf} Business Requirement Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item justifyContent={"center"}>
                                <Link
                                    aria-disabled={!brfEnabled}
                                    to={brfEnabled && `/${CUSTOMIZATIONREQUEST_LINK}brf/${cui}`}
                                >
                                    <Button
                                        disabled={!brfEnabled}
                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={actionNameBrf == "View" ? "primary" : "success"}
                                        disableElevation
                                    >
                                        {actionNameBrf} brf
                                    </Button>
                                </Link>
                                {stageStatus(v.brf)}
                            </Grid>
                        </Tooltip>

                        <Tooltip
                            key={genUUID()}
                            title={<p>{actionNameBrf} Development Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item>
                                <Link
                                    aria-disabled={!devEnabled}
                                    to={devEnabled && `/${CUSTOMIZATIONREQUEST_LINK}dev/${cui}`}
                                >
                                    <Button
                                        disabled={!devEnabled}
                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={actionNameDev == "View" ? "primary" : "success"}
                                        disableElevation
                                    >
                                        {actionNameDev} dev
                                    </Button>
                                </Link>
                                {stageStatus(v.dev)}
                            </Grid>
                        </Tooltip>

                        <Tooltip
                            key={genUUID()}
                            title={<p>{actionNameBrf} User Acceptance Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item>
                                <Link
                                    aria-disabled={!uatEnabled}
                                    to={uatEnabled && `/${CUSTOMIZATIONREQUEST_LINK}uat/${cui}`}
                                >
                                    <Button
                                        disabled={!uatEnabled}
                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={actionNameUat == "View" ? "primary" : "success"}
                                        disableElevation
                                    >
                                        {actionNameUat} uat
                                    </Button>
                                </Link>
                                {stageStatus(v.uat)}
                            </Grid>
                        </Tooltip>
                    </>
                );

            case "brf":
                actionNameDev = v.dev === null ? "Add" : "View";
                devEnabled = v.inputs_closed === "Yes";

                actionNameUat = v.uat === null ? "Add" : "View";
                uatEnabled = devEnabled && v.dev === "Yes";
                return (
                    <>
                        <Tooltip
                            key={genUUID()}
                            title={<p>View Preparation Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item>
                                <Link to={`/${CUSTOMIZATIONREQUEST_LINK}/${cui}`}>
                                    <Button
                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={"primary"}
                                        disableElevation
                                    >
                                        View Pre
                                    </Button>
                                </Link>
                                {stageStatus('Yes')}
                            </Grid>
                        </Tooltip>

                        <Tooltip
                            key={genUUID()}
                            title={<p>{actionNameDev} Development Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item>
                                <Link
                                    aria-disabled={!devEnabled}
                                    to={devEnabled && `/${CUSTOMIZATIONREQUEST_LINK}dev/${cui}`}
                                >
                                    <Button
                                        disabled={!devEnabled}
                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={actionNameDev == "View" ? "primary" : "success"}
                                        disableElevation
                                    >
                                        {actionNameDev} dev
                                    </Button>
                                </Link>
                                {stageStatus(v.dev)}
                            </Grid>
                        </Tooltip>

                        <Tooltip
                            key={genUUID()}
                            title={<p>{actionNameUat} User Acceptance Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item>
                                <Link
                                    aria-disabled={!uatEnabled}
                                    to={uatEnabled && `/${CUSTOMIZATIONREQUEST_LINK}uat/${cui}`}
                                >
                                    <Button
                                        disabled={!uatEnabled}
                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={actionNameUat == "View" ? "primary" : "success"}
                                        disableElevation
                                    >
                                        {actionNameUat} uat
                                    </Button>
                                </Link>
                                {stageStatus(v.uat)}
                            </Grid>
                        </Tooltip>
                    </>
                );

            case "dev":
                actionNameUat = v.uat === null ? "Add" : "View";
                uatEnabled = v.inputs_closed === "Yes";

                return (
                    <>
                        <Tooltip
                            key={genUUID()}
                            title={<p>View Preparation Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item>
                                <Link to={`/${CUSTOMIZATIONREQUEST_LINK}/${cui}`}>
                                    <Button
                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={"primary"}
                                        disableElevation
                                    >
                                        View Pre
                                    </Button>
                                </Link>
                                {stageStatus('Yes')}
                            </Grid>
                        </Tooltip>

                        <Tooltip
                            key={genUUID()}
                            title={<p>Add Business Requirement Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item>
                                <Link
                                    to={`/${CUSTOMIZATIONREQUEST_LINK}brf/${cui}`}
                                >
                                    <Button
                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={'primary'}
                                        disableElevation
                                    >
                                        View BRF
                                    </Button>
                                </Link>
                                {stageStatus('Yes')}
                            </Grid>
                        </Tooltip>

                        <Tooltip
                            key={genUUID()}
                            title={<p>Add User Acceptance Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item>
                                <Link
                                    aria-disabled={!uatEnabled}
                                    to={uatEnabled && `/${CUSTOMIZATIONREQUEST_LINK}uat/${cui}`}
                                >
                                    <Button
                                        disabled={!uatEnabled}
                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={actionNameUat == "View" ? "primary" : "success"}
                                        disableElevation
                                    >
                                        {actionNameUat} uat
                                    </Button>
                                </Link>
                                {stageStatus(v.uat)}
                            </Grid>
                        </Tooltip>
                    </>
                );
            case "uat":
                return (
                    <>
                        <Tooltip
                            key={genUUID()}
                            title={<p>View Preparation Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item>
                                <Link to={`/${CUSTOMIZATIONREQUEST_LINK}/${cui}`}>
                                    <Button
                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={"primary"}
                                        disableElevation
                                    >
                                        View Pre
                                    </Button>
                                </Link>
                                {stageStatus('Yes')}
                            </Grid>
                        </Tooltip>

                        <Tooltip
                            key={genUUID()}
                            title={<p>View Business Requirement Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item>
                                <Link
                                    to={`/${CUSTOMIZATIONREQUEST_LINK}brf/${cui}`}
                                >
                                    <Button
                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={'primary'}
                                        disableElevation
                                    >
                                        View BRF
                                    </Button>
                                </Link>
                                {stageStatus('Yes')}
                            </Grid>
                        </Tooltip>

                        <Tooltip
                            key={genUUID()}
                            title={<p>View Development Stage</p>}
                            arrow
                            followCursor
                            placement="top"
                        >
                            <Grid item>
                                <Link
                                    to={`/${CUSTOMIZATIONREQUEST_LINK}dev/${cui}`}
                                >
                                    <Button

                                        sx={{
                                            minWidth: "unset",
                                            borderRadius: 10,
                                            fontSize: 10,
                                            p: "0.2px 15px",
                                        }}
                                        size="small"
                                        variant="outlined"
                                        color={"primary"}
                                        disableElevation
                                    >
                                        view dev
                                    </Button>
                                </Link>
                                {stageStatus('Yes')}
                            </Grid>
                        </Tooltip>
                    </>
                );
            default:
                return null;
        }

        let previousStageAdded = 0;

        // console.log(checkUpdateAndViewURLSuffix(), Atom);

        return stagesArr.map((v1) => {
            if (String(v1.n).toLowerCase().indexOf(forLinkedStageCheck) === -1) {
                const actionName =
                    v[String(v1.n).toLowerCase()] === null ? "Add" : "View";

                // console.log(String(v1.n).toLowerCase(), actionName, previousStageAdded);
                if (actionName === "Add") {
                    // previous stage added means
                    previousStageAdded++;
                }

                return (
                    <Tooltip
                        key={genUUID()}
                        title={
                            <p>
                                {actionName} {v1.d} Stage
                            </p>
                        }
                        arrow
                        followCursor
                        placement="top"
                    >
                        <Grid item>
                            <Link
                                aria-disabled={v.inputs_closed !== "Yes"}
                                to={
                                    previousStageAdded <= 1 &&
                                    `/${CUSTOMIZATIONREQUEST_LINK}${
                                        String(v1.n).toLowerCase() !== "preparation"
                                            ? String(v1.n).toLowerCase()
                                            : ""
                                    }/${cui}`
                                }
                            >
                                <Button
                                    disabled={v.inputs_closed !== "Yes"}
                                    sx={{
                                        minWidth: "unset",
                                        borderRadius: 10,
                                        fontSize: 10,
                                        p: "0.2px 15px",
                                    }}
                                    size="small"
                                    variant="outlined"
                                    color={actionName == "View" ? "primary" : "success"}
                                    disableElevation
                                >
                                    {actionName} {v1.n}
                                </Button>
                            </Link>
                        </Grid>
                    </Tooltip>
                );
            }
            return null;
        });
    };
    const startingCommonCell = (v, forLinkedStageCheck, goLiveDates = false) => {
        const dates =
            v.dates !== undefined && v.dates !== null ? JSON.parse(v.dates) : null;
        const cui = v.cui;

        return (
            <>
                <td data-label="CUI">
                    <Tooltip
                        title={
                            <p>
                                <b>Customization Unqiue Identification (CUI):</b> {v.cui}
                                {v.old_uic !== null && <><br/><b>OLD UIC:</b> {v.old_uic}</>}
                            </p>
                        }
                        arrow
                        followCursor
                        placement="top"
                    >
                        <Link
                            to={`/${CUSTOMIZATIONREQUEST_LINK}${checkUpdateAndViewURLSuffix()}/${
                                v.cui
                            }`}
                            className="dataListingCUI"
                        >
                            {v.cui}
                        </Link>
                    </Tooltip>


                    {v.old_uic !== null && <span style={{fontSize: 10}}><br/><br/>(OLD UIC: {v.old_uic})</span>}
                </td>
                <td data-label="Customization Request">
                    <Tooltip
                        title={
                            <p>
                                <b>Customization Category:</b>
                                <br/>
                                {v.bucket}
                                <Divider/>
                                <b>Description:</b> <br/> {v.descrip}
                            </p>
                        }
                        arrow
                        followCursor
                        placement="top"
                    >
                        <p className="lineClamp4">
                            <b>{v.bucket}</b>
                            <Divider/>
                            {v.descrip}
                        </p>
                    </Tooltip>
                    <Divider textAlign="left" sx={{width: "40%", mb: 0.5}}>
                        <Typography key={genUUID()} color={"GrayText"} fontSize={10}>
                            Stages
                        </Typography>
                    </Divider>
                    <Grid container spacing={2}>
                        {renderStagesWithRestriction(v, forLinkedStageCheck, cui)}
                    </Grid>
                </td>

                <td data-label="State">
                    <Tooltip
                        title={
                            <p>
                                <b>State:</b> {v.state}
                            </p>
                        }
                        arrow
                        followCursor
                        placement="top"
                    >
                        <p>{v.state}</p>
                    </Tooltip>
                </td>

                <td data-label="State">
                    <Tooltip
                        title={
                            <p>
                                <b>Assigned To:</b> {v.assigned_to}
                            </p>
                        }
                        arrow
                        followCursor
                        placement="top"
                    >
                        <p>{v.assigned_to}</p>
                    </Tooltip>
                </td>

                <td data-label="Dates">
                    {dates !== null && (
                        <Tooltip
                            title={
                                <p>
                                    {dates.start_date !== undefined &&
                                        dates.start_date !== null && (
                                            <>
                                                <b>This Stage Started On:</b>{" "}
                                                {moment(dates.start_date, "YYYY-MM-DD").format(
                                                    "DD-MMM-YY"
                                                )}
                                                <Divider/>
                                            </>
                                        )}
                                    {goLiveDates && (
                                        <>
                                            <b>Planned Go-Live Date:</b>{" "}
                                            {moment(
                                                // @ts-ignore
                                                goLiveDates.go_live_date,
                                                "YYYY-MM-DD"
                                            ).format("DD-MMM-YY")}
                                            <Divider/>
                                            <b>Actual Go-Live Date:</b>{" "}
                                            {moment(
                                                // @ts-ignore
                                                goLiveDates.actual_go_live_date,
                                                "YYYY-MM-DD"
                                            ).format("DD-MMM-YY")}
                                            <Divider/>
                                        </>
                                    )}
                                    <b>Expected Date of Resolution:</b>{" "}
                                    {dates.edorf !== null &&
                                        moment(dates.edorf, "YYYY-MM-DD").format("DD-MMM-YY")}
                                    <Divider/>
                                    <b>Date of Request:</b>{" "}
                                    {moment(dates.dor, "YYYY-MM-DD").format("DD-MMM-YY")}
                                </p>
                            }
                            arrow
                            followCursor
                            placement="top"
                        >
                            <p>
                                {dates.start_date !== undefined &&
                                    dates.start_date !== null && (
                                        <>
                                            <b>Started On:</b>
                                            <br/>{" "}
                                            {moment(dates.start_date, "YYYY-MM-DD").format(
                                                "DD-MMM-YY"
                                            )}
                                            <Divider sx={{my: 1}}/>
                                        </>
                                    )}
                                {goLiveDates && (
                                    <>
                                        {/* @ts-ignore */}
                                        {goLiveDates.go_live_date !== null && (
                                            <>
                                                <b>Planned Go-Live Date:</b>
                                                <br/>{" "}
                                                {moment(goLiveDates.go_live_date, "YYYY-MM-DD").format(
                                                    "DD-MMM-YY"
                                                )}{" "}
                                                <Divider sx={{my: 1}}/>
                                            </>
                                        )}

                                        {/* @ts-ignore */}
                                        {goLiveDates.actual_go_live_date !== null && (
                                            <>
                                                <b>Actual Go-Live Date:</b>
                                                <br/>{" "}
                                                {moment(
                                                    goLiveDates.actual_go_live_date,
                                                    "YYYY-MM-DD"
                                                ).format("DD-MMM-YY")}
                                                <Divider sx={{my: 1}}/>
                                            </>
                                        )}
                                    </>
                                )}
                                <b>EDoR:</b>
                                <br/>{" "}
                                {dates.edorf !== null &&
                                    moment(dates.edorf, "YYYY-MM-DD").format("DD-MMM-YY")}
                                <Divider sx={{my: 1}}/>
                                <b>DoR:</b>
                                <br/> {moment(dates.dor, "YYYY-MM-DD").format("DD-MMM-YY")}
                            </p>
                        </Tooltip>
                    )}
                </td>
                <td data-label="Priority" className="mdTextAlignCenter">
                    {renderPriorityChips(v.priority)}
                </td>

                <td data-label="Ageing" className="mdTextAlignCenter">
                    <Tooltip
                        title={
                            <p>
                                <b>Ageing:</b> {String(v.ageing).replace("00:00:00", "")} Days
                            </p>
                        }
                        arrow
                        followCursor
                        placement="top"
                    >
                        <p>{String(v.ageing).replace("00:00:00", "")}</p>
                    </Tooltip>
                </td>

                <td data-label="Pending Inputs">
                    {renderInputsChips(v.stakeholder_inputs, v.inputs_closed, cusReqTabIndex)}
                </td>
            </>
        );
    };

    const renderTR = () => {
        // return null

        if (dLLoading || Atom.records === undefined) {
            return null;
        }
        // @ts-ignore
        switch (String(urlParams.paramId).toLowerCase().replace(/%20/g, " ")) {
            case "business req. finalization":
                return Atom.records.map((v) => (
                    <tr key={genUUID()}>
                        {startingCommonCell(v, "brf")}
                        {endingCommonCell(v)}
                    </tr>
                ));

            case "development":
                return Atom.records.map((v) => (
                    <tr key={genUUID()}>
                        {startingCommonCell(v, "dev")}

                        <td data-label="NLPSV Resource Name" className="mdTextAlignCenter">
                            <p>
                                {
                                    // @ts-ignore
                                    v.nlpsv_resource_name
                                }
                            </p>
                        </td>

                        {endingCommonCell(v)}
                    </tr>
                ));
            case "user acceptance":
                return Atom.records.map((v) => {
                    // @ts-ignore
                    const acceptedArr =
                        typeof v.accepted_brd_points === "string" &&
                        v.accepted_brd_points.length > 0
                            ? v.accepted_brd_points.split(",")
                            : [];

                    let totalBrdPoints = 0;

                    // @ts-ignore
                    if (typeof v.brd_points === "string" && v.brd_points.length > 0) {
                        // @ts-ignore
                        const brd_pointsArr = JSON.parse(`[${v.brd_points}]`);
                        totalBrdPoints = brd_pointsArr.length;
                    }

                    return (
                        <tr key={genUUID()}>
                            {startingCommonCell(
                                v,
                                "uat",
                                // @ts-ignore
                                {
                                    start_date: v.start_date,
                                    go_live_date: v.go_live_date,
                                    actual_go_live_date: v.actual_go_live_date,
                                }
                            )}

                            <td data-label="Compliance On BRD" className="mdTextAlignCenter">
                                <p>
                                    {totalBrdPoints > 0 &&
                                        `${acceptedArr.length}/${totalBrdPoints} Points Incoprated`}
                                </p>
                            </td>

                            {endingCommonCell(v)}
                        </tr>
                    );
                });
                // @ts-ignore
                // @ts-ignore
                // @ts-ignore
                return;

            default:
                return Atom.records.map((v) => {
                    return (
                        <tr key={genUUID()}>
                            {startingCommonCell(v, "preparation")}

                            {endingCommonCell(v)}
                        </tr>
                    );
                });
        }
    };

    return useMemo(() => {
        return (
            <div style={{width: "100%"}}>
                <Card className="cusTable CusReqTableMobile" sx={{my: 2}}>
                    <table>
                        <CusReqListingHeader/>
                        <tbody>{renderTR()}</tbody>
                    </table>

                    <DataListingLoadingElem/>
                </Card>
            </div>
        );
    }, [dLLoading]);
}
