import React, { useEffect, useState } from "react";
import { Box, Stack, Typography, Button } from "@mui/material";
import { useAuth } from "../../Services/Auth";
import Icon from "../../Assets/files_icon.svg";
import PaidUnpaidChart from "./paidUnpaidChart";
import axios from "axios";
import axiosInstance from "../../Services/AxiosInstance";
import { getCookie } from "../../Services/Cookies";

const StateWiseCard = () => {
  const { setSelectedBtnSanc, selectedBtnSanc } = useAuth();
  const [apiRes, setApiRes] = useState([]);
  const [apiRes2, setApiRes2] = useState([]);
   const [fundSummary, setFundSummary] = useState({
    stateName: "",
    siFunds: 0,
    totalSancPACS: 0,
    totalInvoices: 0,
    paidPercent: 0,
    unpaidPercent: 0,
  });

  useEffect(() => {
    const fetchData = async () => {
      const config = {
        headers: {
          email: getCookie("email2"),
          "access-token": getCookie("token"),
          Authorization: `Bearer ${getCookie("token")}`,
        },
      };
      const requestBody = {
        stateName: selectedBtnSanc,
      };

      try {
        const fundResponse = await axiosInstance.post(
         `/siFundMastergraph/FundSummary?stateName=${encodeURIComponent(selectedBtnSanc)}`,
          requestBody,
          config
        );
        if (fundResponse.status === 200) {
          console.log(fundResponse.data[0]);
            setFundSummary(fundResponse.data);
        } 
      } catch (error) {
        console.error("Error fetching Fund data:", error);
      }

   
     }
      fetchData();
  }, [selectedBtnSanc]);
console.log("selectedBtnSanc : ", selectedBtnSanc);
  return (
    <>
      <Box
        sx={{
          backgroundColor: "#EEF4ED",
          padding: "2%",
          borderRadius: "4px",
        }}
      >
        <Stack direction="column">
          <Typography sx={{ fontFamily: "poppins" }}>
            {selectedBtnSanc}
          </Typography>
          <Typography
            sx={{
              fontFamily: "poppins",
              fontWeight: "bold",
              fontSize: "26px",
            }}
          >
            SI Invoices
          </Typography>
          <Stack
            sx={{ paddingTop: "10px" }}
            direction={{ xs: "column", md: "row" }}
            spacing={1}
          >
            <Stack
              sx={{
                backgroundColor: "#F7FCF7",
                padding: "10px",
                borderRadius: "6px",
              }}
              direction="column"
            >
              <Typography
                sx={{
                  color: "#333333",
                  fontFamily: "poppins",
                  fontSize: "14px",
                  fontWeight: "600",
                }}
              >
                SI Funds
              </Typography>
              <Stack direction="row" sx={{ paddingTop: "10px" }} spacing={1}>
                <img src={Icon} alt="" style={{ width: "50px" }} />
                <Stack direction="column">
                  <Typography
                    sx={{
                      fontWeight: "bold",
                      color: "grey",
                      fontSize: "12px",
                    }}
                  >
                    Funds
                  </Typography>
                  <Typography
                    sx={{
                      color: "#065036",
                      fontWeight: "bold",
                      fontSize: "28px",
                    }}
                  >
                    {fundSummary.siFunds || "NaN"}
                  </Typography>
                </Stack>
              </Stack>
            </Stack>
            <Stack
              sx={{
                backgroundColor: "#F7FCF7",
                padding: "10px",
                borderRadius: "6px",
              }}
              direction="column"
            >
              <Typography
                sx={{
                  color: "#333333",
                  fontFamily: "poppins",
                  fontSize: "14px",
                  fontWeight: "600",
                }}
              >
                Total Sanc
              </Typography>
              <Stack direction="row" sx={{ paddingTop: "20px" }}>
                <img src={Icon} alt="" style={{ width: "50px" }} />
                <Stack direction="column">
                  <Typography
                    sx={{
                      fontWeight: "bold",
                      color: "grey",
                      fontSize: "12px",
                    }}
                  >
                    PACS
                  </Typography>
                  <Typography
                    sx={{
                      color: "#065036",
                      fontWeight: "bold",
                      fontSize: "26px",
                    }}
                  >
                    ₹&nbsp;{fundSummary.totalSancPACS || "NaN"}
                  </Typography>
                </Stack>
              </Stack>
            </Stack>
            <Stack
              sx={{
                backgroundColor: "#F7FCF7",
                padding: "10px",
                borderRadius: "6px",
              }}
              direction="row"
            >
              <Stack direction="column">
                <Typography
                  sx={{
                    color: "#333333",
                    fontFamily: "poppins",
                    fontSize: "14px",
                    fontWeight: "600",
                  }}
                >
                  Total Invoices
                </Typography>
                <Stack direction="row" sx={{ paddingTop: "20px" }}>
                  <img src={Icon} alt="" style={{ width: "50px" }} />
                  <Stack direction="column">
                    <Typography
                      sx={{
                        fontWeight: "bold",
                        color: "grey",
                        fontSize: "12px",
                      }}
                    >
                      Invoices
                    </Typography>
                    <Typography
                      sx={{
                        color: "#065036",
                        fontWeight: "bold",
                        fontSize: "28px",
                      }}
                    >
                        ₹ {fundSummary.totalInvoices?.toFixed(2) || "0"}  &nbsp;Cr.
                    </Typography>
                  </Stack>
                </Stack>
              </Stack>
             <PaidUnpaidChart  paid={fundSummary.paidPercent} unpaid={fundSummary.unpaidPercent} />
            </Stack>
          </Stack>
        </Stack>
      </Box>
    </>
  );
};

export default StateWiseCard;
