// PaidUnpaidDonutChart.jsx
import React from 'react';
import Chart from 'react-apexcharts';

const PaidUnpaidChart = ({ paid = 0, unpaid = 0 }) => {
  const series = [paid, unpaid];
  const options = {
    chart: { type: 'donut' },
    labels: ['Paid', 'Unpaid'],
    colors: ['#28a745', '#dc3545'],
    dataLabels: {
      enabled: true,
      formatter: val => `${val.toFixed(1)}%`
    },
    plotOptions: {
      pie: {
        donut: {
          size: '65%',
          labels: {
            show: true,
            total: {
              show: true,
              label: 'Total',
              formatter: w => w.globals.seriesTotals.reduce((a, b) => a + b, 0)
            }
          }
        }
      }
    },
    legend: { position: 'bottom' },
    responsive: [{
      breakpoint: 480,
      options: {
        chart: { width: 300 },
        legend: { position: 'bottom' }
      }
    }]
  };

  return (
    <div className="chart-container" >
      <Chart options={options} series={series} type="donut" height="180" />
    </div>
  );
};



export default PaidUnpaidChart;
