import { Divider, Grid, TextField, Typography } from "@mui/material";
import {
  SubmitErrorAlertAtom,
  useRecoilState,
  ErrorLabelAtom,
  isEmptyObject,
  formatDate,
  StakeholderStatusArr,
  cusReqROStatusListAtom,
  isObjectCus,
  cusReqMasterDataAtom, currentDate
} from "../../../../Heplers";
import React, { useEffect, useMemo } from "react";
import { CusReqDropdown, defTextFieldOnChange } from "..";
import {getCookie} from "../../../../../Services/Cookies";

export const ROInputs = ({ formAtom, md, readOnly }) => {

  const [Atom, setAtom] = useRecoilState(formAtom);
  // forCheckingInputErrorLabelOnlyAfterSubmit
  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);

  const defTextFieldOnChangeComParams = {
    setAtom, SubmitErrorAlert, setSubmitErrorAlert
  }

  useEffect(() => {
    // Setting Default Value
    // console.log(Atom)
    // For Update Form
    if (!isEmptyObject(Atom)) {
      typeof Atom.ro_inputs === 'string' && defTextFieldOnChange(Atom.ro_inputs, "ro_inputs", defTextFieldOnChangeComParams);

      typeof Atom.ro_date === 'number' && defTextFieldOnChange(formatDate(Atom.ro_date, 'db-yyyy-mm-dd'), "ro_date", defTextFieldOnChangeComParams);
    }
  }, []);

  if(getCookie("userRole") === "RO"){
    readOnly = false;
  }

  return useMemo(() => {
    return (

      <Grid item spacing={2} xs={12} md={md} container direction={'column'}>

        <Grid item>
          <Divider textAlign="left" sx={{ width: "50%", my: 2 }}>
            <Typography className={'greenText'} fontSize={13} fontWeight="700">Regional Office</Typography>
          </Divider>
          <TextField
            label="Date"
            variant="outlined"
            type="date"
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? formatDate(Atom.ro_date, 'db-yyyy-mm-dd') : null}
            fullWidth

            InputProps={{inputProps: { max: currentDate } }}
            InputLabelProps={{
              shrink: true,
            }}
            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "ro_date", defTextFieldOnChangeComParams)}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
        </Grid>

        <Grid item>
          <CusReqDropdown
            // @ts-ignore
            formDataAtom={formAtom}
            listDataAtom={cusReqROStatusListAtom}
            ddLabel="Status"
            dropdownName={"ro_status"}
            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? (Atom.ro_status === null ? Atom.ro_status : Atom.ro_status) : null}
            optData={StakeholderStatusArr}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
          {/* @ts-ignore */}
        </Grid>

        <Grid item>
          <TextField
            label="Remarks"
            multiline
            variant="outlined"
            rows={4}
            fullWidth
            InputLabelProps={{
              shrink: true,
            }}
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.ro_inputs : null}
            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "ro_inputs", defTextFieldOnChangeComParams)}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}

          />
        </Grid>
      </Grid>


    );
  }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
