import {Button, CircularProgress, Divider, Grid, Stack, Typography} from "@mui/material";

import React, {useMemo, useRef, useState} from "react";

import {
    displayDownloadableFilesLinks,
    invalidURLAlert,
    successAndGoBackAlert,
    useRecoilState
} from "../../../../Heplers";
import {getCookie} from "../../../../../Services/Cookies";
import uploadcld from "../../../../../Assets/download_btn.svg";
import axiosInstance from "../../../../../Services/AxiosInstance";


export const BRFUploadFile = ({formAtom, labelText = "Upload Documents Here", fileUploadLableText = "Drop or Click here to upload file (PDF/PNG/JPEG/JPG/DOC/DOCX | <10MB)", acceptedFiles = "application/pdf, .png, .jpeg, .jpg, .doc, .docx"}) => {

    const [uploading, setUploading] = useState(false);
    const [selectedFile, setSelectedFile] = useState(null);

    const [AtomBRF, setAtomBRF] = useRecoilState(formAtom);

    const [fileNameLabel, setFileNameLabel] = useState(fileUploadLableText);

    // console.log( AtomBRF.brd_file, typeof AtomBRF.brd_file, AtomBRF.brd_file === null );
    const tempArr = useRef((AtomBRF.brd_file !== undefined && AtomBRF.brd_file !== null && AtomBRF.brd_file.length > 0) ? AtomBRF.brd_file.split(',') : []);

    const handleFileChange = (e) => {

        if (e.target.files[0].size > 10000000) {
            clearSeletedFiles();
            return invalidURLAlert(`Error`, "File upload file less than 10MB", "", false);
        }
        const file = e.target.files[0];

        console.log(e.target.files[0].size)
        setSelectedFile(file);
        setFileNameLabel(file ? file.name : fileUploadLableText);
    };

    const clearSeletedFiles = () => {
        setSelectedFile(null);
        setFileNameLabel(fileUploadLableText);
    }

    const handleFileUploadHSI = async () => {
        if (!selectedFile) {
            return invalidURLAlert("Upload Error", "Please select a document to upload.");
        }

        setUploading(true);
        try {
            const formData = new FormData();
            formData.append("file", selectedFile);

            axiosInstance({
                method: "post",
                url: "uploadFile_BRF",
                data: formData,
                headers: {
                    "Content-Type": "multipart/form-data",
                    email: getCookie("email2"),
                    resourceId: getCookie("resourceId"),
                    "access-token": getCookie("token"),
                    Authorization: `Bearer ${getCookie("token")}`,
                }
            }).then(function (response) {
                // console.log('Data =>', response.data.data);
                tempArr.current.push(response.data.data);
                const xArr = tempArr;


                // console.log('tempArr =>', tempArr.current);

                successAndGoBackAlert("Success", "File uploaded successfully!", false);

                console.log('tempArr =>', tempArr.current, tempArr.current.toString());

                clearSeletedFiles();

                setAtomBRF(prevState => ({
                    ...prevState,
                    brd_file: tempArr.current.toString()

                }));

                setUploading(false);

            }).catch(function (error) {
                console.error(error);
                setUploading(false);
            });


        } catch (err) {
            console.log("file upload failed : " + err.status);
            if (err.response && err.response.status === 400) {
                alert("Please upload the appropriate file.");
            } else {
                alert("File upload failed. Please try again.");
            }

            setUploading(false);
        }
    };

    return useMemo(() => {
        return (<>
            {
                tempArr.current.length > 0 && <Divider textAlign="left" sx={{mt: 2}}>
                    <Typography className={'greenText'} fontSize={14} fontWeight="bold">Uploaded Documents</Typography>
                </Divider>
            }

            {displayDownloadableFilesLinks(tempArr.current)}

            <Divider textAlign="left" sx={{mb: 1}}>
                <Typography className={'greenText'} fontSize={14} fontWeight="bold">{labelText}</Typography>
            </Divider>

            <Stack
                direction={{xs: "column", md: "row"}}
                justifyContent="space-around"
                alignItems={{xs: "flex-start", md: "center"}}

            >

                {uploading ?
                    (<Grid sx={{mt: 2}}>
                        Uploading please wait ... <CircularProgress size={16} color="success"/>
                    </Grid>) : (
                        <>
                            {/*//         <Typography*/}
                            {/*    //     sx={{*/}
                            {/*    //         fontSize: "15px",*/}
                            {/*    //         fontWeight: "600",*/}
                            {/*    //         fontFamily: "Poppins",*/}
                            {/*    //         marginRight: "10px",*/}
                            {/*    //     }}*/}
                            {/*    // >*/}
                            {/*    //     Upload BRF Docs Here*/}
                            {/*    // </Typography>*/}
                            <input
                                type="file"
                                // accept="application/pdf,application/vnd.ms-excel"
                                accept={acceptedFiles}
                                onChange={handleFileChange}
                                style={{
                                    height: "45px",
                                    flexShrink: 0,
                                    borderRadius: "5px",
                                    border: "1px dashed rgba(0, 0, 0, 0.46)",
                                    display: "none",
                                    padding: "10px",
                                }}
                                id="fileInput"
                            />
                            <label
                                htmlFor="fileInput"
                                className="upload-button"
                                style={{
                                    color: "#A4A4A4",
                                    fontSize: "12px",
                                    fontWeight: "100",
                                    display: "inline-block",
                                    cursor: "pointer",
                                    textAlign: "center",
                                    height: "38px",
                                    flexShrink: 0,
                                    borderRadius: "7.69px",
                                    border: "0.96px solid #D0D5DD",
                                    lineHeight: "38px",
                                    fontFamily: "Poppins",
                                    paddingLeft: "10px",
                                    paddingRight: "10px",
                                }}
                            >
                                {fileNameLabel}
                            </label>
                            <Button
                                variant="contained"
                                startIcon={<img src={uploadcld} alt="upload Icon"/>}
                                onClick={handleFileUploadHSI}
                                sx={{
                                    textTransform: "capitalize",
                                    backgroundColor: "#065036",
                                    height: "38px",
                                    fontSize: "14px",
                                    fontFamily: "Poppins",
                                    lineHeight: "0px",
                                    display: "flex",
                                    justifyItems: "flex-start",
                                    marginLeft: {md: "10px", xs: "0px"},
                                    marginTop: {md: "0", xs: "10px"},
                                    "&:hover": {
                                        backgroundColor: "#333",
                                    },
                                }}
                            >
                                Upload
                            </Button>
                        </>

                    )}

            </Stack>
        </>)
            ;
    }, [selectedFile, fileNameLabel, uploading]);
};
