import React, {useState} from "react";
import {
    Typography,
    Box,
    Button,
    Grid,
    Tooltip,
    tooltipClasses,
    Toolbar,
} from "@mui/material";
import CssBaseline from "@mui/material/CssBaseline";
import styled from "@emotion/styled";
import DrawerComp from "../Drawer/drawer";
import Header from "../Header/MainHeader";
import eyeI from "../../Assets/eye.svg";
import info from "../../Assets/whiteInfo.svg";
import eyevisible from "../../Assets/eyevisible.svg";
import axiosInstance from "../../Services/AxiosInstance";
import {getCookie} from "../../Services/Cookies";
import {useNavigate} from "react-router-dom";
import {invalidURLAlert, successAndGoBackAlert} from "../../RAS_updates/Heplers";

export const UpdatePassword = () => {
    const BootstrapTooltip = styled(({className, ...props}) => (
        <Tooltip {...props} arrow classes={{popper: className}}/>
    ))(({theme}) => ({
        [`& .${tooltipClasses.arrow}`]: {
            color: "white",
        },
        [`& .${tooltipClasses.tooltip}`]: {
            backgroundColor: "white",
            color: "#065036",
        },
    }));

    const [newPassword, setNewPassword] = useState("");
    const [confirmPassword, setConfirmPassword] = useState("");
    const [oldPassword, setOldPassword] = useState("");
    const [showOldPassword, setShowOldPassword] = useState(false);
    const [showNewPassword, setShowNewPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [tooltipOpen, setTooltipOpen] = useState(false);
    const email = getCookie("email2");

    // Validation states
    const [isValidPass, setIsValidPass] = useState(true);
    const [isConfirmMatch, setIsConfirmMatch] = useState(true);
    const [key1, setKey1] = useState(
        "wVgGhlIOKAnFRleHQgdG8gQmFzZTY04oCdIGNvbnZlcnRlciBpcyBhIHNpbXBsZSBlbmNvZGVyIHRvb2wgdGhhdCBhbGxvd3MgeW91IHRvIGNvbnZlcnQgb25saW5lIHRleHQgdG8gQmFzZTY0ICh0aGF0IGlzLCBpdCBlbmNvZGVzIGFueSB0ZXh0dWFsIGNoYXJhY3RlcnMgaW50byBhIGJhc2ljIEFTQ0lJIHN0cmluZyku"
    );
    const [key2, setKey2] = useState(
        "wRG8geW91IGhhdmUgdG8gZGVhbCB3aXRoIEJhc2U2NCBmb3JtYXQ/IFRoZW4gdGhpcyBzaXRlIGlzIHBlcmZlY3QgZm9yIHlvdSEgVXNlIG91ciBzdXBlciBoYW5keSBvbmxpbmUgdG9vbCB0byBlbmNvZGUgb3IgZGVjb2RlIHlvdXIgZGF0YXNldC4u"
    );
    // Password validation pattern
    const passwordPattern = /^(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,20}$/;

    // Tooltip toggle
    const handleTooltipToggle = () => setTooltipOpen((prev) => !prev);

    // Handle password change and validate
    const handleNewPasswordChange = (e) => {
        const value = e.target.value;
        setNewPassword(value);
        setIsValidPass(passwordPattern.test(value));
        setIsConfirmMatch(value === confirmPassword);
    };

    const handleConfirmPasswordChange = (e) => {
        const value = e.target.value;
        setConfirmPassword(value);
        setIsConfirmMatch(newPassword === value);
    };

    const handleOldPasswordChange = (e) => {
        setOldPassword(e.target.value);
    };

    const navigate = useNavigate();

    // Reset all fields
    const handleCancel = () => {
        setOldPassword("");
        setNewPassword("");
        setConfirmPassword("");
        setIsValidPass(true);
        setIsConfirmMatch(true);
    };

    // Submit handler
    const handleResetPassword = async () => {
        if (!oldPassword || !newPassword || !confirmPassword) {
            // alert("Please fill in all fields.");
            invalidURLAlert('Error', "Please fill in all fields.", "", false)
            return;
        }
        if (oldPassword === newPassword) {
            invalidURLAlert('Error', "New password should not be same as old password.", "", false)
            return;
        }
        if (!isValidPass) {
            invalidURLAlert('Error', "New password format is invalid.", "", false)
            alert();
            return;
        }
        if (!isConfirmMatch) {
            invalidURLAlert('Error', "Passwords do not match.", "", false)
            return;
        }

        const encodedOldPassword = btoa(oldPassword);
        const encodedNewPassword = btoa(newPassword);
        const encodedConfirmPassword = btoa(confirmPassword);

        const finalOldPassword = key1 + encodedOldPassword + key2;
        const finalNewPassword = key1 + encodedNewPassword + key2;
        const finalConfirmPassword = key1 + encodedConfirmPassword + key2;

        if (isValidPass) {

            axiosInstance
                .post("/update-password", {
                    email: email,
                    oldPassword: finalOldPassword,
                    newPassword: finalNewPassword,
                    confirmNewPassword: finalConfirmPassword,
                })
                .then((response) => {
                    console.log(" successfully getting the response :", response);
                    const message = response.data.message || "No response provided";

                    console.log("Response message:", response);
                    if (response.status === 200) {
                        // alert(message);
                        successAndGoBackAlert('Success', message.toString(), true)
                    } else if (response.status === 401) {
                        alert(message);
                    } else if (response.status === 404) {
                        alert(message);
                    } else {
                    }
                })
                .catch((error) => {
                    alert(
                        `${error.response.data.errorMessage}`
                    );

                });
        } else {
            return;
        }
        handleCancel();
    };

    return (
        <div style={{overflowX: "hidden"}}>
            <style>
                {`
          .css-10hburv-MuiTypography-root{
            font-size:11px !important;
            font-family: Poppins 
          }
          .css-yb0lig{
            font-size:12px !important
          }
        `}
            </style>
            <Box sx={{display: "flex"}}>
                <CssBaseline/>
                <Header/>
                <DrawerComp listName={""}/>
                <Box
                    component="main"
                    sx={{flexGrow: 1, p: {xs: "10px", md: "24px"}, backgroundColor: "#f4faf8"}}
                >
                    <Toolbar/>
                    <Box
                        sx={{
                            maxWidth: 400,
                            mx: "auto",
                            mt: 6,
                            bgcolor: "#065036",
                            boxShadow: 3,
                            p: 4,
                            borderRadius: "8px",
                        }}
                    >
                        <Typography
                            variant="h6"
                            component="h2"
                            sx={{mb: 3, textAlign: "center", fontWeight: "bold", color: "white"}}
                        >
                            Change Password
                        </Typography>

                        {/* Old Password Field */}
                        <Grid container spacing={1} mt={2}>
                            <Grid item xs={12}>
                                <label style={{color: "white"}}>Old Password</label>
                                {!isValidPass && (
                                    <BootstrapTooltip
                                        open={tooltipOpen}
                                        onClose={handleTooltipToggle}
                                        title={
                                            <span>
                        1) Password should contain 8 to 12 characters.
                        <br/>
                        2) It should contain at least one number, uppercase, and one special character.
                      </span>
                                        }
                                        arrow
                                    >
                                        <Button sx={{padding: "0px", minWidth: "0px"}} onClick={handleTooltipToggle}>
                                            <img alt="info" src={info} style={{marginLeft: "5px"}}/>
                                        </Button>
                                    </BootstrapTooltip>
                                )}
                            </Grid>
                            <Grid item xs={12}>
                                <div style={{
                                    position: "relative",
                                    display: "inline-block",
                                    width: "100%",
                                    marginTop: "-5px"
                                }}>
                                    <input
                                        id="old-password"
                                        className="custom-input"
                                        placeholder="Enter your old password here"
                                        type={showOldPassword ? "text" : "password"}
                                        value={oldPassword}
                                        onChange={handleOldPasswordChange}
                                        style={{
                                            backgroundColor: "#38735e",
                                            width: "100%",
                                            height: "50px",
                                            borderRadius: "7.69px",
                                            border: "1px solid #38735e",
                                            outline: "none",
                                            paddingRight: "40px",
                                            padding: "10px",
                                            color: "#FFFFFF",
                                        }}
                                    />
                                    <img
                                        src={showOldPassword ? eyevisible : eyeI}
                                        alt="icon"
                                        style={{
                                            position: "absolute",
                                            top: "50%",
                                            transform: "translateY(-50%)",
                                            right: "10px",
                                            height: "auto",
                                            cursor: "pointer",
                                            width: "20px",
                                        }}
                                        onClick={() => setShowOldPassword(!showOldPassword)}
                                    />
                                </div>
                            </Grid>
                        </Grid>

                        {/* New Password Field */}
                        <Grid container spacing={1} mt={2}>
                            <Grid item xs={12}>
                                <label style={{color: "white"}}>New Password</label>
                                {!isValidPass && (
                                    <BootstrapTooltip
                                        open={tooltipOpen}
                                        onClose={handleTooltipToggle}
                                        title={
                                            <span>
                        1) Password should contain 8 to 12 characters.
                        <br/>
                        2) It should contain at least one number, uppercase, and one special character.
                      </span>
                                        }
                                        arrow
                                    >
                                        <Button sx={{padding: "0px", minWidth: "0px"}} onClick={handleTooltipToggle}>
                                            <img alt="info" src={info} style={{marginLeft: "5px"}}/>
                                        </Button>
                                    </BootstrapTooltip>
                                )}
                            </Grid>
                            <Grid item xs={12}>
                                <div style={{
                                    position: "relative",
                                    display: "inline-block",
                                    width: "100%",
                                    marginTop: "-5px"
                                }}>
                                    <input
                                        id="new-password"
                                        className="custom-input"
                                        placeholder="Enter your new password here"
                                        type={showNewPassword ? "text" : "password"}
                                        value={newPassword}
                                        onChange={handleNewPasswordChange}
                                        style={{
                                            backgroundColor: "#38735e",
                                            width: "100%",
                                            height: "50px",
                                            borderRadius: "7.69px",
                                            border: isValidPass ? "1px solid #38735e" : "2px solid red",
                                            outline: "none",
                                            paddingRight: "40px",
                                            padding: "10px",
                                            color: "#FFFFFF",
                                        }}
                                    />
                                    <img
                                        src={showNewPassword ? eyevisible : eyeI}
                                        alt="icon"
                                        style={{
                                            position: "absolute",
                                            top: "50%",
                                            transform: "translateY(-50%)",
                                            right: "10px",
                                            height: "auto",
                                            cursor: "pointer",
                                            width: "20px",
                                        }}
                                        onClick={() => setShowNewPassword(!showNewPassword)}
                                    />
                                </div>
                            </Grid>
                            {!isValidPass && (
                                <p style={{color: "#ff0000", margin: "2px 0px 0px 10px", fontSize: "12px"}}>
                                    Invalid Format. Please check info icon.
                                </p>
                            )}
                        </Grid>

                        {/* Confirm Password Field */}
                        <Grid container spacing={1} mt={2}>
                            <Grid item xs={12}>
                                <label style={{color: "white"}}>Confirm New Password</label>
                            </Grid>
                            <Grid item xs={12}>
                                <div style={{
                                    position: "relative",
                                    display: "inline-block",
                                    width: "100%",
                                    marginTop: "-5px"
                                }}>
                                    <input
                                        id="confirm-password"
                                        className="custom-input"
                                        placeholder="Confirm your new password"
                                        type={showConfirmPassword ? "text" : "password"}
                                        value={confirmPassword}
                                        onChange={handleConfirmPasswordChange}
                                        style={{
                                            backgroundColor: "#38735e",
                                            width: "100%",
                                            height: "50px",
                                            borderRadius: "7.69px",
                                            border: isConfirmMatch ? "1px solid #38735e" : "2px solid red",
                                            outline: "none",
                                            paddingRight: "40px",
                                            padding: "10px",
                                            color: "#FFFFFF",
                                        }}
                                    />
                                    <img
                                        src={showConfirmPassword ? eyevisible : eyeI}
                                        alt="icon"
                                        style={{
                                            position: "absolute",
                                            top: "50%",
                                            transform: "translateY(-50%)",
                                            right: "10px",
                                            height: "auto",
                                            cursor: "pointer",
                                            width: "20px",
                                        }}
                                        onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                    />
                                </div>
                            </Grid>
                            {!isConfirmMatch && (
                                <p style={{color: "#ff0000", margin: "2px 0px 0px 10px", fontSize: "12px"}}>
                                    Passwords do not match.
                                </p>
                            )}
                        </Grid>

                        {/* Buttons */}
                        <Grid container spacing={2} mt={3}>
                            <Grid item xs={6}>
                                <Button
                                    variant="outlined"
                                    fullWidth
                                    onClick={() => {handleCancel(); navigate(-1);}}
                                    sx={{textTransform: "capitalize", color: "white", borderColor: "white"}}
                                >
                                    Cancel
                                </Button>
                            </Grid>
                            <Grid item xs={6}>
                                <Button
                                    variant="contained"
                                    fullWidth
                                    onClick={handleResetPassword}
                                    sx={{
                                        backgroundColor: "white",
                                        color: "#065036",
                                        textTransform: "capitalize",
                                        "&:hover": {
                                            backgroundColor: "#f5f5f5",
                                        },
                                    }}
                                >
                                    Change Password
                                </Button>
                            </Grid>
                        </Grid>
                    </Box>
                </Box>
            </Box>
        </div>
    );
};