import React, { useEffect, useState } from 'react';
import { useRecoilState, useSetRecoilState, useRecoilValue } from 'recoil';
import {
  siWOTableAtom,
  siWODataAtom,
  siTotalSancMasterAtom,
  siWOMasterAtom,
  modeSiWODataAtom,
  siFilterAtom,
  genUUID,
  siGlobalModeAtom,
  siUpdateFormDataAtom,
  siTotalSancMasterTableAtom,
  siWOMasterTableAtom,
  globalSiIdAtom

} from '../../RAS_updates/Heplers';
import { Card, Divider, Pagination, Box } from '@mui/material';
import '../SIPayments/SiTable.css';
import { useParams } from 'react-router-dom';
import axiosInstance from '../../Services/AxiosInstance';
import { Navigate, useNavigate } from 'react-router-dom';
import { renderSubmitErrorAlert } from '../../RAS_updates/Heplers';
export const SiNameTable = ({ page, size }) => {
  const [siList, setSiList] = useRecoilState(siWOTableAtom);
  const [form,setForm] = useRecoilState(siWODataAtom);
  const setMode = useSetRecoilState(modeSiWODataAtom);
  const setGlobalMode = useSetRecoilState(siGlobalModeAtom);
  const filters = useRecoilValue(siFilterAtom);
  // const setFieldAtom = useSetRecoilState(siUpdateFormDataAtom);
  const setTotalSancList = useSetRecoilState(siTotalSancMasterTableAtom);
  const setWOList = useSetRecoilState(siWOMasterTableAtom);
  const [SiTotalSancMaster, setSiTotalSancMaster] = useRecoilState(siTotalSancMasterAtom);
  const [siWoMaster,setSiWOMaster] = useRecoilState(siWOMasterAtom);
  const [globalSiId,setGlobalSiId] = useRecoilState(globalSiIdAtom);
  const navigate = useNavigate();
  
  const handleSiClick = async (row) => {
    navigate("/sipaymentsmaster/update");
    try {
      const res = await axiosInstance.post(   `/siMaster/SiSubClasses`, {}, // Empty body
  { params: { siId: row.siId } } );

      if (res.status === 200 && res.data?.siMaster) {
        // Set SI Card Atom
      setForm({
            siName: row.siName,
            siId: row.siId,
            ...res.data.siMaster,
          });
          setGlobalSiId(row.siId); // Set global SI ID atom

        // Set Total Sanc List Atom
        // Set Total Sanc Master Atom with the first object
        if (res.data.siTotalSancList && res.data.siTotalSancList.length > 0) {
          setSiTotalSancMaster(res.data.siTotalSancList[0]); // First object
          setTotalSancList(res.data.siTotalSancList); // Full array for table
        }

        // Set SI WO Master Atom with the first object
        if (res.data.siWOList && res.data.siWOList.length > 0) {
          setSiWOMaster(res.data.siWOList[0]); // First object
          setWOList(res.data.siWOList); // Full array for table
        }
        
      } else {
        renderSubmitErrorAlert(res.data?.error || "Operation failed");
      }

    } catch (err) {
      console.error("Fetch error:", err);
      renderSubmitErrorAlert("Something went wrong");
    }

  };
// console.log("avlu of siname card", form)
// console.log("SiTotalSancMaster:", SiTotalSancMaster);
// console.log(" SiTotalSancMaster:", SiTotalSancMaster)
// console.log("siWoMaster:", siWoMaster);
  
return (
    <div style={{ width: '100%' }}>
      <Card className="cusTable" >
        {/* Desktop Table */}
        <table className="desktopTable">
          <thead>
            <tr>
              <th>Sno.</th>
              <th>SI Name</th>
              <th>SI Type</th>
              <th>Total Sanc PACs</th>
              <th>States</th>
            </tr>
          </thead>
          <tbody>
            {(Array.isArray(siList) ? siList : []).map((row, idx) => (
              <tr key={genUUID()}>
                <td>{page * size + idx + 1}</td>
                <td>
                  <span
                    className="dataListingCUI"
                    style={{
                      color: '#1976d2',
                      cursor: 'pointer',
                      textDecoration: 'underline'
                    }}
                    onClick={() => handleSiClick(row)}
                  >
                    {row.siName}
                  </span>
                </td>
                <td>{row.siType}</td>
                <td>{row.totalSancPacs}</td>
                <td>{row.states}</td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Mobile Table */}
        <div className="mobileTable">
          {siList.map((row, idx) => (
            <div key={genUUID()} className="responsiveTableRow">
              <div className="rowItem">
                <span>Sno.</span>
                <span>{page * size + idx + 1}</span>
              </div>
              <Divider className="mobileRowDivider" />

              <div className="rowItem">
                <span>SI Name</span>
                <span
                  className="dataListingCUI"
                  style={{ color: '#1976d2', cursor: 'pointer', textDecoration: 'underline' }}
                  onClick={() => handleSiClick(row)}
                >
                  {row.siName}
                </span>
              </div>
              <Divider className="mobileRowDivider" />

              <div className="rowItem">
                <span>SI Type</span>
                <span>{row.siType}</span>
              </div>
              <Divider className="mobileRowDivider" />

              <div className="rowItem">
                <span>Total Sanc PACs</span>
                <span>{row.totalSancPacs}</span>
              </div>
              <Divider className="mobileRowDivider" />

              <div className="rowItem">
                <span>States</span>
                <span>{row.states}</span>
              </div>
              <Divider className="mobileRowDivider" />
            </div>
          ))}
        </div>

      </Card>
    </div>
  );
};