import React, { useEffect } from "react";
import { useRecoilState, useSetRecoilState } from "recoil";
import { siWOMasterTableAtom, siWOMasterAtom, modeSiWOMasterAtom } from "../../RAS_updates/Heplers";
import { Card, Divider } from "@mui/material";
import axiosInstance from "../../Services/AxiosInstance";
import moment from "moment";
import "../SIPayments/SiTable.css";
import { displayDownloadableFilesLinks } from "../../RAS_updates/Heplers/genFuns";
const genUUID = () => Math.random().toString(36).substring(2, 10);

export const SiWOMasterTable = ({ page = 0, size = 10 }) => {
  const [tableData, setTableData] = useRecoilState(siWOMasterTableAtom);
  const setSelectedRow = useSetRecoilState(siWOMasterAtom);
  const setMode = useSetRecoilState(modeSiWOMasterAtom);


  // const fetchData = async () => {
  //   try {
  //     const res = await axiosInstance.post("/siWOMaster/all");
  //     if (res.status === 200 && Array.isArray(res.data.data)) {
  //       setTableData(res.data.data);
  //     } else {
  //       setTableData([]);
  //     }
  //   } catch (err) {
  //     setTableData([]);
  //   }
  // };

  // useEffect(() => {
  //   fetchData();
  //   // eslint-disable-next-line
  // }, [setTableData]);

  if (!Array.isArray(tableData) || tableData.length === 0) {
    return <p>No data submitted yet.</p>;
  }

  const handleRowClick = (row) => {
    setSelectedRow(row);
    setMode("edit");
  };

  const getStateLabel = (stateUtObj) => {
    if (stateUtObj && typeof stateUtObj === "object") {
      return `${stateUtObj.name} (${stateUtObj.short_name} - ${stateUtObj.code})`;
    }
    return "—";
  };

  return (
    <Card className="cusTable" sx={{ mt: 2, overflowX: 'auto' }}>
      <div style={{ minWidth: '1000px' }}>
        <table className="desktopTable">
          <thead>
            <tr>
              <th>Sno.</th>
              <th>SI WO No</th>
              <th>State/UT</th>
              <th>WO Date</th>
              <th>WO Doc</th>
              <th>WO Value</th>
              <th>Onboarded On</th>
              <th>Contact Number</th>
              <th>Contact Mail</th>
            </tr>
          </thead>
          <tbody>
            {tableData.slice(page * size, page * size + size).map((row, idx) => (
              <tr key={genUUID()}>
                <td>{page * size + idx + 1}</td>

                <td>
                  <span
                    style={{ color: "#1976d2", cursor: "pointer", textDecoration: "underline" }}
                    onClick={() => handleRowClick(row)}
                  > {row.siWONo ?? "—"}
                  </span>
                </td>
                <td>
                  {row.stateUT && getStateLabel(row.stateUT)}
                </td>
                <td>{row.siWODate ? moment(row.siWODate).format("MM/DD/YYYY") : "—"}</td>
                <td >
                  {row.siWODoc && row.siWODoc.includes(':#:')
                    ? displayDownloadableFilesLinks(row.siWODoc.split(','))
                    : (row.siWODoc ?? "—")}
                </td>
                <td>{row.siWOValue ?? "—"}</td>
                <td>{row.onboardedOn ? moment(row.onboardedOn).format("MM/DD/YYYY") : "—"}</td>
                <td>{row.contactNumber ?? "—"}</td>
                <td>{row.contactMail ?? "—"}</td>
              </tr>
            ))}
          </tbody>
        </table>
        {/* Mobile stacked rows */}
        <div className="mobileTable">
          {tableData.slice(page * size, page * size + size).map((row, idx) => (
            <div key={genUUID()} className="responsiveTableRow">
              <div className="rowItem"><span>Sno.</span><span>{page * size + idx + 1}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>SI WO No</span><span>{row.siWONo ?? "—"}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>State/UT</span>
                <span>
                  {row.stateUT && getStateLabel(row.stateUT) || "—"}
                </span>
              </div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>WO Date</span><span>{row.siWODate ? moment(row.siWODate).format("MM/DD/YYYY") : "—"}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>WO Doc</span>
                <span>
                  {row.siWODoc && row.siWODoc.includes(':#:')
                    ? displayDownloadableFilesLinks(row.siWODoc.split(','))
                    : (row.siWODoc ?? "—")}
                </span>
              </div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>WO Value</span><span>{row.siWOValue ?? "—"}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>Onboarded On</span><span>{row.onboardedOn ? moment(row.onboardedOn).format("MM/DD/YYYY") : "—"}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>Contact Number</span><span>{row.contactNumber ?? "—"}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>Contact Mail</span><span>{row.contactMail ?? "—"}</span></div>
              <Divider className="mobileRowDivider" />
            </div>
          ))}
        </div>
      </div>
    </Card>

  );
};