// helpers/DuplicateStateErrorAlert.ts
import { useEffect } from "react";
import Swal from "sweetalert2";
import { useNavigate } from "react-router-dom";

export const useDuplicateStateErrorAlert = (
 errorMessage,
 showAlert,
 setShowAlert
) => {
 const navigate = useNavigate();

 useEffect(() => {
  console.log("useDuplicateStateErrorAlert triggered");
  if (!showAlert || !errorMessage) return;

  const extractedId = errorMessage?.match(/ID:\s*(\d+)/)?.[1];
  console.log("Extracted ID:", extractedId);
  Swal.fire({
   icon: "error",
   title: "State Already Exists",
   text: "Please update the existing record.",
   showCancelButton: true,
   confirmButtonText: "Go to Update Form",
   cancelButtonText: "Close",
   confirmButtonColor: "#4CAF50",
   cancelButtonColor: "#ed6c02",
   allowOutsideClick: false,
   allowEscapeKey: false,
   backdrop: true,
  }).then((result) => {
   setShowAlert(false); // reset alert
   if (result.isConfirmed && extractedId) {
    navigate(`/sipaymentsfundsupdate/update/${extractedId}`);
   } else {
    navigate(-1);
   }
  });
 }, [errorMessage, showAlert, navigate, setShowAlert]);
};
