import React, {useEffect} from "react";
import Box from "@mui/material/Box";
import {CssBaseline, Toolbar, Grid} from "@mui/material";
import DrawerComp from "../../Components/Drawer/drawer";
import MainHeader from "../../Components/Header/MainHeader";
import {SiWOHeaderComponnent} from "./SiWOHeaderComponent";
import SiNameCard from "./SiNameCard";
import SiTotalSancMasterCard from "./SiTotalSancMaster";
import SiWOMasterForm from "./SiWOMasterCard";
import SiMasterSearchForm from "../SiWorkOrder/SiMasterSearchForm"
import {UnderDevAlert} from "../../RAS_updates/Pages/CustomizationRequest/Components";

export default function SiMasterSearch() {
    useEffect(() => {
        window.scrollTo({
            top: 0,
            left: 0,
            behavior: "smooth",
        });
    }, []);
    return (
        <div style={{overflowX: "hidden"}}>
            <style>
                {`
            .css-10hburv-MuiTypography-root{
              font-size:11px !important;
              font-family: Poppins 
            }
            .css-yb0lig{
              font-size:12px !important
            }
            `}
            </style>
            <Box sx={{display: "flex"}}>
                <CssBaseline/>
                <MainHeader/>
                <DrawerComp listName={"SI Master"}/>
                <Box
                    component="main"
                    sx={{
                        flexGrow: 1,
                        backgroundColor: "#f4faf8",
                        p: 1
                    }}>
                    <Toolbar/>
                    <UnderDevAlert/>


                    <Grid
                        item
                        container
                        spacing={2}
                        xs={12}
                        sx={{
                            mt: "1.5%",
                            pl: "-0.5%",
                        }}
                    >
                        <SiWOHeaderComponnent/>
                        <SiMasterSearchForm/>

                    </Grid>
                </Box>
            </Box>
        </div>
    );
}
