import React, {useMemo} from "react";

import ManageSearchOutlinedIcon from "@mui/icons-material/ManageSearchOutlined";
import {Button, Card, Grid, TextField, Typography} from "@mui/material";
import {
    cusReqAgeingListAtom,
    cusReqAssignedToFilterListAtom,
    cusReqBucketListAtom,
    cusReqDataListingAtom,
    cusReqFilterFormAtom,
    cusReqPriorityListAtom,
    cusReqShowstopperAuditFilterListAtom, cusReqShowstopperDayendFilterListAtom,
    cusReqStateListAtom,
    cusReqStatusListAtom, FIELDVISIT_LINK, isARDBCusReqTabActive,
    isEmptyObject, overViewTabAtom,
    pageLoadingAtom,
    paramsFromURL,
    stakeholderArr, stakeholderArrARDB,
    useRecoilState, useRecoilValue,
    useSetRecoilState,
    yesNoArr
} from "../../../../Heplers";
import {CusReqDropdown} from "./../CusReqDropdown";
import {useNavigate} from "react-router-dom";
import {APICallDataListing} from "../../CustomizationRequestListing";
import {RestartAltRounded} from "@mui/icons-material";

function TotalRecords() {

    const [dLAtom, setdLAtom] = useRecoilState(cusReqDataListingAtom);

    return useMemo(() => {

        return (
            <Grid
                container
                item
                md={6}
                sx={{p: 1}}
                display="flex"
                direction={"row"}
                justifyContent="flex-start"
                alignItems="end"
            >
                <Typography className={'greenText'} fontSize={11} fontWeight="bold">
                    Total Records:</Typography>
                <Typography fontSize={12} className="fontGreenTheme bold">{dLAtom.totalRecords}</Typography>
            </Grid>
        );
    }, [dLAtom.totalRecords]);
}

export default function CusReqFilterOptions() {
    const URLParams = paramsFromURL({
        linkToSplit: `${FIELDVISIT_LINK}listing/`,
    })
    const [Atom, setAtom] = useRecoilState(cusReqFilterFormAtom);


    const navigate = useNavigate();

    const setPageLoading = useSetRecoilState(pageLoadingAtom);
    const [dLAtom, setdLAtom] = useRecoilState(cusReqDataListingAtom);

    const cusReqTabIndex = useRecoilValue(overViewTabAtom);

    const filterDataListing = (reset = false) => {

        // Stages Limit Offset
        const {paramId, paramId1, paramId2} = paramsFromURL({
            linkToSplit: `${FIELDVISIT_LINK}listing/`,
        })

        const {
            status,
            searchtext,
            priority,
            state,
            ageing,
            bucket,
            showstopper_audit,
            showstopper_dayend,
            assigned_to
        } = Atom

        //Offset should be set to Zero 0 as whenever in clicked first page should be displayed
        let filterURL = `/${FIELDVISIT_LINK}listing/${paramId}/${paramId1}/0/`;

        // console.log(Atom, searchtext, String(searchtext).length);

        if (!reset) {
            if (searchtext === undefined || String(searchtext).length === 0)
                filterURL = filterURL + "all/"
            else
                filterURL = filterURL + `${searchtext}/`

            if (bucket === undefined || isEmptyObject(bucket))
                filterURL = filterURL + "all/"
            else
                filterURL = filterURL + `${String(bucket.id)}/`

            if (state === undefined || isEmptyObject(state))
                filterURL = filterURL + "all/"
            else
                filterURL = filterURL + `${String(state.code)}/`

            if (priority === undefined || isEmptyObject(priority))
                filterURL = filterURL + "all/"
            else
                filterURL = filterURL + `${String(priority.id)}/`

            if (ageing === undefined || isEmptyObject(ageing))
                filterURL = filterURL + "all/"
            else
                filterURL = filterURL + `${String(ageing.days)}/`

            // Status in UI means inputs_closed in DB Yes - Closed || No - Pending
            if (status === undefined || isEmptyObject(status)) {
                filterURL = filterURL + "all/"
            } else if (!isEmptyObject(status)) {
                if (status.id === 1) {
                    // Pending
                    filterURL = filterURL + "No/"
                } else {
                    // Closed
                    filterURL = filterURL + "Yes/"
                }
            }

            if (showstopper_audit === undefined || isEmptyObject(showstopper_audit))
                filterURL = filterURL + "all/"
            else
                filterURL = filterURL + `${String(showstopper_audit.id)}/`

            if (showstopper_dayend === undefined || isEmptyObject(showstopper_dayend))
                filterURL = filterURL + "all/"
            else
                filterURL = filterURL + `${String(showstopper_dayend.id)}/`

            if (assigned_to === undefined || isEmptyObject(assigned_to))
                filterURL = filterURL + "all/"
            else
                filterURL = filterURL + `${String(assigned_to.id)}/`
        }

        if(reset){
            setAtom({})
            document.getElementById("searchtext").value = "";
        }
        navigate(filterURL, {replace: true})

        APICallDataListing({
            setLoading: setPageLoading,
            setAtom: setdLAtom,
            is_ardb: isARDBCusReqTabActive(cusReqTabIndex)
        });


    };

    return useMemo(() => {
        const defValCusBuc =
            (URLParams.paramId4 !== undefined && URLParams.paramId4 !== "all")
                // ? JSON.parse(decodeURIComponent(URLParams.paramId3))
                ? URLParams.paramId4
                : {};

        const defValState =
            (URLParams.paramId5 !== undefined && URLParams.paramId5 !== "all")
                ? URLParams.paramId5
                : {};

        const defValPri =
            (URLParams.paramId6 !== undefined && URLParams.paramId6 !== "all")
                ? URLParams.paramId6
                : {};


        const defValAgeing =
            (URLParams.paramId7 !== undefined && URLParams.paramId7 !== "all")
                ? URLParams.paramId7
                : {};

        const defValStatus =
            (URLParams.paramId8 !== undefined && URLParams.paramId8 !== "all")
                ? URLParams.paramId8 === 'No' ? 1 : 2
                : {};

        const defValShowstopperDayend =
            (URLParams.paramId9 !== undefined && URLParams.paramId9 !== "all")
                ? URLParams.paramId9
                : {};

        const defValShowstopperAudit =
            (URLParams.paramId10 !== undefined && URLParams.paramId10 !== "all")
                ? URLParams.paramId10
                : {};

        const defValAssigned =
            (URLParams.paramId11 !== undefined && URLParams.paramId11 !== "all")
                ? URLParams.paramId11
                : {};


        return <><Typography>Search Options in development</Typography></>
        // console.log("URLParams", URLParams);
        return (
            <Card sx={{pt: 2, mt: 2, width: "100%"}} className={"greenBorder CusReqFilterOptionsCard"}>
                <Grid item container>
                    {/* <Grid item xs={12}>
          <Divider textAlign="right">Advance Filter Options</Divider>
        </Grid> */}

                    <Grid item md={4} xs={12} sx={{p: 1}}>
                        <TextField
                            id="searchtext"
                            variant="outlined"
                            label="CUI / Decription"
                            fullWidth
                            InputLabelProps={{
                                shrink: true,
                            }}
                            onChange={(e) => setAtom((prevState) => ({
                                ...prevState,
                                searchtext: e.target.value

                            }))}
                            defaultValue={URLParams.paramId3 === 'all' ? null : URLParams.paramId3}
                        />
                    </Grid>

                    <Grid item md={4} xs={12} sx={{p: 1}}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqFilterFormAtom}
                            listDataAtom={cusReqBucketListAtom}
                            ddLabel="Bucket"
                            dropdownName={"bucket"}
                            fetchMasterDataURL="fetchBucketMasterData_CusReq"
                            defVal={defValCusBuc}
                        />
                    </Grid>


                    <Grid item md={4} xs={12} sx={{p: 1}}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqFilterFormAtom}
                            listDataAtom={cusReqStateListAtom}
                            ddLabel="State/ UT/ HO"
                            dropdownName={"state"}
                            fetchMasterDataURL={isARDBCusReqTabActive(cusReqTabIndex) === 'Yes'? 'fetchStateARDBMasterData_CusReq' : 'fetchStateMasterData_CusReq'}
                            // @ts-ignore
                            optionLabel={["StateNameAndCode", "name", "short_name", "code"]}
                            defVal={defValState}
                        />
                    </Grid>

                    <Grid item md={4} xs={12} sx={{p: 1}}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqFilterFormAtom}
                            listDataAtom={cusReqPriorityListAtom}
                            ddLabel="Priority"
                            dropdownName={"priority"}
                            fetchMasterDataURL="fetchPriorityMasterData_CusReq"
                            defVal={defValPri}
                        />
                    </Grid>

                    <Grid item md={4} xs={12} sx={{p: 1}}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqFilterFormAtom}
                            listDataAtom={cusReqAgeingListAtom}
                            ddLabel="Ageing Group"
                            dropdownName={"ageing"}
                            fetchMasterDataURL="fetchAgeingMasterData_CusReq"
                            defVal={defValAgeing}
                        />
                    </Grid>

                    <Grid item md={4} xs={12} sx={{p: 1}}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqFilterFormAtom}
                            listDataAtom={cusReqStatusListAtom}
                            ddLabel="Status"
                            dropdownName={"status"}
                            fetchMasterDataURL="fetchStatusMasterData_CusReq"
                            defVal={defValStatus}
                        />
                    </Grid>

                    <Grid item md={4} xs={12} sx={{p: 1}}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqFilterFormAtom}
                            listDataAtom={cusReqShowstopperAuditFilterListAtom}
                            ddLabel="Showstopper Dayend"
                            dropdownName={"showstopper_dayend"}
                            optData={yesNoArr}
                            defVal={defValShowstopperDayend}
                        />
                    </Grid>

                    <Grid item md={4} xs={12} sx={{p: 1}}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqFilterFormAtom}
                            listDataAtom={cusReqShowstopperDayendFilterListAtom}
                            ddLabel="Showstopper Audit"
                            dropdownName={"showstopper_audit"}
                            optData={yesNoArr}
                            defVal={defValShowstopperAudit}
                        />
                    </Grid>

                    <Grid item md={4} xs={12} sx={{p: 1}}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqFilterFormAtom}
                            listDataAtom={cusReqAssignedToFilterListAtom}
                            ddLabel="Assigned To"
                            dropdownName={"assigned_to"}
                            optData={
                                isARDBCusReqTabActive(cusReqTabIndex) ===  "Yes" ?
                                stakeholderArrARDB    :
                                [...stakeholderArr, {id: "NA", name: "NA"}]

                            }
                            defVal={defValAssigned}
                        />
                    </Grid>

                    <Grid container direction={'row'}>


                        <TotalRecords/>


                        <Grid
                            item
                            md={6}
                            sx={{p: 1}}
                            display="flex"
                            justifyContent="flex-end"
                            alignItems="center"
                        >
                            <Button onClick={() => filterDataListing(true)} sx={{mt: 1, mx: 2}} variant="contained"
                                    color="warning">
                                Reset <RestartAltRounded sx={{width: 40, mt: -0.5}}/>
                            </Button>

                            <Button onClick={() => filterDataListing()} sx={{mt: 1}} variant="contained"
                                    color="success">
                                Search <ManageSearchOutlinedIcon sx={{width: 40, mt: -0.5}}/>
                            </Button>
                        </Grid>


                    </Grid>


                </Grid>
            </Card>
        );
    }, [Atom]);
}
