import {
    Button, Chip,
    Divider,
    Grid,
} from "@mui/material";
import React, { useMemo } from "react";
import {
    cusReqCUIMasterDetailsAtom,
    genUUID, isARDBCusReqTabActive, overViewTabAtom,
    useRecoilValue,
} from "../../../../Heplers";
import moment from "moment";
import { CardStagesHeader, createrArrOfInputs, inputsRender, pendingInputsRender, systemCreationRender } from "./CusReqDetailsCard_Pre";
import { Link, useNavigate } from "react-router-dom";
import {chipSX} from "../CusReqDatalisting";



export function CusReqDetailsCard_Dev() {
    const Atom = useRecoilValue(cusReqCUIMasterDetailsAtom);
    const cusReqTabIndex = useRecoilValue(overViewTabAtom);
    return useMemo(() => {
        const { dev, pre } = Atom;

        if (dev === null) {
            return <>

                {CardStagesHeader("Development")}
                <b>Not Started:</b>
                {/* <Grid item>
                    <Link to={`/${CUSTOMIZATIONREQUEST_LINK}dev/${pre.cui}`}>
                        <Button sx={{ minWidth: "unset", borderRadius: 10, fontSize: 10, p: "0.2px 15px" }} size="small" variant="outlined" color="primary" disableElevation >Add Development Details</Button>
                    </Link>

                </Grid> */}
                
        </>
        }
        const dev_reviews_ongoing = dev.dev_reviews_ongoing !== null ? JSON.parse(`[${dev.dev_reviews_ongoing}]`) : []
        console.log(dev_reviews_ongoing);

        return (
            <span key={genUUID()}>
               {CardStagesHeader("Development")}

                <b>Started On:</b> {moment(dev.dsd, "YYYY-MM-DD").format("DD-MMM-YY")}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Status :</b> <br />
                {
                    dev_reviews_ongoing[0].inputs_closed === 'Yes' ? <Chip size="small"  className="inputRecChip" label="Closed" color="success" sx={chipSX}/> : <Chip size="small" className="inputRecChip"  label="Pending" color="error" sx={{...chipSX, backgroundColor: "#B71C1C"}}/>
                }

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Assigned To:</b><br /> {dev.assigned_to}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Expected Date of Development Resolution:</b> <br /> {moment(dev.edor, "YYYY-MM-DD").format("DD-MMM-YY")}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Ageing:</b> <br /> {dev.ageing}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>{isARDBCusReqTabActive(cusReqTabIndex) === 'Yes'? 'NUSV' : 'NLPSV'} Resource:</b> <br /> {dev.nlpsv_resource_name}


                {dev_reviews_ongoing.map((v, i) => {
                    const pendingInputs = [];
                    const stakeholderInputs = [];

                    createrArrOfInputs(v, 'si', pendingInputs, stakeholderInputs);
                    createrArrOfInputs(v, 'state', pendingInputs, stakeholderInputs);
                    createrArrOfInputs(v, 'stcb', pendingInputs, stakeholderInputs);
                    createrArrOfInputs(v, 'spmu', pendingInputs, stakeholderInputs);
                    createrArrOfInputs(v, 'cpmu', pendingInputs, stakeholderInputs);
                    createrArrOfInputs(v, 'nlpsv', pendingInputs, stakeholderInputs);

                    if(pre.ardb_pacs ===  "Yes"){
                        //     Only ARDB Stakeholder
                        createrArrOfInputs(pre, 'scardb_branch', pendingInputs, stakeholderInputs);
                        createrArrOfInputs(pre, 'pcardb_ho', pendingInputs, stakeholderInputs);
                        createrArrOfInputs(pre, 'pcardb_branch', pendingInputs, stakeholderInputs);

                        // Renaming replaced stakeholders
                        pendingInputs.forEach(function(value, index, theArray) {
                            switch (value.toUpperCase()){
                                case "PACS":
                                    theArray[index] = "SCARDB_SU";
                                    break;
                                case "STCB":
                                    theArray[index] = "SCARDB_HO";
                                    break;
                                case "NLPSV":
                                    theArray[index] = "NUSV";
                                    break;
                                default:
                                    break;
                            }
                        });

                        stakeholderInputs.forEach(function(value, index, theArray) {
                            switch (value.name.toUpperCase()){
                                case "PACS":
                                    theArray[index].name = "SCARDB_SU";
                                    break;
                                case "STCB":
                                    theArray[index].name = "SCARDB_HO";
                                    break;
                                case "NLPSV":
                                    theArray[index].name = "NUSV";
                                    break;
                                default:
                                    break;
                            }
                        });
                    }

                    // console.log({ pendingInputs, stakeholderInputs })
                    return <span key={genUUID()}>
                        <Divider sx={{ my: 1, width: "25%" }} />
                        {/*<b>{i + 1}: Development Review On:</b><br /> {moment(v.dod, "YYYY-MM-DD").format("DD-MMM-YY")}*/}
                        <b>Development Review On:</b><br /> {moment(v.dod, "YYYY-MM-DD").format("DD-MMM-YY")}
                        {pendingInputsRender(pendingInputs, `Stakeholder Pending Inputs`, 0)}
                        {inputsRender(stakeholderInputs, `Stakeholder Inputs`, 0)}
                    </span>
                })}

                {systemCreationRender(dev)}



            </span>
        );
    }, [])
}
