import {Box, Grid, Paper} from "@mui/material";
import CssBaseline from "@mui/material/CssBaseline";
import Toolbar from "@mui/material/Toolbar";
import React, {useEffect, useMemo} from "react";
import DrawerComp from "../../../Components/Drawer/drawer";
import MainHeader from "../../../Components/Header/MainHeader";
import {HeaderMasterComp, LocationVisitProfileInputs, PlanInputs} from "./Components";
import {
    cusReqMasterDataAtom,
    ErrorLabelAtom,
    FIELDVISIT_LINK,
    invalidURLAlert,
    pageLoadingAtom,
    paramsFromURL,
    SubmitErrorAlertAtom,
    useRecoilState
} from "../../Heplers";
import axiosInstance from "../../../Services/AxiosInstance";

import {useNavigate} from "react-router-dom";
import {getCookie} from "../../../Services/Cookies";
import {BRFUploadFile, PageLoadingElem, UnderDevAlert} from "../CustomizationRequest/Components";
import {CardGreenHeader} from "../CustomizationRequest/Components/CardGreenHeader";
import {Stability_N_Accessibility} from "./Components/PreparationForm/Stability_N_Accessibility";
import {PersonalReadinessMotivation} from "./Components/PreparationForm/PersonalReadinessMotivation";
import {Knowledge_Training} from "./Components/PreparationForm/Knowledge_Training";
import {Support_System} from "./Components/PreparationForm/Support_System";
import {InstitutionalEngagement} from "./Components/PreparationForm/InstitutionalEngagement";
import {OperationalPractices} from "./Components/PreparationForm/OperationalPractices";
import {Access_Credentials} from "./Components/PreparationForm/Access_Credentials";
import {InfraAvail_n_IssuesHandling} from "./Components/PreparationForm/InfraAvail_n_IssuesHandling";
import {SoftwareFunc_Align} from "./Components/PreparationForm/SoftwareFunc_Align";
import {Post_ePACS_declaration} from "./Components/PreparationForm/Post_ePACS_declaration";
import {OnSystemAudit} from "./Components/PreparationForm/OnSystemAudit";
import {AuditorFeedback} from "./Components/PreparationForm/AuditorFeedback";
import {SI} from "./Components/PreparationForm/SI";
import {PreSoftware} from "./Components/PreparationForm/PreSoftware";

export default function CustomizationRequestEntryForm() {

    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    const navigate = useNavigate();

    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);
    const APICall = async (reqData) => {
        setPageLoading(true);
        axiosInstance({
            method: "post",
            url: "fetchCUIPreparation_CusReq",
            data: reqData,
        }).then(function (response) {
            // console.log('Data =>', response.data[0]);
            if (response.data[0] === null) {
                return invalidURLAlert(`CUI: ${reqData.cui}`, "Invalid Customization Unique Identification Number")
            } else {
                setPageLoading(false)
                setAtom(response.data[0])
            }

        })
            .catch(function (error) {
                setPageLoading(false)
                console.error(error);
            });

    };

    const URLParams = paramsFromURL({
        linkToSplit: FIELDVISIT_LINK + "/",
    })

    const [PageLoading, setPageLoading] = useRecoilState(pageLoadingAtom);
    useEffect(() => {
        window.scrollTo({
            top: 0,
            left: 0,
            behavior: "smooth",
        });


        // console.log('Listing', URLParams)
        if (URLParams.paramId !== undefined && URLParams.paramId != "") {
            //For Update Form

            // @ts-ignore
            // if (isNaN(URLParams.paramId)) {
            if (URLParams.paramId.length < 6) {
                invalidURLAlert(`CUI: ${URLParams.paramId}`, "Invalid Customization Unique Identification Number")
            } else {
                APICall({cui: URLParams.paramId});
            }
        } else {
            //For New Form
            setPageLoading(false)
        }
        return () => {
            // Clearing Page Used Variables

            // @ts-ignore
            setAtom({})
            setPageLoading(false)

            setSubmitErrorAlert(false);
            setErrorLabel(false);
        };

    }, []);

    // console.log("getCookie(\"userRole\")", getCookie("userRole"))
    const readOnly = (getCookie("userRole") !== "SPMU" && getCookie("userRole") !== "CPMU");

    const renderMainContent = () => {
        return <>
            <HeaderMasterComp URLParams={URLParams}/>

            <LocationVisitProfileInputs readOnly={readOnly}/>

            <PlanInputs readOnly={readOnly}/>

            <Stability_N_Accessibility readOnly={readOnly}/>

            <PersonalReadinessMotivation readOnly={readOnly}/>
            <Access_Credentials readOnly={readOnly}/>

            <Knowledge_Training readOnly={readOnly}/>

            <Support_System readOnly={readOnly}/>

            <InstitutionalEngagement readOnly={readOnly}/>

            <OperationalPractices readOnly={readOnly}/>

            <InfraAvail_n_IssuesHandling readOnly={readOnly} />
            <SoftwareFunc_Align readOnly={readOnly} />
            <Post_ePACS_declaration readOnly={readOnly} />
            <OnSystemAudit readOnly={readOnly} />
            <AuditorFeedback readOnly={readOnly} />
            <SI readOnly={readOnly} />
            <PreSoftware readOnly={readOnly} />
        </>
    }

    return useMemo(() => {
        return (
            <div>
                <style>
                    {`
                    .css-10hburv-MuiTypography-root{
                      font-size:11px !important;
                      font-family: Poppins 
                    }
                    .css-yb0lig{
                      font-size:12px !important
                    }
                    `}
                </style>

                <Box sx={{display: "flex", mt: 5}}>
                    <CssBaseline/>
                    {/* @ts-ignore*/}
                    <MainHeader/>
                    <DrawerComp listName={"Field Visit"}/>
                    <Box
                        component="main"
                        sx={{
                            flexGrow: 1,
                            backgroundColor: "#f4faf8",
                            px: 1,
                            // pr: 4,
                            // @ts-ignore
                            // height: isEmptyObject(URLParams) ? "100vh" : "auto",
                        }}
                    >
                        <Toolbar/>

                        <UnderDevAlert />

                        <PageLoadingElem/>

                        {!PageLoading && renderMainContent()}


                    </Box>
                </Box>
            </div>
        )
    }, [PageLoading]);
}
