import {Grid, Paper, Typography} from "@mui/material";
import {
    cusReqMasterDataAtom, cusReqShowstopperListAtom,
    cusReqStateListAtom,
    ErrorLabelAtom,
    isEmptyObject,
    isObjectCus,
    renderInputErrorLabel,
    SubmitErrorAlertAtom,
    useRecoilState, yesNoArr
} from "../../../../Heplers";
import React, {useMemo} from "react";
import {CusReqDropdown, RadioYesNo} from "..";
import {CardGreenHeader} from "../../../CustomizationRequest/Components/CardGreenHeader";

export const PersonalReadinessMotivation = ({readOnly}) => {

    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);


    return useMemo(() => {
        return (
            <Paper elevation={2} sx={{mb: 2}} className={"greenBorder"}>
                <CardGreenHeader text={"Personnel Readiness & Motivation"}/>

                <Grid p={2} spacing={2} container>

                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sta_acc1"} ddLabel={"There is a resource available to operate software"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sta_acc2"} ddLabel={"If he is motivated to open the software"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sta_acc3"} ddLabel={"Does he have time to operate on software"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sta_acc4"} ddLabel={"Is the personnel paid as per expectation of the personnel"} />
                    </Grid>
                    <Grid item xs={12} md={3.5}>
                        <RadioYesNo radioName={"sta_acc5"} ddLabel={"Does PACS management support software adoption"} />
                    </Grid>
                    <Grid item xs={12} md={4.5}>
                        <RadioYesNo radioName={"sta_acc6"} ddLabel={"Does DCCB support/encourage/incentivise/remind about software adoption"} />
                    </Grid>


                </Grid>
            </Paper>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
