import {Fab, Grid, Typography} from "@mui/material";
import React, {useEffect, useMemo} from "react";

import {AddCircleOutlineOutlined} from "@mui/icons-material";
import {
    CUSTOMIZATIONREQUEST_LINK,
    overViewDataAtom,
    overViewDataDefault, overViewTabAtom,
    useRecoilState,
    useRecoilValue,
} from "../../../Heplers";
import {useNavigate} from "react-router-dom";
import {getCookie} from "../../../../Services/Cookies";


export const NewCusReqButton = () => {

    const navigate = useNavigate();
    const readOnly = (getCookie("userRole") !== "SPMU" && getCookie("userRole") !== "CPMU");

    return useMemo(() => readOnly ? null : <Fab
        sx={{textTransform: "none"}}
        color="success"
        variant="extended"
        onClick={() => navigate(`/${CUSTOMIZATIONREQUEST_LINK}/`)}
    >
        <AddCircleOutlineOutlined sx={{mr: 1}}/>
        New Customisation Request
    </Fab>)

}
export const OverViewTotal = () => {
    const data = useRecoilValue(overViewDataAtom);

    const cusReqTabIndex = useRecoilValue(overViewTabAtom);

    return useMemo(() => {
        // const totalReq = data.CusBucket.reduce(
        //   (partialSum, v) => partialSum + v.total,
        //   0
        // );

        // console.log(data)
        const totalReq = data.CusBucket[0].total;

        // TOTAL UAT CLOSED means request closed
        const uatClosed = data.CusBucket[3].carbs;


        return (
            <Grid
                item
                container
                spacing={2}
                xs={12}
                sx={{
                    marginTop: "0.2%",
                    marginBottom: "1.5%",
                    paddingX: "1%",
                }}
            >
                <Grid item alignItems={"center"} xs={6}>
                    <Typography
                        variant="h4"
                        sx={{
                            color: "#00261C",
                            paddingTop: "1%",
                            fontWeight: "550",
                            lineHeight: "42px",
                        }}
                    >
                        {cusReqTabIndex.replace('_tab', '').toUpperCase()} Total Customization Request
                    </Typography>
                    <Grid display="flex" flexDirection={"row"} alignItems={"center"}>

                        <Typography
                            variant="h4"
                            sx={{
                                color: "#333333",
                                fontWeight: "700",
                                // fontSize: "32px",
                                fontFamily: "poppins",
                            }}
                        >
                            {totalReq}
                        </Typography>

                        <Typography
                            variant="h6"
                            sx={{
                                color: "#333333",
                                fontWeight: "300",
                                // fontSize: "16px",
                                fontFamily: "poppins",
                                px: 2,
                                mt: 1
                            }}
                        >
                            <span style={{color: '#065036'}}>Completed: <b>{uatClosed}</b></span>
                            {/*<br/>*/} {" | "}
                            <span style={{color: '#B71C1C'}}>Pending: <b>{totalReq - uatClosed}</b></span>
                        </Typography>

                    </Grid>
                </Grid>
                <Grid
                    display={"flex"}
                    justifyContent={"right"}
                    alignItems={"center"}
                    xs={6}
                    item
                >
                    <NewCusReqButton/>
                </Grid>
            </Grid>
        );
    }, [data]);
};
