import React, { useState } from "react";
import {
  Card,
  Grid,
  TextField,
  Button,
  Typography,
  Box
} from "@mui/material";
import { useRecoilState } from "recoil";
import {
  siFundTotalSancAtom,
  siGlobalModeAtom,
  siFundGlobatMasterIdAtom,
  siNameListAtom,
  siFundSiNameListAtom,
  siFundReleaseTableAtom,
  siFundTotalSancTableAtom,
  siFundMasterAtom

} from "../../RAS_updates/Heplers";
import {
  useSuccessAndResetAlert,
  renderSubmitErrorAlert
} from "../../RAS_updates/Heplers";
import { getCookie } from "../../Services/Cookies";
import axiosInstance from "../../Services/AxiosInstance";
import SaveIcon from "@mui/icons-material/Save";
import AutorenewIcon from "@mui/icons-material/Autorenew";
import RestartAltRounded from "@mui/icons-material/RestartAltRounded";
import { CusReqDropdownSIPayment } from "../SIPayments/CusReqDropdownSIPayment";
import { useNavigate } from 'react-router-dom';
import SiFundMasterForm from "./SiFundNewForm";

export default function SiFundTotalSancCard() {
  const [siFundMaster,setSiFundMaster]= useRecoilState(siFundMasterAtom)
  const [form, setForm] = useRecoilState(siFundTotalSancAtom);
  const [mode, setMode] = useRecoilState(siGlobalModeAtom);
  const [loading, setLoading] = useState(false);
  const [fundMasterId] = useRecoilState(siFundGlobatMasterIdAtom);
  const successAlertAndReset = useSuccessAndResetAlert(siFundTotalSancAtom);
  const [siNameList, setSiNameList] = useRecoilState(siFundSiNameListAtom);
  const [globalFundId, setGlobalFundId] = useRecoilState(siFundGlobatMasterIdAtom);
  const [sifundReleaseTable, setSiFundReleaseTable] = useRecoilState(siFundReleaseTableAtom);
  const [siFundTotalSancsTable, setSiFundTotalSancsTable] = useRecoilState(siFundTotalSancTableAtom);
  const navigate = useNavigate();
  // if (!Array.isArray(siNameList) || siNameList.length === 0) {
  //   return <p>Loading SI list...</p>; // or a spinner
  // }

  const fetchAndUpdateSubClasses = async (fundMasterId) => {
    try {
      const res = await axiosInstance.post(`/siFundMaster/FundMasterSubClasses`, {}, {
        params: { fundMasterId },
      });

      if (res.status === 200 && res.data?.fundMasterDetails?.siFundMaster) {
        setForm({
          siId: fundMasterId,
          ...res.data.fundMasterDetails.siFundMaster,
        });

        setGlobalFundId(fundMasterId);
        setSiNameList(res.data.siMasters.sis);

        if (Array.isArray(res.data.fundMasterDetails.siFundReleaseList)) {
          setSiFundReleaseTable(res.data.fundMasterDetails.siFundReleaseList);
        }

        if (Array.isArray(res.data.fundMasterDetails.siTotalSancMasterList)) {
          setSiFundTotalSancsTable(res.data.fundMasterDetails.siTotalSancMasterList);
        }
      } else {
        renderSubmitErrorAlert(res.data?.error || "Failed to fetch updated fund data.");
      }
    } catch (err) {
      console.error("Error fetching subclasses:", err);
      renderSubmitErrorAlert("Something went wrong while refreshing data.");
    }
  };

  const handleClear = () => {
    setForm({
      createdBy: 0,
      siName: "",
      id: 0,
      totalSancPACS: 0,
      fundMasterId: 0,
      date: null
    });
    setMode("create");
  };

  const handleChange = (field) => (e) => {
    setForm((prev) => ({
      ...prev,
      [field]: e.target.value
    }));
  };
  
  const handleClose = () => {
    navigate("/sipaymentsfunds");
  }

  const handleSaveOrUpdate = async () => {
    const user_id = getCookie("resourceId");

    if (!form.siName || !form.totalSancPACS) {
      alert("All fields are required.");
      return;
    }

    setLoading(true);

    const payload = {
      createdBy: user_id,
      stateUt: siFundMaster.stateUt.id,
      totalSancPACS: form.totalSancPACS,
      date: form.date,
      siMasterId: form.siName.siId,
      id: form.id
    };

    const url = form.id ? "/siTotalSancMaster/update" : "/siTotalSancMaster/create";

    try {
      const res = await axiosInstance.post(url, payload);

      if (res.status === 200 && res.data.message) {
        successAlertAndReset(res.data.message);
        await fetchAndUpdateSubClasses(fundMasterId);
      } else {
        renderSubmitErrorAlert(res.data.error || "Operation failed.");
      }
    } catch (err) {
      renderSubmitErrorAlert("Something went wrong.");
    }

    setLoading(false);
  };
  console.log("siNameList", siNameList);
  return (
    <Grid item xs={12} sx={{ p: 2 }}>
      <Card sx={{ p: 3, width: "100%" }}>
        <Typography variant="h6" sx={{ mb: 2 }}>
          SI Fund Total Sanctioned PACs
        </Typography>
        <Grid container spacing={2} sx={{ mb: 2 }}>
          <Grid item  xs={12} md={4}>
            {siNameList.length > 0 && (
                <CusReqDropdownSIPayment
              //@ts-ignore
              formDataAtom={siFundTotalSancAtom}
              listDataAtom={siNameListAtom}
              ddLabel="Si Name"
              dropdownName="siName"
              // fetchMasterDataURL="fetchStateMasterData_CusReq"
              optData={siNameList}
              //@ts-ignore
              optionLabel={["siName", "name"]}
              defVal={form.siName}
              value={form.siName|| ""}
              onChange={handleChange("siName")}
              required
            />
              )}
          
          </Grid>

          <Grid item  xs={12} md={4}>
            <TextField
              label="Total Sanctioned PACs"
              type="number"
              value={form.totalSancPACS || ""}
              onChange={handleChange("totalSancPACS")}
              fullWidth
              required
            />
          </Grid>

          <Grid item  xs={12} md={4}>
            <TextField
              label="Date"
              type="date"
              value={form.date || ""}
              onChange={handleChange("date")}
              fullWidth
              InputLabelProps={{ shrink: true }}
            />
          </Grid>
        </Grid>

        <Box sx={{ display: "flex", justifyContent: "flex-end", gap: 1 }}>
          <Button
            variant="contained"
            onClick={handleSaveOrUpdate}
            sx={{ mt: 1 }}
            color="success"
          >
            {form.id ? "Update" : "Save"}
            {form.id ? (
              <AutorenewIcon sx={{ width: 20, ml: 1 }} />
            ) : (
              <SaveIcon sx={{ width: 20, ml: 1 }} />
            )}
          </Button>
          <Button
            sx={{ mt: 1 }}
            variant="contained"
            color="warning"
            onClick={handleClear}
            disabled={loading}
          >
            Clear <RestartAltRounded sx={{ width: 20, ml: 1 }} />
          </Button>
          <Button
            sx={{ mt: 1 }}
            variant="outlined"
            color="error"
            onClick={handleClose}
          >
            Close
          </Button>
        </Box>
      </Card>
    </Grid>
  );
}
