import {Grid, Paper, Typography} from "@mui/material";
import {
    cusReqMasterDataAtom,
    cusReqStateListAtom,
    ErrorLabelAtom,
    isEmptyObject,
    isObjectCus,
    renderInputErrorLabel,
    SubmitErrorAlertAtom,
    useRecoilState
} from "../../../../Heplers";
import React, {useMemo} from "react";
import {CusReqDropdown} from "..";
import {CardGreenHeader} from "../../../CustomizationRequest/Components/CardGreenHeader";

export const LocationVisitProfileInputs = ({readOnly}) => {

    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);


    return useMemo(() => {
        return (
            <Paper elevation={2} sx={{mb: 2}} className={"greenBorder"}>
                <CardGreenHeader text={"Location Visit Profile Details"}/>

                <Grid p={2} spacing={2} container>

                    <Grid item xs={12} md={4}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqMasterDataAtom}
                            listDataAtom={cusReqStateListAtom}
                            ddLabel="State"
                            dropdownName={"state"}
                            required
                            fetchMasterDataURL={'fetchStateMasterData_CusReq'}
                            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.state : null}
                            // @ts-ignore
                            optionLabel={["StateNameAndCode", "name", "short_name", "code"]}

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}

                        />
                        {/* @ts-ignore */}
                        {renderInputErrorLabel(ErrorLabel, Atom.state, "Required")}
                    </Grid>

                    <Grid item xs={12} md={4}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqMasterDataAtom}
                            listDataAtom={cusReqStateListAtom}
                            ddLabel="DCCB"
                            dropdownName={"state"}
                            required
                            fetchMasterDataURL={'fetchStateMasterData_CusReq'}
                            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.state : null}
                            // @ts-ignore
                            optionLabel={["StateNameAndCode", "name", "short_name", "code"]}

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}

                        />
                        {/* @ts-ignore */}
                        {renderInputErrorLabel(ErrorLabel, Atom.state, "Required")}
                    </Grid>

                    <Grid item xs={12} md={4}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqMasterDataAtom}
                            listDataAtom={cusReqStateListAtom}
                            ddLabel="District"
                            dropdownName={"state"}
                            required
                            fetchMasterDataURL={'fetchStateMasterData_CusReq'}
                            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.state : null}
                            // @ts-ignore
                            optionLabel={["StateNameAndCode", "name", "short_name", "code"]}

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}

                        />
                        {/* @ts-ignore */}
                        {renderInputErrorLabel(ErrorLabel, Atom.state, "Required")}
                    </Grid>

                    <Grid item xs={12} md={4}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqMasterDataAtom}
                            listDataAtom={cusReqStateListAtom}
                            ddLabel="DCCB Branch"
                            dropdownName={"state"}
                            required
                            fetchMasterDataURL={'fetchStateMasterData_CusReq'}
                            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.state : null}
                            // @ts-ignore
                            optionLabel={["StateNameAndCode", "name", "short_name", "code"]}

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}

                        />
                        {/* @ts-ignore */}
                        {renderInputErrorLabel(ErrorLabel, Atom.state, "Required")}
                    </Grid>

                    <Grid item xs={12} md={4}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqMasterDataAtom}
                            listDataAtom={cusReqStateListAtom}
                            ddLabel="PACS"
                            dropdownName={"state"}
                            required
                            fetchMasterDataURL={'fetchStateMasterData_CusReq'}
                            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.state : null}
                            // @ts-ignore
                            optionLabel={["StateNameAndCode", "name", "short_name", "code"]}

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}

                        />
                        {/* @ts-ignore */}
                        {renderInputErrorLabel(ErrorLabel, Atom.state, "Required")}
                    </Grid>

                    <Grid item xs={12} md={4}>
                        <Typography className={'greenText'} pt={1} fontSize={14} fontWeight="bold">Ensure
                            ID:</Typography>
                        <Typography className={'greenText'} fontSize={14} fontWeight="bold">PACS ID:</Typography>
                    </Grid>


                </Grid>
            </Paper>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
