import React, { useState, useEffect } from 'react';
import { Card, Grid, TextField, Button, MenuItem, Typography, Box, Pagination } from "@mui/material";
import { useRecoilState } from "recoil";
import { siFilterAtom, siWOTableAtom, siStateListAtom } from "../../RAS_updates/Heplers";
import { CusReqDropdownSIPayment } from "../SIPayments/CusReqDropdownSIPayment";
import { SiNameTable } from './SiNameTable';
import axiosInstance from '../../Services/AxiosInstance';
import { RestartAltRounded } from "@mui/icons-material";
import ManageSearchOutlinedIcon from "@mui/icons-material/ManageSearchOutlined";
import { PageLoadingElem, DataListingLoadingElem } from '../../RAS_updates/Pages/CustomizationRequest/Components';
export default function SiMasterSearchForm() {
  const [filters, setFilters] = useRecoilState(siFilterAtom);
  const [siList, setSiList] = useRecoilState(siWOTableAtom);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(0); // 0-based for API
  const size = 5;
  const [totalItems, setTotalItems] = useState(0);
  const [searchTriggered, setSearchTriggered] = useState(false);

  useEffect(() => {
    fetchTableData(); // fetch on first mount
  }, []);

  useEffect(() => {
    if (searchTriggered) {
      fetchTableData();
      setSearchTriggered(false); // reset after fetch
    }
  }, [searchTriggered, page]);

  const buildQueryParams = () => {
    const params = {};
    params.page = page;
    params.size = size;
    if (filters.stateUt) params.stateId = filters.stateUt.id;
    if (filters.siName) params.siName = filters.siName;
    if (filters.siType) params.siType = filters.siType;
    params.sort = "createdAt,desc"; // Default sorting
    return params;
  };

  const fetchTableData = async () => {
    setLoading(true);
    try {
      const params = buildQueryParams();
      const res = await axiosInstance.post('/siMaster/siPagenation', {}, { params });

      if (res.status === 200 && res.data?.data) {
        // console.log("siList value at render:", siList);
        setSiList(res.data.data || []);
        setTotalItems(res.data.totalItems || 0);
        if (!siList || siList.length === 0) return <p>No data available.</p>;
      } else {
        setSiList([]);
        setTotalItems(0);
      }
    } catch (error) {
      setSiList([]);
      setTotalItems(0);
      console.error('Failed to fetch SI data', error);
    }
    setLoading(false);
  };

  const handleChange = (field) => (event) => {
    setFilters((prev) => ({
      ...prev,
      [field]: event.target.value
    }));
  };

  const handleClick = () => {
    setPage(0);
    setSearchTriggered(true);
  };

  const handleClear = () => {
    setFilters({
      stateUt: null,
      siName: "",
      siType: ""
    });
    setPage(0);
    setSearchTriggered(true);
  };

  //  console.log("siList value at render:", siList);
  // console.log("loading",loading);
  return (
    <Grid item container sx={{ width: "100%" }}>
      <Card sx={{ p: 3, width: "100%" }}>
        <Typography variant="h6" sx={{ mb: 2 }}>
          SI Master
        </Typography>
        <Grid container spacing={2}>
          {/* State/UT */}
          <Grid item xs={12} sm={4}>
            <CusReqDropdownSIPayment
              // @ts-ignore
              formDataAtom={siFilterAtom}
              // @ts-ignore
              listDataAtom={siStateListAtom}
              ddLabel="State/ UT"
              dropdownName="stateUt"
              fetchMasterDataURL="fetchStateMasterData_CusReq"
              // @ts-ignore
              optionLabel={["StateNameAndCode", "name", "short_name", "code"]}
              value={filters.stateUt || ""}
              onChange={handleChange("stateUt")}
            />
          </Grid>
          {/* SI Name */}
          <Grid item xs={12} sm={4}>
            <TextField
              fullWidth
              label="SI Name"
              value={filters.siName || ""}
              onChange={handleChange("siName")}
            />
          </Grid>
          {/* SI Type */}
          <Grid item xs={12} sm={4}>
            <TextField
              select
              fullWidth
              label="SI Type"
              value={filters.siType || ""}
              onChange={handleChange("siType")}
            >
              <MenuItem value="Hardware">Hardware</MenuItem>
              <MenuItem value="Digitisation">Digitisation</MenuItem>
            </TextField>
          </Grid>
          {/* Buttons */}
          <Grid item xs={12}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "flex-end",
                alignItems: "center",
                mt: 2
              }}
            >
              <Grid item display="flex" alignItems="center">
                <Button
                  onClick={handleClear}
                  sx={{ mt: 1, mx: 1 }}
                  variant="contained"
                  color="warning"
                >
                  Reset <RestartAltRounded sx={{ width: 20, ml: 1 }} />
                </Button>
                <Button
                  onClick={handleClick}
                  sx={{ mt: 1 }}
                  variant="contained"
                  color="success"
                >
                  Search <ManageSearchOutlinedIcon sx={{ width: 20, ml: 1 }} />
                </Button>
              </Grid>
            </Box>
          </Grid>

          {/* <Grid item xs={12} >
            <Box sx={{ display: "flex", justifyContent: "flex-end", gap: 1 }}>
              <Button variant="outlined" color="error" onClick={handleClear}>
                Clear
              </Button>
              <Button variant="outlined" color="success" onClick={handleClick}>
                Search
              </Button>
            </Box>
          </Grid> */}
        </Grid>

      </Card>
      <div style={{ width: '100%' }}>
        <Card className="cusTable" sx={{ mt: 2 }}>
          {/* {!loading ? <DataListingLoadingElem /> : <SiNameTable page={page} size={size} />} */}

          <SiNameTable page={page} size={size} />
          {/* Pagination */}
          <Box sx={{ display: "flex", justifyContent: "flex-end", my: 2 }}>
            <Pagination
              count={Math.ceil(totalItems / size)}
              page={page + 1}
              onChange={(_, value) => setPage(value - 1)}
              color="primary"
              shape="rounded"
            />
          </Box>
        </Card>
      </div>
    </Grid>
  );
}