import {

    Button, CircularProgress, Divider, Grid, Stack
} from "@mui/material";

import React, {useEffect, useMemo, useRef, useState} from "react";

import {
    API_Endpoint, displayDownloadableFilesLinks,
    fileUploadTextPDFImage,
    invalidURLAlert, successAndGoBackAlert, tempBRDFIlesArrAtom,
    useRecoilState
} from "../../RAS_updates/Heplers";
import {getCookie} from "../../Services/Cookies";
import uploadcld from "../../Assets/download_btn.svg";
import axiosInstance from "../../Services/AxiosInstance";


export const SiWOMasterUploadFile = ({formAtom}) => {

    const [uploading, setUploading] = useState(false);
    const [selectedFile, setSelectedFile] = useState(null);

    const [AtomBRF, setAtomBRF] = useRecoilState(formAtom);

    const [fileNameLabel, setFileNameLabel] = useState(fileUploadTextPDFImage);

    // console.log( AtomBRF.brd_file, typeof AtomBRF.brd_file, AtomBRF.brd_file === null );
    // const tempArr = useRef((AtomBRF.siWODoc !== undefined && AtomBRF.siWODoc !== null && AtomBRF.siWODoc.length > 0) ? AtomBRF.siWODoc.split(',') : []);
 
    const handleFileChange = (e) => {

        if (e.target.files[0].size > 10000000) {
            clearSeletedFiles();
            return invalidURLAlert(`Error`, "File upload file less than 10MB", "", false);
        }
        const file = e.target.files[0];

        console.log(e.target.files[0].size)
        setSelectedFile(file);
        setFileNameLabel(file ? file.name : fileUploadTextPDFImage);
    };

    const clearSeletedFiles = () => {
        setSelectedFile(null);
        setFileNameLabel(fileUploadTextPDFImage);
    }

    const handleFileUploadHSI = async () => {
        if (!selectedFile) {
    return invalidURLAlert("Upload Error", "Please select a document to upload.");
  }
 setUploading(true);
  try {
    const formData = new FormData();
    formData.append("file", selectedFile);

    const response = await axiosInstance({
      method: "post",
      url: "uploadFile_BRF",
      data: formData,
      headers: {
        "Content-Type": "multipart/form-data",
        email: getCookie("email2"),
        resourceId: getCookie("resourceId"),
        "access-token": getCookie("token"),
        Authorization: `Bearer ${getCookie("token")}`,
      }
    });

    const uploadedFilePath = response.data.data;

    successAndGoBackAlert("Success", "File uploaded successfully!", false);

    clearSeletedFiles();

    setAtomBRF(prevState => ({
      ...prevState,
      siWODoc: uploadedFilePath, // single file only
    }));

    setUploading(false);
  } catch (err) {
    console.log("file upload failed : ", err);
    if (err.response && err.response.status === 400) {
      alert("Please upload the appropriate file.");
    } else {
      alert("File upload failed. Please try again.");
    }
    setUploading(false);
  }
};
   

    return useMemo(() => {
        return (<>
            <Divider sx={{my: 1}}/>

           {displayDownloadableFilesLinks(AtomBRF.siWODoc ? [AtomBRF.siWODoc] : [])}

            <Divider sx={{my: 1}}/>

            <Stack
                direction={{xs: "column", md: "row"}}
                justifyContent="space-around"
                alignItems={{xs: "flex-start", md: "center"}}

            >

                {uploading ?
                    (<Grid sx={{mt: 2}}>
                        Uploading please wait ... <CircularProgress size={16} color="success"/>
                    </Grid>) : (
                        <>
                            {/*//         <Typography*/}
                            {/*    //     sx={{*/}
                            {/*    //         fontSize: "15px",*/}
                            {/*    //         fontWeight: "600",*/}
                            {/*    //         fontFamily: "Poppins",*/}
                            {/*    //         marginRight: "10px",*/}
                            {/*    //     }}*/}
                            {/*    // >*/}
                            {/*    //     Upload BRF Docs Here*/}
                            {/*    // </Typography>*/}
                            <input
                                type="file"
                                // accept="application/pdf,application/vnd.ms-excel"
                                accept="application/pdf, .png, .jpeg, .jpg, .doc, .docx"
                                onChange={handleFileChange}
                                style={{
                                    height: "45px",
                                    flexShrink: 0,
                                    borderRadius: "5px",
                                    border: "1px dashed rgba(0, 0, 0, 0.46)",
                                    display: "none",
                                    padding: "10px",
                                }}
                                id="fileInput"
                            />
                            <label
                                htmlFor="fileInput"
                                className="upload-button"
                                style={{
                                    color: "#A4A4A4",
                                    fontSize: "12px",
                                    fontWeight: "100",
                                    display: "inline-block",
                                    cursor: "pointer",
                                    textAlign: "center",
                                    height: "38px",
                                    flexShrink: 0,
                                    borderRadius: "7.69px",
                                    border: "0.96px solid #D0D5DD",
                                    lineHeight: "38px",
                                    fontFamily: "Poppins",
                                    paddingLeft: "10px",
                                    paddingRight: "10px",
                                }}
                            >
                                {fileNameLabel}
                            </label>
                            <Button
                                variant="contained"
                                startIcon={<img src={uploadcld} alt="upload Icon"/>}
                                onClick={handleFileUploadHSI}
                                sx={{
                                    textTransform: "capitalize",
                                    backgroundColor: "#065036",
                                    height: "38px",
                                    fontSize: "14px",
                                    fontFamily: "Poppins",
                                    lineHeight: "0px",
                                    display: "flex",
                                    justifyItems: "flex-start",
                                    marginLeft: {md: "10px", xs: "0px"},
                                    marginTop: {md: "0", xs: "10px"},
                                    "&:hover": {
                                        backgroundColor: "#333",
                                    },
                                }}
                            >
                                Upload
                            </Button>
                        </>

                    )}

            </Stack>
        </>)
            ;
    }, [selectedFile, fileNameLabel, uploading]);
};
