import React, { useEffect, useState } from "react";
import { Button, Stack } from "@mui/material";
import ArrowForward from "../../Assets/arrow_polygon.svg";
import "../../Components/StateDrawer/stated.css";
import { useAuth } from "../../Services/Auth";
import axiosInstance from "../../Services/AxiosInstance";
import { getCookie } from "../../Services/Cookies";

function StateDrawer() {
  const { setSelectedBtnSanc, selectedBtnSanc } = useAuth();
  const [selectedButton, setSelectedButton] = useState("Andaman & Nicobar");
  const [stateNames, SetStateNames] = useState([]);

  useEffect(() => {
    setSelectedBtnSanc("Andaman and Nicobar Islands");
    const fetchStates = async () => {
      const config = {
        headers: {
          email: getCookie("email2"),
          "access-token": getCookie("token"),
          Authorization: `Bearer ${getCookie("token")}`,
        },
      };
      try {
        const response = await axiosInstance.post("fetchStates", {}, config);
        if (response.status === 200) {
          const stateNames = response.data.map((state) => state.stateName);
          SetStateNames(stateNames);
        }
      } catch (error) {
        console.error("Error fetching data:", error);
      }
    };
    fetchStates();
  }, []);

  const handleButtonClick = (buttonVal) => {
    if (buttonVal === "Andaman & Nicobar") {
      setSelectedButton(buttonVal);
      setSelectedBtnSanc("Andaman and Nicobar Islands");
    } else if (buttonVal === "Jammu & Kashmir") {
      setSelectedButton(buttonVal);
      setSelectedBtnSanc("Jammu and Kashmir");
    } else {
      setSelectedButton(buttonVal);
      setSelectedBtnSanc(buttonVal);
    }
  };

  const indianStateNames = stateNames.map((state) => {
    if (state === "Andaman and Nicobar Islands") {
      return "Andaman & Nicobar";
    } else if (state === "Jammu and Kashmir") {
      return "Jammu & Kashmir";
    } else {
      return state;
    }
  });

  return (
    <div
      style={{
        position: "relative",
        width: "20%",
        backgroundColor: "#EEF4ED",
        padding: "12px",
        // height: "400px",
        borderRadius: "4px",
        overflowX: "hidden",
        overflowY: "auto",
      }}
      className="checkSD"
    >
      <Stack direction="column">
        {indianStateNames &&
          indianStateNames.map((buttonIndex) => (
            <Stack
              direction="row"
              key={buttonIndex}
              alignItems="center"
              sx={{
                marginBottom: "8px",
                position: "relative",
                zIndex: selectedButton === buttonIndex ? "1" : "auto",
                // marginLeft: selectedButton !== buttonIndex ? "0px" : "20px",
              }}
            >
              <Button
                onClick={() => handleButtonClick(buttonIndex)}
                sx={{
                  minWidth: selectedButton === buttonIndex ? "90%" : "100%",
                  justifyContent: "flex-start",
                  textTransform: "capitalize",
                  fontFamily:"poppins",
                  backgroundColor:
                    selectedButton === buttonIndex ? "#054B0C" : "transparent",
                  boxShadow:
                    selectedButton !== buttonIndex
                      ? "0px 2px 1px -1px rgba(0,0,0,0.2), 0px 1px 1px 0px rgba(0,0,0,0.14), 0px 1px 3px 0px rgba(0,0,0,0.12)"
                      : "none",
                  color: selectedButton === buttonIndex ? "#FFFFFF" : "#000000",
                  "&:hover": {
                    backgroundColor: "#054B0C",
                    color: "white",
                    fontFamily:"poppins"
                  },
                }}
              >
                {buttonIndex}
              </Button>
              {selectedButton === buttonIndex && (
                <img
                  src={ArrowForward}
                  alt=""
                  style={{ width: "15px", height: "27px", marginLeft: "2px" }}
                />
              )}
            </Stack>
          ))}
      </Stack>
    </div>
  );
}

export default StateDrawer;
