import {Box, Grid, LinearProgress, Tab,} from "@mui/material";
import CssBaseline from "@mui/material/CssBaseline";
import Toolbar from "@mui/material/Toolbar";
import React, {useEffect, useMemo} from "react";
import DrawerComp from "../../../Components/Drawer/drawer";
import MainHeader from "../../../Components/Header/MainHeader";

import {
  isARDBCusReqTabActive,
  isEmptyObject,
  isObjectCus,
  overViewDataAtom,
  overViewTabAtom,
  useRecoilState,
} from "../../Heplers";
import {OverviewCardPenAndClosedOnly, OverViewTotal, UnderDevAlert,} from "./Components";
import axiosInstance from "../../../Services/AxiosInstance";
import ReportDownloadCusReq from "./Components/ReportDownloadCusReq";
import {TabContext, TabList, TabPanel} from "@mui/lab";

export default function CusReqOverview() {
  const [data, setData] = useRecoilState(overViewDataAtom);

  // const [tabIndex, settabIndex] = useState("pacs_tab");
  const [tabIndex, settabIndex] = useRecoilState(overViewTabAtom);

  const APICall = async () => {
    axiosInstance({
      method: "post",
      url: "overallfigures_CusReq",
      data: {is_ardb: isARDBCusReqTabActive(tabIndex)},
    })
      .then(function (response) {
        console.log("Data =>", response.data);
        // console.log("typeof =>", typeof response.data.data[0].json_build_object);

        const parsedRes = JSON.parse(response.data.data);
        const parsedData = JSON.parse(parsedRes[0].json_build_object);

        // console.log("typeof =>", typeof parsedData);

        console.log(parsedData);

        const formattedData = {
          CusBucket: [
            {
              name: "Preparation",
              total: parsedData.pre,
              fat: parsedData.pre - parsedData.pre_closed,
              // hoapp: 3,
              carbs: parsedData.pre_closed,
            },
            {
              name: "Business Req. Finalization",
              total: parsedData.brd,
              fat: parsedData.brd - parsedData.brd_closed,
              // hoapp: 1,
              carbs: parsedData.brd_closed,
            },
            {
              name: "Development",
              total: parsedData.dev,
              fat: parsedData.dev - parsedData.dev_closed,
              // hoapp: 0,
              carbs: parsedData.dev_closed,
            },
            {
              name: "User Acceptance",
              total: parsedData.uat,
              fat: parsedData.uat - parsedData.uat_closed,
              // hoapp: 0,
              carbs: parsedData.uat_closed,
            },
          ],
        };
        // console.log(overViewDataDefault);
        console.log({ formattedData });

        setData(formattedData);
      })
      .catch(function (error) {
        console.error(error);
      });

    // await new Promise((r) => setTimeout(r, 2000));
    // setData(overViewDataDefault);
  };

  useEffect(() => {
    window.scrollTo({
      top: 0,
      left: 0,
      behavior: "smooth",
    });

    APICall();

    return () => {

        // Cleanup function if needed
        // For example, you can reset the data or perform any other cleanup
      setData({});
    }
  }, [tabIndex]);


  const pacsOverviewPage = () => {
    return <>
      {isObjectCus(data) && !isEmptyObject(data) ? (
          <div style={{ zoom: 1 }}>
            <OverViewTotal />

            <Grid item container xs={12} paddingBottom={2}>
              <OverviewCardPenAndClosedOnly />
            </Grid>

            {/* TODO: HIDDEN FOR DEMO */}
            {/*

                <Grid item container xs={12} paddingBottom={2}>
                  <OverviewCard />
                </Grid>

                <Grid item container spacing={2}>
                  <Grid item md={4} xs={12}>
                    <RevisedCusBucketCardDetails />
                  </Grid>

                  <Grid item md={4} xs={12}>
                    <AgeingChart />
                  </Grid>
                  <Grid item md={4} xs={12}>
                    <PendingChart />
                  </Grid>
                </Grid> */}


            <ReportDownloadCusReq />


          </div>
      ) : (
          <LinearProgress sx={{ marginTop: 5 }} color="success" />
      )}
    </>
  }
  const handleChange = (event, newtabIndex) => {
    if (event.type === 'click') {
      settabIndex(newtabIndex);
    }
  };

  return useMemo(() => {
    return (
      <div>
        <style>
          {`
              .css-10hburv-MuiTypography-root{
                font-size:11px !important;
                font-family: Poppins 
              }
              .css-yb0lig{
                font-size:12px !important
              }
              `}
        </style>

        <Box sx={{ display: "flex" }}>
          <CssBaseline />
          {/* @ts-ignore*/}
          <MainHeader />
          <DrawerComp listName={"Field Visit"} />
          <Box
            component="main"
            sx={{
              flexGrow: 1,
              backgroundColor: "#f4faf8",
              p: 1,
              // @ts-ignore
              height: isEmptyObject(data) ? "100vh" : "auto",
              // height: "100vh",
            }}
          >
            <Toolbar />

            {/*<UnderDevAlert />*/}


            <TabContext value={tabIndex}>
              <Box sx={{ borderBottom: 1, borderColor: 'divider', pt: 2}}>
                <TabList textColor="primary"
                         indicatorColor="primary" onChange={handleChange} centered >
                  <Tab label="PACS Request" value="pacs_tab" style={{fontWeight: 'bold', fontSize: 18}} />
                  <Tab label="ARDB Request" value="ardb_tab" style={{fontWeight: 'bold', fontSize: 18}} />
                </TabList>
              </Box>
              <TabPanel value="pacs_tab">{pacsOverviewPage()}</TabPanel>
              <TabPanel value="ardb_tab">

                {/*<UnderDevAlert text={"ARDB Customization Request Module is under development"} />*/}

                {pacsOverviewPage()}

              </TabPanel>
            </TabContext>

          </Box>
        </Box>
      </div>
    );
  }, [data, tabIndex]);
}
