import React, { useState, useEffect } from 'react';
import { Card, Grid, TextField, Button, MenuItem, Typography, Box, Pagination } from "@mui/material";
import { useRecoilState } from "recoil";
import { siFundsFilterAtom, siNameListAtom, siFundsFilterTableAtom, siSearchFieldsAtom, siStateListAtom } from "../../RAS_updates/Heplers";
import { CusReqDropdownSIPayment } from "../SIPayments/CusReqDropdownSIPayment";
// import { SiNameTable } from './SiNameTable';
import axiosInstance from '../../Services/AxiosInstance';
import { RestartAltRounded } from "@mui/icons-material";
import ManageSearchOutlinedIcon from "@mui/icons-material/ManageSearchOutlined";
import { SiFundTable } from './SiFundSearchTable';
import { PageLoadingElem, DataListingLoadingElem } from '../../RAS_updates/Pages/CustomizationRequest/Components';
export default function SiFundSearchForm() {
  const [filters, setFilters] = useRecoilState(siFundsFilterAtom);
  const [siList, setSiList] = useRecoilState(siFundsFilterTableAtom);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(0); // 0-based for API
  const size = 5;
  const [totalItems, setTotalItems] = useState(0);
  const [searchTriggered, setSearchTriggered] = useState(false);
  const [siNameOptions, setSiNameOptions] = useRecoilState(siNameListAtom);
  const [siNameData, setSiNameData] = useState([]);
  const [siNameList, setSiNameList] = useState([]);


  useEffect(() => {
    axiosInstance.post('/si-payments/siswithStates').then(res => {
      if (res.data && Array.isArray(res.data)) {
        setSiNameData(res.data);
      }
    });
  }, []);

  // useEffect(() => {
  //   // Only run if state is selected and siNameData is loaded
  //   if (filters.stateUt && filters.stateUt.id) {
  //     const match = siNameData.find(
  //       (item) => item.stateId === filters.stateUt.id
  //     );
  //     console.log("Matched state data", match);
  //     setSiNameOptions(match && Array.isArray(match.sis) ? match.sis : []);
  //   } else {
  //     setSiNameOptions([]); // No state selected, clear options
  //   }
  // }, [filters.stateUt, siNameData, setSiNameOptions]);
  useEffect(() => {
    axiosInstance.post('/si-payments/siswithStates').then((res) => {
      if (res.data && Array.isArray(res.data)) {
        // Flatten all `sis` arrays into one
        const mergedSis = res.data.flatMap((item) => item.sis || []);
        console.log("Merged SI Names:", mergedSis);
        setSiNameList(mergedSis); // This is now a flat array
      }
    });
  }, []);

  useEffect(() => {
    if (searchTriggered || page === 0) {
      fetchTableData();
      setSearchTriggered(false);
    }
  }, [searchTriggered]);

  // Separate effect for pagination changes
  useEffect(() => {
    if (page >= 0 && !searchTriggered) {
      fetchTableData();
    }
  }, [page]);

  const buildQueryParams = () => {
    const params = {};
    params.page = page;
    params.size = size;
    if (filters.stateUt) params.stateId = filters.stateUt.id;
    if (filters.siName) params.siName = filters.siName.siName;
    params.sort = "createdAt,desc"; // Default sorting
    return params;
  };

  const fetchTableData = async () => {
    setLoading(true);
    try {
      const params = buildQueryParams();
      const res = await axiosInstance.post('/siFundMaster/pagination', {}, { params });

      if (res.status === 200 && res.data?.data) {
        // console.log("siList value at render:", siList);
        setSiList(res.data.data || []);
        setTotalItems(res.data.totalItems || 0);
        if (!siList || siList.length === 0) return <p>No data available.</p>;
      } else {
        setSiList([]);
        setTotalItems(0);
      }
    } catch (error) {
      setSiList([]);
      setTotalItems(0);
      console.error('Failed to fetch SI data', error);
    }
    setLoading(false);
  };

  const handleChange = (field) => (event) => {
    setFilters((prev) => ({
      ...prev,
      [field]: event.target.value
    }));
  };

  const handleClick = () => {
    setPage(0);
    setSearchTriggered(true);
  };

  const handleClear = () => {
    setFilters({
      stateUt: null,
      siName: null,
    });
    setPage(0);
    setSearchTriggered(true);
  };

  console.log("siNameList:", siNameList);
  console.log("filters", filters);
  return (
    <Grid item container sx={{ width: "100%" }}>
      <Card sx={{ p: 3, width: "100%" }}>
        <Grid container spacing={2}>
          {/* State/UT */}
          <Grid item xs={12} sm={4}>
            <CusReqDropdownSIPayment
              // @ts-ignore
              formDataAtom={siFundsFilterAtom}
              // @ts-ignore
              listDataAtom={siStateListAtom}
              ddLabel="State/ UT"
              dropdownName="stateUt"
              fetchMasterDataURL="fetchStateMasterData_CusReq"
              // @ts-ignore
              optionLabel={["StateNameAndCode", "name", "short_name", "code"]}
              value={filters.stateUt || ""}
              onChange={handleChange("stateUt")}
            />
          </Grid>
          {/* SI Name */}
          {/* <Grid item xs={12} sm={4}> */}
          {/* @ts-ignore */}
          {/* <CusReqDropdownSIPayment */}
          {/* // @ts-ignore */}
          {/* formDataAtom={siFundsFilterAtom} */}
          {/* // @ts-ignore
       listDataAtom={siNameListAtom}
       ddLabel="SI Name"
       dropdownName="siName"
       // @ts-ignore
        fetchMasterDataURL="/si-payments/siswithStates"
        // @ts-ignore
       optionLabel={["sis", "state", "siId"]}
       value={filters.siName || ""}
       onChange={handleChange("siName")}
      /> */}
          {/* </Grid> */}
          <Grid item xs={12} sm={4}>
            {siNameList.length > 0 && (
              <CusReqDropdownSIPayment
                ddLabel="SI Name"
                dropdownName="siName"
                // @ts-ignore
                formDataAtom={siFundsFilterAtom}
                listDataAtom={siNameListAtom}
                optData={siNameList}
                // @ts-ignore
                optionLabel={["siName", "siType", "siId"]} // Adjust depending on what the dropdown expects
                // @ts-ignore
                value={filters.siName}
                onChange={handleChange("siName")}
              />
            )}
          </Grid>
          {/* Buttons */}
          <Grid item xs={12}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "space-between", // spread left and right
                alignItems: "center",
                mt: 2,
                flexWrap: "wrap",
              }}
            >
              {/* Left Side: Total Records */}
              <Grid
                container
                item
                xs={12}
                md={6}
                sx={{ p: 1 }}
                display="flex"
                alignItems="center"
              >
                <Typography color="GrayText" fontSize={11} fontWeight="bold" mr={1}>
                  Total Records:
                </Typography>
                <Typography fontSize={12} className="fontGreenTheme bold">
                  {totalItems}
                </Typography>
              </Grid>

              {/* Right Side: Buttons */}
              <Grid
                container
                item
                xs={12}
                md={6}
                display="flex"
                justifyContent="flex-end"
                alignItems="center"
                sx={{ gap: 1, mt: { xs: 1, md: 0 } }}
              >
                <Button
                  onClick={handleClear}
                  variant="contained"
                  color="warning"
                >
                  Reset <RestartAltRounded sx={{ width: 20, ml: 1 }} />
                </Button>
                <Button
                  onClick={handleClick}
                  variant="contained"
                  color="success"
                >
                  Search <ManageSearchOutlinedIcon sx={{ width: 20, ml: 1 }} />
                </Button>
              </Grid>
            </Box>
          </Grid>
        </Grid>

      </Card>
      <div style={{ width: '100%', mt: 2 }}>
        {/* {!loading ? <DataListingLoadingElem /> : <SiNameTable page={page} size={size} />} */}
        <SiFundTable page={page} size={size} />

        {/* Pagination */}
        <Box sx={{ display: "flex", justifyContent: "flex-end", my: 2 }}>
          <Pagination
            count={Math.ceil(totalItems / size)}
            page={page + 1}
            onChange={(_, value) => setPage(value - 1)}
            color="primary"
            shape="rounded"
          />
        </Box>
      </div>
    </Grid>
  );
}