import {
    Checkbox,
    Divider,
    Grid,
    List,
    ListItem,
    ListItemButton,
    ListItemIcon,
    ListItemText,
    TextField, Typography,
} from "@mui/material";
import {
    SubmitErrorAlertAtom,
    useRecoilState,
    renderInputErrorLabel,
    ErrorLabelAtom,
    isEmptyObject,
    formatDate,
    isObjectCus,
    genUUID,
    cusReqUATMasterDataAtom,
    yesNoArr,
    cusAccSIListAtom,
    cusAccROListAtom,
    cusAccStateListAtom,
    useRecoilValue,
    cusReqCUIMasterDetailsAtom,
    currentDate,
    currentDatePlus14,
} from "../../../../Heplers";
import React, {useEffect, useMemo} from "react";
import {
    CusReqDropdown,
    defTextFieldOnChange,
    InputsFourthRowMasterData,
} from "..";

export const InputsFirstRowUAT = ({readOnly}) => {
    const [Atom, setAtom] = useRecoilState(cusReqUATMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    // @ts-ignore
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);

    const defTextFieldOnChangeComParams = {
        setAtom,
        SubmitErrorAlert,
        setSubmitErrorAlert,
    };

    const [checked, setChecked] = React.useState([0]);

    const handleToggle = (value) => () => {
        console.log(value, Atom);

        // return null;

        let acceptedArr =
            Atom.accepted_brd_points !== undefined &&
            Atom.accepted_brd_points !== null &&
            Atom.accepted_brd_points.length > 0
                ? Atom.accepted_brd_points.split(",")
                : [];

        if (acceptedArr.includes(String(value))) {
            acceptedArr = acceptedArr.filter((e) => e !== String(value));
        } else {
            acceptedArr.push(String(value));
        }

        setAtom((prevState) => ({
            // @ts-ignore
            ...prevState,
            accepted_brd_points: acceptedArr.toString(),
        }));
        const currentIndex = checked.indexOf(value);
        const newChecked = [...checked];

        if (currentIndex === -1) {
            newChecked.push(value);
        } else {
            newChecked.splice(currentIndex, 1);
        }

        setChecked(newChecked);
    };

    const renderSavedAndAcceptedbrd_points = () => {
        const acceptedArr =
            typeof Atom.accepted_brd_points === "string" &&
            Atom.accepted_brd_points.length > 0
                ? Atom.accepted_brd_points.split(",")
                : [];

        // @ts-ignore
        if (
            CUIAtom.brd !== undefined &&
            CUIAtom.brd !== null &&
            CUIAtom.brd.brd_points !== undefined &&
            typeof CUIAtom.brd.brd_points === "string"
        ) {
            // @ts-ignore
            const brd_points =
                CUIAtom.brd.brd_points !== null
                    ? JSON.parse(`[${CUIAtom.brd.brd_points}]`)
                    : [];
            return (
                <Grid>
                    <Divider textAlign="left">
                        <Typography sx={{color: "red", fontSize: 10}}>Please check/ select the BRD Points that are
                            deployed by NLPSV and accepted by stakeholder</Typography>
                    </Divider>

                    <List sx={{width: "100%", bgcolor: "background.paper"}}>
                        {brd_points.map((value, i) => {
                            const labelId = `checkbox-list-label-${value.name}`;

                            // console.log(value, acceptedArr, acceptedArr.includes(String(value.id)))

                            return (
                                <span key={genUUID()}>
                <ListItem
                    key={value}
                    //   secondaryAction={
                    //     <IconButton edge="end" aria-label="comments">
                    //       <CommentIcon />
                    //     </IconButton>
                    //   }
                    disablePadding
                >
                  <ListItemButton
                      role={undefined}
                      onClick={handleToggle(value.id)}
                      dense
                  >
                    <ListItemIcon>
                      <Checkbox
                          edge="start"
                          checked={acceptedArr.includes(String(value.id))}
                          tabIndex={-1}
                          inputProps={{"aria-labelledby": labelId}}
                      />
                    </ListItemIcon>
                    <ListItemText
                        id={labelId}
                        primary={`${i + 1}: ` + value.name + ` (ID: ${value.id})`}
                    />
                  </ListItemButton>
                </ListItem>
                <Divider variant="inset" component="li"/>
              </span>
                            );
                        })}
                    </List>
                </Grid>

            );
        }

        return null;
    };

    const CUIAtom = useRecoilValue(cusReqCUIMasterDetailsAtom);

    useEffect(() => {
        // Setting Default Value
        // console.log(Atom)
        // For Update Form
        if (
            CUIAtom !== null &&
            CUIAtom.uat !== null &&
            isObjectCus(CUIAtom.uat) &&
            !isEmptyObject(CUIAtom.uat)
        ) {
            defTextFieldOnChange(
                formatDate(Atom.start_date, "db-yyyy-mm-dd"),
                "start_date",
                defTextFieldOnChangeComParams
            );
            // defTextFieldOnChange(
            //     formatDate(Atom.go_live_date, "db-yyyy-mm-dd"),
            //     "go_live_date",
            //     defTextFieldOnChangeComParams
            // );
            defTextFieldOnChange(
                formatDate(Atom.actual_go_live_date, "db-yyyy-mm-dd"),
                "actual_go_live_date",
                defTextFieldOnChangeComParams
            );
            defTextFieldOnChange(
                formatDate(Atom.dod, "db-yyyy-mm-dd"),
                "dod",
                defTextFieldOnChangeComParams
            );

            // DROPDOWN SHOULD NOT BE SET ON MOUNT-------------
            // defTextFieldOnChange(Atom.acceptance_si, "acceptance_si", defTextFieldOnChangeComParams);
            // defTextFieldOnChange(Atom.acceptance_state, "acceptance_state", defTextFieldOnChangeComParams);
            // defTextFieldOnChange(Atom.acceptance_ro, "acceptance_ro", defTextFieldOnChangeComParams);
        } else {
            defTextFieldOnChange(
                currentDate,
                "start_date",
                defTextFieldOnChangeComParams
            );
            defTextFieldOnChange(
                currentDatePlus14,
                "dod",
                defTextFieldOnChangeComParams
            );
        }
    }, []);

    return useMemo(() => {
        return (
            <Grid spacing={2} container>
                <Grid item xs={12} md={4} sx={{pb: {xs: 2}, pt: {md: 1}}}>
                    <TextField
                        label="Started On"
                        variant="outlined"
                        type="date"
                        defaultValue={
                            Atom !== null && typeof Atom.start_date === "string"
                                ? formatDate(Atom.start_date, "db-yyyy-mm-dd")
                                : currentDate
                        }
                        fullWidth
                        required

                        InputProps={{inputProps: { max: currentDate } }}
                        InputLabelProps={{
                            shrink: true,
                        }}
                        onChange={(e) =>
                           readOnly ? null : defTextFieldOnChange(
                                e.target.value,
                                "start_date",
                                defTextFieldOnChangeComParams
                            )
                        }

                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                    {renderInputErrorLabel(ErrorLabel, Atom.start_date, "Required")}
                </Grid>

                <Grid item xs={12} md={4} sx={{pb: {xs: 2}, pt: {md: 1}}}>
                    <TextField
                        label="NLPSV Demo On"
                        variant="outlined"
                        type="date"
                        defaultValue={
                            Atom !== null && typeof Atom.dod === "string"
                                ? formatDate(Atom.dod, "db-yyyy-mm-dd")
                                : currentDatePlus14
                        }
                        fullWidth
                        required
                        InputLabelProps={{
                            shrink: true,
                        }}
                        onChange={(e) =>
                           readOnly ? null : defTextFieldOnChange(
                                e.target.value,
                                "dod",
                                defTextFieldOnChangeComParams
                            )
                        }


                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                    {renderInputErrorLabel(ErrorLabel, Atom.start_date, "Required")}
                </Grid>

                {/*<Grid item xs={12} md={6} sx={{pb: {xs: 2}, pt: {md: 1}}}>*/}
                {/*    <TextField*/}
                {/*        label="Planned Go-Live Date"*/}
                {/*        variant="outlined"*/}
                {/*        type="date"*/}
                {/*        defaultValue={*/}
                {/*            Atom !== null && typeof Atom.go_live_date === "string"*/}
                {/*                ? formatDate(Atom.go_live_date, "db-yyyy-mm-dd")*/}
                {/*                : null*/}
                {/*        }*/}
                {/*        fullWidth*/}
                {/*        InputLabelProps={{*/}
                {/*            shrink: true,*/}
                {/*        }}*/}
                {/*        onChange={(e) =>*/}
                {/*           readOnly ? null : defTextFieldOnChange(*/}
                {/*                e.target.value,*/}
                {/*                "go_live_date",*/}
                {/*                defTextFieldOnChangeComParams*/}
                {/*            )*/}
                {/*        }*/}

                {/*        disabled={readOnly}*/}
                {/*        aria-readonly={readOnly}*/}
                {/*        readOnly={readOnly}*/}
                {/*        className={`${readOnly && 'readonlyStyle'}`}*/}
                {/*    />*/}
                {/*</Grid>*/}

                <Grid item xs={12} md={4} sx={{pb: {xs: 2}, pt: {md: 1}}}>
                    <TextField
                        label="Actual Go-Live Date"
                        variant="outlined"
                        type="date"
                        defaultValue={
                            Atom !== null && typeof Atom.actual_go_live_date === "string"
                                ? formatDate(Atom.actual_go_live_date, "db-yyyy-mm-dd")
                                : null
                        }
                        fullWidth
                        InputProps={{inputProps: { max: currentDate } }}
                        InputLabelProps={{
                            shrink: true,
                        }}
                        onChange={(e) =>
                           readOnly ? null : defTextFieldOnChange(
                                e.target.value,
                                "actual_go_live_date",
                                defTextFieldOnChangeComParams
                            )
                        }


                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                </Grid>

                <Grid item xs={12} md={4} sx={{pb: {xs: 2}, pt: {md: 1}}}>
                    <CusReqDropdown
                        // @ts-ignore
                        formDataAtom={cusReqUATMasterDataAtom}
                        listDataAtom={cusAccSIListAtom}
                        ddLabel="SI Acceptance"
                        dropdownName={"acceptance_si"}
                        optData={yesNoArr}
                        defVal={
                            isObjectCus(Atom) && !isEmptyObject(Atom)
                                ? Atom.acceptance_si
                                : null
                        }

                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                </Grid>

                <Grid item xs={12} md={4} sx={{pb: {xs: 2}, pt: {md: 1}}}>
                    <CusReqDropdown
                        // @ts-ignore
                        formDataAtom={cusReqUATMasterDataAtom}
                        listDataAtom={cusAccStateListAtom}
                        ddLabel="State Acceptance"
                        dropdownName={"acceptance_state"}
                        optData={yesNoArr}
                        defVal={
                            isObjectCus(Atom) && !isEmptyObject(Atom)
                                ? Atom.acceptance_state
                                : null
                        }


                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                </Grid>

                <Grid item xs={12} md={4} sx={{pb: {xs: 2}, pt: {md: 1}}}>
                    <CusReqDropdown
                        // @ts-ignore
                        formDataAtom={cusReqUATMasterDataAtom}
                        listDataAtom={cusAccROListAtom}
                        ddLabel="RO Acceptance"
                        dropdownName={"acceptance_ro"}
                        optData={yesNoArr}
                        defVal={
                            isObjectCus(Atom) && !isEmptyObject(Atom)
                                ? Atom.acceptance_ro
                                : null
                        }

                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                </Grid>
                <Grid item xs={12} md={4} sx={{pb: {xs: 2}, pt: {md: 1}}}>
                    <InputsFourthRowMasterData
                        formAtom={cusReqUATMasterDataAtom}
                        md={12}
                        mt={0}

                        readOnly={readOnly}
                    />
                </Grid>


                <Grid item md={12} sx={{pb: {xs: 2}, pt: {md: 1}}}>
                    {renderSavedAndAcceptedbrd_points()}
                </Grid>
            </Grid>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert, checked]);
};
