import { Autocomplete, CircularProgress, TextField } from "@mui/material";
import {
    defAtom,
    defListAtom,
    isEmptyObject,
    useRecoilState,

    SubmitErrorAlertAtom,
    isObjectCus,
} from "../../RAS_updates/Heplers";
import React, { useEffect, useMemo, useRef, useState } from "react";
import axiosInstance from "../../Services/AxiosInstance";

export const CusReqDropdownSIPayment = ({
    dropdownName,
    ddLabel = "Default Label",
    required = false,
    readOnly = false,
    fetchMasterDataURL = "",
    formDataAtom = defAtom,
    listDataAtom = defListAtom,
    defVal = {},
    optionLabel = "name",
    optionValue = "id",
    optData = [],
    multiple = false,

    // placeholder = false,
    // vMsg,
    // colClass,
    // RXJSConditionsDef = '',
    // RXJSConditionsEdit = '',
    // isMulti = false,
    // defValSerPar = '',
    // filterOption = [],
    // AddSelectToServerData = false
}) => {
    // console.log("defVal value inside the cusreq",);
    const [Atom, setAtom] = useRecoilState(formDataAtom);
    const isMounted = useRef(null);
    const netCallInProgress = useRef(false);
    const [open, setOpen] = useState(false);
    const [options, setOptions] = useRecoilState(listDataAtom);
    useEffect(() => {
        isMounted.current = true;
        APICall();
        return () => {
            isMounted.current = false;
            setAtom((prevState) => ({
                // @ts-ignore
                ...prevState,
                [dropdownName]: {},
            }));
        };
    }, []);

    const APICall = async () => {
        let serList = optData;

        if (fetchMasterDataURL !== "") {
            netCallInProgress.current = true;

            const response = await axiosInstance.post(fetchMasterDataURL);

            netCallInProgress.current = false;

            const { status, data } = response;

            if (status === 200 && Array.isArray(data) && data.length > 0) {
                if (dropdownName === 'siName') {
                    // Safely get selected state id from atom
                    const selectedStateId =
                        // @ts-ignore
                        Atom && typeof Atom === "object" && Atom.state && Atom.state.id
                            // @ts-ignore
                            ? Atom.state.id
                            : undefined;
                    // Find the state object in the response
                    const stateObj = data.find(
                        (item) => Number(item.stateId) === Number(selectedStateId)
                    );

                    // If found, use its sis array as options
                    serList = stateObj && Array.isArray(stateObj.sis) ? stateObj.sis : [];
                } else {
                    serList = data;
                }
            }
        }

        setOptions(serList);
        // Handle defVal for primitive types (like ID)
        if (!isObjectCus(defVal) && String(defVal).length > 0) {
            const defValObject = serList.filter((v) => {
                if (dropdownName === 'stateUt') {
                    return Number(v.id) === Number(defVal) || Number(v.code) === Number(defVal);
                }
                if (dropdownName === 'siName') {
                    return String(v.siId) === String(defVal) || String(v.id) === String(defVal);
                }
                return Number(v.id) === Number(defVal) || String(v.id) === String(defVal)
            })
            // console.log("DefVal is   there however fetchMaster only after fetch server data, we can set value", serList, defValObject[0]);
            setAtom((prevState) => ({
                // @ts-ignore
                ...prevState,
                [dropdownName]: defValObject[0] || defValObject,
            }));
        }

        let defValObject = null;
        // ✅ Handle defVal if it's already an object (like from saved form data)
        // console.log("isObjectCus", isObjectCus(defVal));
        // console.log("DefVal", defVal);
        // console.log("not empty object", !isEmptyObject(defVal));
        if (isObjectCus(defVal) && !isEmptyObject(defVal)) {

            // console.log("DefVal is an object, checking for specific dropdowns", defVal);
            if (dropdownName === 'stateUt') {
                defValObject = serList.find((v) => v.id === defVal.id || v.code === defVal.code);
            } else if (dropdownName === 'siName') {
                const siId = defVal?.sis?.siId || defVal.siId;
                defValObject = serList.find((v) => v.siId === siId);
            } else if (dropdownName === 'paymentMilestone') {
                defValObject = serList.find((v) => v.id === defVal.id);
            }
            console.log("DefVal is an object, setting it directly", defValObject);
        }
        if (defValObject) {
            setAtom((prevState) => ({
                // @ts-ignore
                ...prevState,
                [dropdownName]: defValObject,
            }));
        }

    };

    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);
    const handleOnChange = (value) => {
        SubmitErrorAlert && setSubmitErrorAlert(false);

        setAtom((prevState) => ({
            // @ts-ignore
            ...prevState,
            // [dropdownName]: value === null ? "" : value[optionValue],
            [dropdownName]: value === null ? {} : value,
        }));
    };

    return useMemo(() => {
        return (
            <Autocomplete
                id={dropdownName}
                multiple={multiple}
                sx={{ width: "100%" }}
                open={open}
                onOpen={() => {
                    setOpen(true);
                }}
                onClose={() => {
                    setOpen(false);
                }}
                options={options}
                readOnly={readOnly}
                loading={netCallInProgress.current}
                getOptionLabel={(option) => {
                    let label = option[optionLabel];
                    if (
                        Array.isArray(optionLabel) &&
                        optionLabel[0] === "StateNameAndCode"
                    ) {
                        label = `${option[optionLabel[1]]} (${option[optionLabel[2]]} - ${option[optionLabel[3]]})`;
                    }
                    if (dropdownName === 'siName') {
                        const name = option.siName || option.name || '';
                        const type = option.siType || option.sitype || option.type || '';
                        return `${name} | ${type}`.trim();
                    }
                    if (dropdownName === 'paymentMilestone') {
                        return option.name || '';
                    }
                    return label;
                }}
                defaultValue={defVal}
                onChange={(event, newValue) => handleOnChange(newValue)}
                value={
                    options.length === 0
                        ? (multiple ? [] : null)
                        : Atom !== null && isObjectCus(Atom[dropdownName]) && !isEmptyObject(Atom[dropdownName])
                            ? Atom[dropdownName]
                            : multiple ? [] : null
                }
                renderInput={(params) => (
                    <TextField
                        {...params}
                        label={ddLabel}
                        placeholder={
                            !Atom[dropdownName] || isEmptyObject(Atom[dropdownName])
                                ? (dropdownName === 'state'
                                    ? 'Select State'
                                    : dropdownName === 'siName'
                                        ? 'Select SI Name'
                                        : 'Select option')
                                : ''
                        }
                        InputLabelProps={{
                            shrink: true,
                        }}
                        required={required}
                        InputProps={{
                            ...params.InputProps,

                            endAdornment: (
                                <React.Fragment>
                                    {netCallInProgress.current ? (
                                        <CircularProgress color="inherit" size={20} />
                                    ) : null}
                                    {params.InputProps.endAdornment}
                                </React.Fragment>
                            ),
                        }}
                    />
                )}
            />
        );
    }, [Atom, open, options]);
};
