import React, { useState } from "react";
import { useRecoilState, useSetRecoilState } from "recoil";
import {
  siFundReleaseTableAtom,
  siFundReleaseAtom,
  siGlobalModeAtom,
  siFundMasterAtom
} from "../../RAS_updates/Heplers";
import { Card, Divider, Box } from "@mui/material";
import moment from "moment";
import "../SIPayments/SiTable.css";

const genUUID = () => Math.random().toString(36).substring(2, 10);

export const SiFundReleaseTable = ({ page = 0, size = 10 }) => {
  const [tableData] = useRecoilState(siFundReleaseTableAtom);
  const setSelectedRow = useSetRecoilState(siFundReleaseAtom);
  const [isIdColumnVisible, setIsIdColumnVisible] = useState(false);
  const [fundMaster, setFundMaster] = useRecoilState(siFundMasterAtom)
  // const setMode = useSetRecoilState(siGlobalModeAtom);

  const handleRowClick = (row) => {
    setSelectedRow(row);
    // setMode("edit");
  };

  const getStateLabel = (stateUtObj) => {
    if (stateUtObj && typeof stateUtObj === "object") {
      return `${stateUtObj.name} (${stateUtObj.short_name} - ${stateUtObj.code})`;
    }
    return "—";
  };

  if (!Array.isArray(tableData) || tableData.length === 0) {
    return <p style={{ padding: '20px' }}>No fund release data available.</p>;
  }

  return (
    <Box sx={{ width: '100%', px: 2 }}>
      <Card className="cusTable" sx={{ overflowX: "auto" }}>
        <div style={{ minWidth: "700px" }}>
          <table className="desktopTable">
            <thead>
              <tr>
                <th>Sno.</th>
                <th>Centre Share</th>
                <th>State Share</th>
                <th>State</th>
                <th>Date</th>
                {isIdColumnVisible && <th>Id</th>}
              </tr>
            </thead>
            <tbody>
              {tableData.slice(page * size, page * size + size).map((row, idx) => (
                <tr key={genUUID()}>
                  <td>{page * size + idx + 1}</td>
                  <td>
                    <span
                      style={{
                        color: "#1976d2",
                        cursor: "pointer",
                        textDecoration: "underline"
                      }}
                      onClick={() => handleRowClick(row)}
                    >
                      {row.centreShare ?? "—"}
                    </span></td>
                  <td>{row.stateShare ?? "—"}</td>
                  <td>{fundMaster.stateUt ? getStateLabel(fundMaster.stateUt) : '_'}</td>
                  <td>{row.date ? moment(row.date).format("MM/DD/YYYY") : "—"}</td>
                  {isIdColumnVisible && <td>{row.id}</td>}
                </tr>
              ))}
            </tbody>
          </table>

          {/* Mobile stacked layout */}
          <div className="mobileTable">
            {tableData.slice(page * size, page * size + size).map((row, idx) => (
              <div key={genUUID()} className="responsiveTableRow" onClick={() => handleRowClick(row)}>
                <div className="rowItem"><span>Sno.</span><span>{page * size + idx + 1}</span></div>
                <Divider className="mobileRowDivider" />
                {/* <div className="rowItem"><span>State/UT</span>
                <span>{row.stateUt && getStateLabel(row.stateUt) || "—"}</span>
              </div>
              <Divider className="mobileRowDivider" /> */}
                <div className="rowItem"><span>Centre Share</span>
                  <span
                    style={{
                      color: "#1976d2",
                      cursor: "pointer",
                      textDecoration: "underline"
                    }}
                    onClick={() => handleRowClick(row)}
                  >{row.centreShare ?? "—"}</span></div>
                <Divider className="mobileRowDivider" />
                <div className="rowItem"><span>State Share</span><span>{row.stateShare ?? "—"}</span></div>
                <Divider className="mobileRowDivider" />
                <div className="rowItem"><span>Date</span><span>{row.date ? moment(row.date).format("MM/DD/YYYY") : "—"}</span></div>
                <Divider className="mobileRowDivider" />
                <div className="rowItem"><span>State</span><span>{fundMaster.stateUt ? getStateLabel(fundMaster.stateUt) : '_'}</span></div>
                <Divider className="mobileRowDivider" />
                {isIdColumnVisible &&
                  <td><div className="rowItem"><span>Id</span><span>{row.id}</span></div></td>}
              </div>
            ))}
          </div>
        </div>
      </Card>
    </Box>
  );
};
