import {Box, Button, Divider, Grid, Paper, Stack, Typography} from "@mui/material";
import CssBaseline from "@mui/material/CssBaseline";
import Toolbar from "@mui/material/Toolbar";
import React, { useEffect, useMemo } from "react";
import DrawerComp from "../../../Components/Drawer/drawer";
import MainHeader from "../../../Components/Header/MainHeader";
import {
  BRFUploadFile, CPMUInputs,
  CusReqDetailsCard,
  HeaderMasterComp,
  InputsFourthRowMasterData,
  NLPSVInputs,
  PageLoadingElem,
  ROInputs,
  SIInputs,
  SLIMCInputs,
  SPMUInputs,
  StateInputs,
  UnderDevAlert
} from "./Components";
import {
  cusReqBRFMasterDataAtom,
  cusReqCUIMasterDetailsAtom,
  cusReqMasterDataAtom, CUSTOMIZATIONREQUEST_LINK,
  ErrorLabelAtom,
  invalidURLAlert,
  isEmptyObject, NAWarningLabel,
  pageLoadingAtom,
  paramsFromURL,
  SubmitErrorAlertAtom,
  useRecoilState
} from "../../Heplers";
import axiosInstance from "../../../Services/AxiosInstance";

import { useNavigate } from "react-router-dom";
import { InputsFirstRowBRF } from "./Components/BRDForm/InputsFirstRowBRF";
import { BRFDataSubmit } from "./Components/BRDForm/BRFDataSumbit";
import { isObject } from "@mui/x-data-grid/internals";
import uploadcld from "../../../Assets/download_btn.svg";
import UploadedFilesDisplay from "./Components/BRDForm/UploadedFilesDisplay";
import {StCBInputs} from "./Components/PreparationForm/StCBInputs";
import {getCookie, setCookie} from "../../../Services/Cookies";

export default function CustomizationRequestBRFEntryForm() {

  const [Atom, setAtom] = useRecoilState(cusReqCUIMasterDetailsAtom);
  const navigate = useNavigate();


  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);

  const [AtomBRF, setAtomBRF] = useRecoilState(cusReqBRFMasterDataAtom);

  const APICall = async (reqData) => {

    setPageLoading(true);
    axiosInstance({
      method: "post",
      url: "fetchCUIMasterData",
      data: reqData,
    }).then(function (response) {
      if (!isObject(response.data) || isEmptyObject(response.data)) {
        invalidURLAlert(`CUI: ${reqData.cui}`, "Invalid Customization Unique Identification Number")
      } else {

        console.log(response.data)
        // console.log('brd',response.data.brd, JSON.parse(response.data.brd))

        const parsedRes = {
          pre: JSON.parse(response.data.pre),
          brd: JSON.parse(response.data.brd),
          dev: JSON.parse(response.data.dev),
          uat: JSON.parse(response.data.uat),
        };
        setAtom(parsedRes);

        setAtomBRF((prevState) => ({

          // // Adding these three here because it's throwing undefined
          // start_date: null,
          // edor: null,
          // brd_points: null,


          // @ts-ignore
          ...prevState,
          ...parsedRes.brd

        }));
        setPageLoading(false)
      }
      console.log('Data =>', response.data);

    })
      .catch(function (error) {
        setPageLoading(false)
        console.error(error);
      });

  };

  const URLParams = paramsFromURL({
    linkToSplit: `${CUSTOMIZATIONREQUEST_LINK}brf/`,
  })
  const [PageLoading, setPageLoading] = useRecoilState(pageLoadingAtom);
  useEffect(() => {
    window.scrollTo({
      top: 0,
      left: 0,
      behavior: "smooth",
    });



    // console.log('Listing', URLParams)
    if (URLParams.paramId !== undefined && URLParams.paramId != "") {
      // @ts-ignore
      // if (isNaN(URLParams.paramId)) {
      if (URLParams.paramId.length < 6) {
        invalidURLAlert(`CUI: ${URLParams.paramId}`, "Invalid Customization Unique Identification Number")
      } else {
        APICall({ cui: URLParams.paramId });
      }
    }
    return () => {
      // Clearing Page Used Variables

      // @ts-ignore
      setAtom({})
      // @ts-ignore
      setAtomBRF({})

      setSubmitErrorAlert(false);
      setErrorLabel(false);
      setPageLoading(false)
    };

  }, []);

  const readOnly = (getCookie("userRole") !== "SPMU" && getCookie("userRole") !== "CPMU");

  const renderMainContent = () => {
    return <>
      <HeaderMasterComp URLParams={URLParams} stageName="Business Requirement Finalization" />

      <Grid container spacing={1} pt={1}>

        <Grid item md={4} xs={12}>
          <CusReqDetailsCard />
        </Grid>

        <Grid item md={8} xs={12}>
          <Paper elevation={2} sx={{ p: 2, mb: 4 }}>

            <InputsFirstRowBRF readOnly={readOnly} />

            {!readOnly && <BRFUploadFile formAtom={cusReqBRFMasterDataAtom} />}

            <Grid item xs={12} mt={4}>
              <Divider textAlign="left">
                <Typography className={'greenText'} fontSize={14} fontWeight="bold">Stakeholder Inputs</Typography>
              </Divider>

              {NAWarningLabel()}

            </Grid>

            <Grid container spacing={2} direction={"row"}>
              <SIInputs formAtom={cusReqBRFMasterDataAtom} md={6} readOnly={readOnly}/>

              <StateInputs formAtom={cusReqBRFMasterDataAtom} md={6} readOnly={readOnly}/>
            </Grid>

            <Grid container spacing={2} direction={"row"}>
              <StCBInputs formAtom={cusReqBRFMasterDataAtom} md={6} readOnly={readOnly}/>
              <SLIMCInputs formAtom={cusReqBRFMasterDataAtom} md={6} readOnly={readOnly}/>

            </Grid>

            <Grid container spacing={2} direction={"row"}>
              <SPMUInputs formAtom={cusReqBRFMasterDataAtom} md={6} readOnly={readOnly}/>
              <ROInputs formAtom={cusReqBRFMasterDataAtom} md={6} readOnly={readOnly}/>

            </Grid>

            <Grid container spacing={2} direction={"row"}>
              <CPMUInputs formAtom={cusReqBRFMasterDataAtom} md={6} readOnly={readOnly}/>
              <NLPSVInputs formAtom={cusReqBRFMasterDataAtom} md={6} edodInput={true} edorfInput={false} plannedGoLive={false} readOnly={readOnly}/>
            </Grid>

            <BRFDataSubmit />
          </Paper>
        </Grid>
      </Grid>


    </>
  }

  return useMemo(() => {
    return (
      <div>
        <style>
          {`
                    .css-10hburv-MuiTypography-root{
                      font-size:11px !important;
                      font-family: Poppins 
                    }
                    .css-yb0lig{
                      font-size:12px !important
                    }
                    `}
        </style>

        <Box sx={{ display: "flex", mt: 5 }}>
          <CssBaseline />
          {/* @ts-ignore*/}
          <MainHeader />
          <DrawerComp listName={"Customization Request"} />
          <Box
            component="main"
            sx={{
              flexGrow: 1,
              backgroundColor: "#f4faf8",
              px: 1,
              // pr: 4,
              // @ts-ignore
              // height: isEmptyObject(URLParams) ? "100vh" : "auto",
            }}
          >
            <Toolbar />

            {/*<UnderDevAlert />*/}
            <PageLoadingElem />

            {!PageLoading && renderMainContent()}


          </Box>
        </Box>
      </div>
    )
  }, [PageLoading]);
}
