import React, { useState, useEffect } from 'react';
import Chart from 'react-apexcharts';
import { Box, Tabs, Tab, Typography, Stack, TextField, MenuItem } from '@mui/material';
import axiosInstance from '../../Services/AxiosInstance';
import { getCookie } from '../../Services/Cookies';

const SIInvoiceChart = () => {
 const [tab, setTab] = useState(0);
 const [stateNames, setStateNames] = useState([]);
 const [selectedState, setSelectedState] = useState('');
 const [topPaidData, setTopPaidData] = useState({});
 const [topUnpaidData, setTopUnpaidData] = useState({});
 const [stateData, setStateData] = useState({});
 const [allSIData, setAllSIData] = useState({});

 const config = {
  headers: {
   email: getCookie("email2"),
   "access-token": getCookie("token"),
   Authorization: `Bearer ${getCookie("token")}`,
  },
 };

 // Fetch all state names for dropdown
 useEffect(() => {
  const fetchStates = async () => {
   try {
    const res = await axiosInstance.post('/siFundMastergraph/state-wise-summary', config);
    if (res.status === 200) {
     setStateNames(Object.keys(res.data));
    }
   } catch (err) {
    console.error("Error fetching state names:", err);
   }
  };
  fetchStates();
 }, []);

 useEffect(() => {
  if (tab !== 2) return;
  const fetchAllSIs = async () => {
   try {
    const res = await axiosInstance.post('/siFundMastergraph/all-sis', config);
    if (res.status === 200) {
     setAllSIData(res.data);
    }
   } catch (err) {
    console.error("Error fetching all SIs:", err);
   }
  };
  fetchAllSIs();
 }, [tab]);

 // Fetch top 5 paid SIs
 useEffect(() => {
  if (tab !== 0) return;
  const fetchTopPaid = async () => {
   try {
    const res = await axiosInstance.post('/siFundMastergraph/top5-states-paid', config);
    if (res.status === 200) {
     setTopPaidData(res.data);
    }
   } catch (err) {
    console.error("Error fetching top 5 paid SIs:", err);
   }
  };
  fetchTopPaid();
 }, [tab]);

 // Fetch top 5 unpaid SIs
 useEffect(() => {
  if (tab !== 1) return;
  const fetchTopUnpaid = async () => {
   try {
    const res = await axiosInstance.post('/siFundMastergraph/top5-states-unpaid', config);
    if (res.status === 200) {
     setTopUnpaidData(res.data);
    }
   } catch (err) {
    console.error("Error fetching top 5 unpaid SIs:", err);
   }
  };
  fetchTopUnpaid();
 }, [tab]);

 // Fetch SI data by state
 useEffect(() => {
  if (tab !== 3 || !selectedState) return;
  const fetchStateData = async () => {
   try {
    const res = await axiosInstance.post(`/siFundMastergraph/by-state?stateName=${encodeURIComponent(selectedState)}`, config);
    if (res.status === 200) {
     setStateData(res.data);
    }
   } catch (err) {
    console.error("Error fetching SI data by state:", err);
   }
  };
  fetchStateData();
 }, [tab, selectedState]);

 // Prepare chart data for each tab
 const prepareSeries = () => {
  if (tab === 0) {
   // Top 5 Paid
   const paid = Object.values(topPaidData).map(d => d.paid);
   const unpaid = Object.values(topPaidData).map(d => d.unpaid);
   return [
    { name: 'Paid', data: paid },
    { name: 'Unpaid', data: unpaid }
   ];
  }
  if (tab === 1) {
   // Top 5 Unpaid
   const paid = Object.values(topUnpaidData).map(d => d.paid);
   const unpaid = Object.values(topUnpaidData).map(d => d.unpaid);
   return [
    { name: 'Paid', data: paid },
    { name: 'Unpaid', data: unpaid }
   ];
  }
  if (tab === 2) {
   // All SI (flattened SI+State)
   const paid = [];
   const unpaid = [];
   Object.entries(allSIData).forEach(([siName, statesObj]) => {
    Object.entries(statesObj).forEach(([state, values]) => {
     paid.push(values.paid);
     unpaid.push(values.unpaid);
    });
   });
   return [
    { name: 'Paid', data: paid },
    { name: 'Unpaid', data: unpaid }
   ];
  }
  if (tab === 3) {
   // By State: SI names as keys
   const paid = Object.values(stateData).map(d => d.paid);
   const unpaid = Object.values(stateData).map(d => d.unpaid);
   return [
    { name: 'Paid', data: paid },
    { name: 'Unpaid', data: unpaid }
   ];
  }
  return [];
 };

 // Prepare categories (x-axis labels)
 const prepareCategories = () => {
  if (tab === 0) {
   // Top 5 Paid
   return Object.entries(topPaidData).map(([state, d]) => `${d.siName} (${state})`);

  }
  if (tab === 1) {
   // Top 5 Unpaid
   return Object.entries(topUnpaidData).map(([state, d]) => `${d.siName} (${state})`);
  }
  if (tab === 2) {
   // All SI (flattened SI+State)
   const categories = [];
   Object.entries(allSIData).forEach(([siName, statesObj]) => {
    Object.entries(statesObj).forEach(([state, values]) => {
     categories.push(`${siName} (${state})`);
    });
   });
   return categories;
  }
  if (tab === 3) {
   // By State
   return Object.keys(stateData);
  }
  return [];
 };

 const isHorizontal = tab === 2;
 const chartOpts = {
  chart: { type: 'bar', background: '#D9D9D980' },
  plotOptions: {
   bar: {
    horizontal: isHorizontal,
    columnWidth: isHorizontal ? '60%' : '80%',
    barHeight: isHorizontal ? '100%' : undefined,
    borderRadius: 4,
    dataLabels: { position: 'center' },
   },
  },
  xaxis: {
   categories: prepareCategories(),
   labels: {
    rotate: -45,
    style: {
     fontSize: '12px',
     fontFamily: 'Poppins',
     colors: ['#000'],
    },
    formatter: (value) => {
     // Show only first 15 chars, add ... if longer
     if (value.length > 15) {
      return value.slice(0, 15) + '...';
     }
     return value;
    }
   },
  },
  tooltip: {
   y: {
    formatter: (val, { dataPointIndex }) => {
     if (tab === 0) {
      const entries = Object.entries(topPaidData);
      if (entries[dataPointIndex]) {
       const [state, d] = entries[dataPointIndex];
       return `${d.siName} (${state}): ${val} Cr`;
      }
     } else if (tab === 1) {
      const entries = Object.entries(topUnpaidData);
      if (entries[dataPointIndex]) {
       const [state, d] = entries[dataPointIndex];
       return `${d.siName} (${state}): ${val} Cr`;
      }
     } else if (tab === 2) {
      const d = allSIData[dataPointIndex];
      if (d) {
       return `${d.siName} (${d.state}): ${val} Cr`;
      }
     } else if (tab === 3) {
      const siNames = Object.keys(stateData);
      if (siNames[dataPointIndex]) {
       return `${siNames[dataPointIndex]}: ${val} C`;
      }
     }
     return val;
    }
   }
  },
  dataLabels: {
   enabled: true,
   style: {
    fontSize: '12px',
    colors: ['#808080'],
    Padding: '4px',
   },
   formatter: (val) => `${val} Cr`, 
   offsetX: isHorizontal ? -6 : 0,
   offsetY: isHorizontal ? 0 : -8,
   orientation: isHorizontal ? 'horizontal' : 'vertical',
   textAnchor: 'middle',
  },
  legend: { position: 'bottom' },
 };

 const dynamicHeight = () => {
  if (tab === 2) {
    // Count total SI+State pairs
    let count = 0;
    Object.values(allSIData).forEach(statesObj => {
      count += Object.keys(statesObj).length;
    });
    return Math.max(400, count * 45); // 45px per bar, tweak as needed
  }
  const count =
    tab === 0
      ? Object.keys(topPaidData).length
      : tab === 1
        ? Object.keys(topUnpaidData).length
        : Object.keys(stateData).length;
  return Math.max(400, count * (isHorizontal ? 40 : 60));
};

 return (
  <Box sx={{
   overflowX: isHorizontal ? 'auto' : 'hidden',
   overflowY: isHorizontal ? 'auto' : 'hidden',
   maxHeight: isHorizontal ? '600px' : 'auto',
   padding: 2,
   backgroundColor: '#f4f4f4',
   borderRadius: '8px',
  }}>
   <Typography
    sx={{
     fontSize: '18px',
     fontWeight: 600,
     fontFamily: 'Poppins',
     marginBottom: 2,
     textAlign: 'left',
     color: '#333'
    }}
   >
    SI based Invoice Report
   </Typography>
   <Tabs
    value={tab}
    onChange={(_, v) => setTab(v)}
    sx={{ mb: 2 }}
   >
    <Tab label="Top 5 Paid" />
    <Tab label="Top 5 Unpaid" />
    <Tab label="All SI" />
    <Tab label="Search by State" />
   </Tabs>
   {tab === 3 && (
    <Stack direction="row" alignItems="center" spacing={2} sx={{ mb: 2 }}>
     <TextField
      select
      label="Search by State"
      value={selectedState}
      onChange={e => setSelectedState(e.target.value)}
      sx={{ minWidth: 220 }}
      placeholder="Search by State"
     >
      {stateNames.map((state, idx) => (
       <MenuItem key={state} value={state}>
        {state}
       </MenuItem>
      ))}
     </TextField>
    </Stack>
   )}
   <Chart
    options={chartOpts}
    series={prepareSeries()}
    type="bar"
    width="100%"
    height={dynamicHeight()}
    className={`si-invoice-chart ${isHorizontal ? 'horizontal-mode' : ''}`}
   />
  </Box>
 );
};

export default SIInvoiceChart;