import {
    Button,
    Chip,
    Divider,
    Grid,
    Typography,
} from "@mui/material";
import React, { useMemo } from "react";
import {
    cusReqCUIMasterDetailsAtom, displayDownloadableFilesLinks,
    genUUID, isARDBCusReqTabActive,
    isObjectCus, overViewTabAtom,
    useRecoilValue,
} from "../../../../Heplers";
import {
    chipSX,
    renderPriorityChips,
} from "..";
import moment from "moment";

export const renderInputsChipsPendingClosed_CardDetails = (data) => {
    return (
        <Grid ml={1}>
            {data.length === 0 ? (
                <Chip
                    label="Closed"
                    color="success"
                    sx={{ fontSize: 12, mt: 1, mr: 1, p: 0.01 }}
                />
            ) : (
                data.map((v) => (
                    <Chip
                        key={v}
                        className="inputRecChip"
                        label={String(v).replace(/_/g, " ").toUpperCase()}
                        sx={{
                            backgroundColor: "#B71C1C",
                            color: "#FFF",
                            mr: 0.5,
                            mt: 0.5,
                        }}
                        size="small"
                    />
                ))
            )}
        </Grid>
    );
};

export const createrArrOfInputs = (pre, stakeholderName, pendingInputs, stakeholderInputs) => {

    // console.log(pre);

    (pre[stakeholderName + "_status"] === null
    //     || (
    //     pre[stakeholderName + "_status"] !== 'Approved' &&
    //     pre[stakeholderName + "_status"] !== 'Rejected' &&
    //     pre[stakeholderName + "_status"] !== 'Not Applicable'
    //
    // )

    ) ? pre.inputs_closed !== 'Yes' && pendingInputs.push(stakeholderName.toUpperCase()) : stakeholderInputs.push({
        name: stakeholderName.toUpperCase(),
        ['date']: pre[stakeholderName + '_date'],
        ['status']: pre[stakeholderName + '_status'],
        ['inputs']: pre[stakeholderName + '_inputs']
    })
}

export const renderApprovedYesChips = (v) => {
    return v !== null && (<Button key={genUUID()} sx={{ minWidth: "unset", borderRadius: 10, fontSize: 8, p: "0.1px 8px", alignItems: "end" }} size="small" variant="outlined" color={(v.toLowerCase() === "approved" || v.toLowerCase() === "yes" ? "success" : "error")} disableElevation>{v}</Button>)
}

export const inputsRender = (stakeholderInputs, headerText = "Stakeholder Inputs", ml = 0, statusKey = "Status") => stakeholderInputs.length > 0 && <Grid key={genUUID()} ml={ml}>
    <Divider key={genUUID()} sx={{ my: 1, width: "25%" }} />
    <b key={genUUID()}>{headerText}:</b>
    {stakeholderInputs.map((v, i) => (
        <span key={genUUID()}>
            <Grid key={genUUID()} ml={1} display={"flex"} container direction={"row"}><Typography sx={{ fontWeight: 600, fontSize: 11, pr: 0.5 }}>{String(v.name).replace(/_/g, " ").toUpperCase()} Date:</Typography>{v.date !== null && moment(v.date, "YYYY-MM-DD").format("DD-MMM-YY")}</Grid>

            <Grid key={genUUID()} ml={1} display={"flex"} container direction={"row"}><Typography sx={{ fontWeight: 600, fontSize: 11, pr: 0.5 }}>{String(v.name).replace(/_/g, " ").toUpperCase()} {statusKey}:</Typography>

                {(statusKey === "Status") ? renderApprovedYesChips(v.status) : v.status}

            </Grid>

            <Grid key={genUUID()} ml={1} display={"flex"} container direction={"row"}><Typography sx={{ fontWeight: 600, fontSize: 11, pr: 0.5 }}>{String(v.name).replace(/_/g, " ").toUpperCase()} Inputs:</Typography>{v.inputs}</Grid>
            {stakeholderInputs.length !== i + 1 && <Divider sx={{ my: 1, width: "25%" }} />}
        </span>
    ))}
</Grid>

export const systemCreationRender = (pre) => {

    if (pre === null || !isObjectCus(pre)) {
        return null;
    }

    const created_by = JSON.parse(pre.created_by)

    return (<><Divider key={genUUID()} sx={{ my: 1, width: "25%" }} />
        <b>System Created Details:</b>

        <Grid ml={1} display={"flex"} container direction={"row"}><Typography sx={{ fontWeight: 600, fontSize: 12, pr: 0.5 }}>User:</Typography>{created_by.user_name}</Grid>

        <Grid ml={1} display={"flex"} container direction={"row"}><Typography sx={{ fontWeight: 600, fontSize: 12, pr: 0.5 }}>Email:</Typography>{created_by.email}</Grid>

        <Grid ml={1} display={"flex"} container direction={"row"}><Typography sx={{ fontWeight: 600, fontSize: 12, pr: 0.5 }}>User Type:</Typography>{created_by.user_type}</Grid>

        <Grid ml={1} display={"flex"} container direction={"row"}><Typography sx={{ fontWeight: 600, fontSize: 12, pr: 0.5 }}>Created At:</Typography>{moment(pre.created_at).format("lll")}</Grid></>)
}
export const pendingInputsRender = (pendingInputs, headerText = "Stakeholder Pending Inputs", ml = 0) => pendingInputs.length > 0 && (
    <Grid ml={ml}>
        <Divider sx={{ my: 1, width: "25%" }} />
        <b>{headerText}:</b> <br />
        {renderInputsChipsPendingClosed_CardDetails(pendingInputs)}
    </Grid>
)

export const CardStagesHeader = (v) => <Divider sx={{ my: 2 }} className="OverviewCardTableCellStages" textAlign="left"> {v}</Divider>
export function CusReqDetailsCard_Pre() {
    const Atom = useRecoilValue(cusReqCUIMasterDetailsAtom);
    const cusReqTabIndex = useRecoilValue(overViewTabAtom);
    return useMemo(() => {

        const { pre } = Atom;
        const pendingInputs = [];
        const stakeholderInputs = [];


        // Common stakeholders
        createrArrOfInputs(pre, 'pacs', pendingInputs, stakeholderInputs);
        createrArrOfInputs(pre, 'si', pendingInputs, stakeholderInputs);
        createrArrOfInputs(pre, 'stcb', pendingInputs, stakeholderInputs);
        createrArrOfInputs(pre, 'state', pendingInputs, stakeholderInputs);
        createrArrOfInputs(pre, 'slimc', pendingInputs, stakeholderInputs);
        createrArrOfInputs(pre, 'spmu', pendingInputs, stakeholderInputs);
        createrArrOfInputs(pre, 'ro', pendingInputs, stakeholderInputs);
        createrArrOfInputs(pre, 'cpmu', pendingInputs, stakeholderInputs);
        createrArrOfInputs(pre, 'nlpsv', pendingInputs, stakeholderInputs);
        createrArrOfInputs(pre, 'ho', pendingInputs, stakeholderInputs);

        if(pre.ardb_pacs ===  "Yes"){
            //     Only ARDB Stakeholder
            createrArrOfInputs(pre, 'scardb_branch', pendingInputs, stakeholderInputs);
            createrArrOfInputs(pre, 'pcardb_ho', pendingInputs, stakeholderInputs);
            createrArrOfInputs(pre, 'pcardb_branch', pendingInputs, stakeholderInputs);

            // Renaming replaced stakeholders
            pendingInputs.forEach(function(value, index, theArray) {
                switch (value.toUpperCase()){
                    case "PACS":
                        theArray[index] = "SCARDB_SU";
                        break;
                    case "STCB":
                        theArray[index] = "SCARDB_HO";
                        break;
                    case "NLPSV":
                        theArray[index] = "NUSV";
                        break;
                    default:
                        break;
                }
            });

            stakeholderInputs.forEach(function(value, index, theArray) {
                switch (value.name.toUpperCase()){
                    case "PACS":
                        theArray[index].name = "SCARDB_SU";
                        break;
                    case "STCB":
                        theArray[index].name = "SCARDB_HO";
                        break;
                    case "NLPSV":
                        theArray[index].name = "NUSV";
                        break;
                    default:
                        break;
                }
            });
        }

        console.log(pendingInputs, stakeholderInputs);


        const arr = (pre.brd_file !== undefined && pre.brd_file !== null && pre.brd_file.length > 0) ? pre.brd_file.split(',') : [];
        console.log(pre, arr)

        return (
            <>
                {CardStagesHeader("Preparation")}

                <b>Status :</b> <br />
                {
                    pre.inputs_closed === 'Yes' ? <Chip size="small"  className="inputRecChip" label="Closed" color="success" sx={chipSX}/> : <Chip size="small" className="inputRecChip"  label="Pending" color="error" sx={{...chipSX, backgroundColor: "#B71C1C"}}/>
                }

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Request Priority :</b> <br />
                {renderPriorityChips(pre.priority)}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Integration Type:</b> <br /> {pre.integration_type}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Name of Portal To be Integrated:</b> <br /> {pre.portal_name_int}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Ageing:</b> <br /> {pre.ageing}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Assigned To:</b><br /> {pre.assigned_to}

                {/*<Divider sx={{ my: 1, width: "25%" }} />*/}
                {/*<b>Is this For ARDB:</b><br /> {pre.ardb_pacs}*/}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Expected Date of Preparation Resolution:</b> <br /> {moment(pre.edor, "YYYY-MM-DD").format("DD-MMM-YY")}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Request Addressed To | {isARDBCusReqTabActive(cusReqTabIndex) === 'Yes' ? 'NUSV' : 'NLPSV'} Resource Name:</b><br /> {pre.addto}
                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Addressed Via:</b> <br /> {pre.addvia}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Portal/ Product:</b><br /> {pre.portal}
                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Module:</b> <br /> {pre.module}
                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Type of Change/ Theme:</b> <br /> {pre.type_of_change}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Is there deviation from regulation:</b><br /> {pre.deviation}


                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Is showstopper:</b> <br /> {pre.showstopper}
                <Divider sx={{ my: 1, width: "25%" }} />
                <b>No. of PACS impacted if showstopper:</b> <br /> {pre.showstopper_pacs_no}
                <Divider sx={{ my: 1, width: "25%" }} />

                <b>Is showstopper For Audit:</b> <br /> {pre.showstopper_audit}
                <Divider sx={{ my: 1, width: "25%" }} />

                <b>Is showstopper For Dayend:</b> <br /> {pre.showstopper_dayend}

                {pendingInputsRender(pendingInputs)}

                {inputsRender(stakeholderInputs)}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Uploaded Documents:</b> <br /> {displayDownloadableFilesLinks(arr)}

                {Number(pre.dump_via_excel) === 1 && <><Divider sx={{ my: 1, width: "25%" }} /><b>Dump via Excel:</b> Yes<br /></>}

                {systemCreationRender(pre)}

            </>
        );
    }, []);
}
