import {FormControlLabel, FormLabel, Radio, RadioGroup} from "@mui/material";
import {defAtom, genUUID, useRecoilState,} from "../../../Heplers";
import React, {useEffect, useMemo, useRef, useState} from "react";

export const RadioYesNo = ({
                               radioName,
                               ddLabel = "YesNo Label",
                               ddLabelID = genUUID(),
                               required = false,
                               readOnly = false,
                               formDataAtom = defAtom,
                               defVal = "Yes",
                               YesValue = "Yes",
                               NoValue = "No",
                               className = "",
                           }) => {
    const [Atom, setAtom] = useRecoilState(formDataAtom);
    const isMounted = useRef(null);

    const [open, setOpen] = useState(false);

    useEffect(() => {
        isMounted.current = true;

        // console.log('Mounting', radioName)

        return () => {
            isMounted.current = false;
            setAtom((prevState) => ({
                // @ts-ignore
                ...prevState,
                [radioName]: defVal,
            }));
        };
    }, []);

    const handleOnChange = (value) => {

        console.log(value);

        setAtom((prevState) => ({
            // @ts-ignore
            ...prevState,
            [radioName]: value,
        }));
    };

    return useMemo(() => {
        // console.log('CusDrop', Atom, radioName)
        return (
            <>
                <FormLabel className={"radioLabelFix"} id={ddLabelID}>{ddLabel}</FormLabel>
                <RadioGroup
                    row
                    aria-labelledby={ddLabelID}
                    name={ddLabelID}
                    defaultValue={defVal}
                    onChange={(e) => handleOnChange(e.target.value)}
                >
                    <FormControlLabel value={YesValue} control={<Radio/>} label={YesValue}/>
                    <FormControlLabel value={NoValue} control={<Radio/>} label={NoValue}/>
                </RadioGroup>
            </>
        );
    }, [Atom, open]);
};
