export function Bar({ height, statename,img, num, ml }) {
  let s2;
  if (statename === "Andaman and Nicobar Islands") {
    s2 = "Andaman";
  } else if (statename === "Arunachal Pradesh") {
    s2 = "Arunachal Pradesh";
  } else if (statename === "Jammu and Kashmir") {
    s2 = "J&K";
  } 
  else if (statename === "Andhra Pradesh") {
    s2 = "Andhra Pradesh";
  }
  else if (statename.split(' ').length > 1) {
    const initial = statename
      .split(' ')
      .map(name => name[0])
      .join('');

    if (initial === "AaNI") {
      s2 = "Andaman";
    } else if (initial === "JaK") {
      s2 = "J&K";
    } else {
      s2 = initial;
    }
  } else {
    s2 = statename;
  }
  
  const maxHeight = 100;
  const dynamicHeight = maxHeight * (height / 100);
  return (
    <>
      <div style={{marginTop:"0px"}}>
      <img src={img} alt="" style={{
        marginLeft: "-19px",
        marginBottom: `-${maxHeight - dynamicHeight + 7}px`,
        content:"hi"
      }}
      />
      <span 
      style={{
        marginLeft: ml,
        // top: `${maxHeight - dynamicHeight-num}px`,
        zIndex:1000,
        position:"absolute",
        fontFamily:"Poppins",
        fontSize:"14px",
        fontWeight:600,
        bottom:`${dynamicHeight+num}px`
      }}
      >{height}%</span>
      </div>

      <Box
        sx={{
          width: "70px",
          background: "linear-gradient(180deg, #047442 0%, #14B47C 100%)",
          borderRadius: "6px",
          zIndex: "-1",
          height: dynamicHeight + "px",
          marginTop: maxHeight - dynamicHeight + "px",
        }}
      >
      </Box>
      <span style={{
        fontFamily: "Poppins",
        fontWeight: 600,
        fontSize: "12px",
        textAlign: "center",
        marginLeft:"-8px",
        width: "80px",
        position:"absolute",
        bottom: s2 === "Arunachal Pradesh" || s2 === "Andhra Pradesh" ? "-35px" : "-20px",
        zIndex:1000,
      }}>
        {s2}
      </span>
    </>

  )
}