import React, { useEffect, useState } from "react";
import Box from "@mui/material/Box";
import { CssBaseline, Toolbar, Grid } from "@mui/material";
import DrawerComp from "../../Components/Drawer/drawer";
import MainHeader from "../../Components/Header/MainHeader";
import axiosInstance from "../../Services/AxiosInstance";
import { renderSubmitErrorAlert } from "../../RAS_updates/Heplers";
import { useRecoilValue, useRecoilState } from 'recoil';
import { siFundsFilterTableAtom, siFundGlobatMasterIdAtom, siFundMasterAtom, siFundReleaseTableAtom, siFundTotalSancTableAtom, siNameListAtom, siFundSiNameListAtom } from '../../RAS_updates/Heplers';
import { useParams } from "react-router-dom";
import SiFundMasterCard from "./SiFundsMasterForm";
import SiFundReleaseCard from "./SiFundReleaseCard";
import { SiFundReleaseTable } from "./SiFundReleaseTable";
import SiFundTotalSancCard from "./SiFundTotalSancsPACSCard";
import { SiFundTransSancPACSTable } from "./SiFundTotalSancsPACSTable";
export default function SiFundsUpdateForm() {
  const { id } = useParams();
  const [globalFundId, setGlobalFundId] = useRecoilState(siFundGlobatMasterIdAtom);
  const [sifundReleaseTable, setSiFundReleaseTable] = useRecoilState(siFundReleaseTableAtom);
  const [siFundTotalSancsTable, setSiFundTotalSancsTable] = useRecoilState(siFundTotalSancTableAtom);
  const [form, setForm] = useRecoilState(siFundMasterAtom);
  const [siNameList, setSiNameList] = useRecoilState(siFundSiNameListAtom);
  useEffect(() => {
    window.scrollTo({
      top: 0,
      left: 0,
      behavior: "smooth",
    });
  }, []);

  useEffect(() => {
    const fetchFundSubClasses = async () => {
      try {
        const res = await axiosInstance.post(
          `/siFundMaster/FundMasterSubClasses?fundMasterId=${id}`
        );

        if (res.status === 200 && res.data?.fundMasterDetails?.siFundMaster) {
          // Set SI Card Atom
          setForm({
            siId: id,
            ...res.data.fundMasterDetails.siFundMaster,
          });
          if (id) setGlobalFundId(Number(id));
          setSiNameList(res.data.siMasters.sis);

          if (
            res.data.fundMasterDetails.siFundReleaseList &&
            res.data.fundMasterDetails.siFundReleaseList.length > 0
          ) {
            setSiFundReleaseTable(res.data.fundMasterDetails.siFundReleaseList);
          }

          if (
            res.data.fundMasterDetails.siTotalSancMasterList &&
            res.data.fundMasterDetails.siTotalSancMasterList.length > 0
          ) {
            setSiFundTotalSancsTable(res.data.fundMasterDetails.siTotalSancMasterList);
          }
        } else {
          renderSubmitErrorAlert(res.data?.error || "Operation failed");
        }
      } catch (err) {
        console.error("Fetch error:", err);
        renderSubmitErrorAlert("Something went wrong");
      }
    };

    fetchFundSubClasses(); // Call the async function
  }, [id]);



  return (
    <div style={{ overflowX: "hidden" }}>
      <style>
        {`
            .css-10hburv-MuiTypography-root{
              font-size:11px !important;
              font-family: Poppins 
            }
            .css-yb0lig{
              font-size:12px !important
            }
            `}
      </style>
      <Box sx={{ display: "flex" }}>
        <CssBaseline />
        <MainHeader />
        <DrawerComp listName={"SI Work Order"} />
        <Box
          component="main"
          sx={{
            flexGrow: 1,
            backgroundColor: "#f4faf8",
          }}>
          <Toolbar />
          <Grid container spacing={2}>
            <Grid item xs={12}>
              <SiFundMasterCard />
            </Grid>
            <Grid item xs={12}>
              <SiFundReleaseCard />
            </Grid>
            <Grid item xs={12}>
              <SiFundReleaseTable />
            </Grid>
            <Grid item xs={12}>
              <SiFundTotalSancCard />
            </Grid>
            <Grid item xs={12}>
              <SiFundTransSancPACSTable />
            </Grid>
          </Grid>
        </Box>
      </Box>
    </div>
  );
}
