import React, { useEffect } from 'react';
import { Card, Grid, TextField, Button, MenuItem, Typography, Box, ButtonGroupContext } from "@mui/material";
import { getCookie } from "../../Services/Cookies";
import axiosInstance from "../../Services/AxiosInstance";
import { renderSubmitErrorAlert, useSuccessAndResetAlert } from "../../RAS_updates/Heplers";
import { useRecoilState, useSetRecoilState, useRecoilValue } from "recoil";
import { siWODataAtom, siGlobalModeAtom ,globalSiIdAtom} from "../../RAS_updates/Heplers";
import { SiNameTable } from './SiNameTable';
import { RestartAltRounded } from "@mui/icons-material";
import ManageSearchOutlinedIcon from "@mui/icons-material/ManageSearchOutlined";

export default function SiNameCard() {
  const [atomField, setFieldAtom] = useRecoilState(siWODataAtom);
  // const [mode, setMode] = useRecoilState(siGlobalModeAtom);
  // const mode = useRecoilValue(modeSiWODataAtom); // <-- Get current mode
  const successAlertAndReset = useSuccessAndResetAlert(siWODataAtom);
  const [globalSiId, setGlobalSiId] = useRecoilState(globalSiIdAtom);
  // useEffect(() => {
  //   if (atomField.siId) {
  //     setMode("edit");
  //   } else {
  //     setMode("create");
  //   }
  // }, [atomField.siId, setMode]);

  const handleClearCard1 = () => {
    setFieldAtom({
      createdBy: 0,
      siName: "",
      siId: 0,
      siType: ""
    });
    // setMode("create"); // Reset mode to create on clear
  };

  const handleChange = (field) => (event) => {
    setFieldAtom({
      ...atomField,
      [field]: event.target.value
    });
  };

  const handleSaveOrUpdate = async () => {
    const user_id = getCookie("resourceId");

    const payload = {
      siName: atomField.siName,
      siType: atomField.siType,
      createdBy: user_id,
      id:globalSiId

    };

    // if (mode === "edit") {
    //   payload.id = atomField.siId;
    // }

    try {
      const url = "/siMaster/update";
      const res = await axiosInstance.post(url, payload);

      if (res.status === 200 && res.data.message) {
        setFieldAtom(prev => ({
          ...prev,
          siId: res.data.siId || prev.siId
        }));
        successAlertAndReset(res.data.message);
      } else {
        renderSubmitErrorAlert(res.data.error || "Operation failed");
      }
    } catch (err) {
      renderSubmitErrorAlert("Something went wrong");
    }
  };

  return (
    <Grid item container sx={{ width: "100%" }}>
      <Card sx={{ p: 3, width: "100%" }}>
        <Typography variant="h6" sx={{ mb: 2 }}>SI Master</Typography>
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            gap: 2,
            flexWrap: { xs: "wrap", sm: "nowrap" }
          }}
        >
          <TextField
            label="SI Name"
            value={atomField.siName || ""}
            onChange={handleChange("siName")}
            sx={{ flex: 1 }}
          />
          <TextField
            select
            label="SI Type"
            value={atomField.siType || ""}
            onChange={handleChange("siType")}
            sx={{ flex: 1 }}
          >
            <MenuItem value="Hardware">Hardware</MenuItem>
            <MenuItem value="Digitisation">Digitisation</MenuItem>
          </TextField>
          <Box sx={{ display: "flex", gap: 1, ml: "auto" }}>
            <Button
              onClick={handleSaveOrUpdate}
              sx={{ mt: 1 }}
              color="success"
              variant="contained"
            >
              Update  <ManageSearchOutlinedIcon sx={{ width: 20, ml: 1 }} />
            </Button>
            <Button
              sx={{ mt: 1, mx: 1 }}
              variant="contained"
              color="warning"
              onClick={handleClearCard1}>
              Clear <RestartAltRounded sx={{ width: 20, ml: 1 }} />
            </Button>
          </Box>
        </Box>
      </Card>
    </Grid>
  );
}