import {Box, Grid, Typography} from "@mui/material";
import CssBaseline from "@mui/material/CssBaseline";
import Toolbar from "@mui/material/Toolbar";
import React, {useEffect, useMemo} from "react";
import DrawerComp from "../../../Components/Drawer/drawer";
import MainHeader from "../../../Components/Header/MainHeader";
import CusReqDatalisting from "./Components/CusReqDatalisting";
import {
    cusReqDataListingAtom,
    cusReqFilterFormAtom, FIELDVISIT_LINK,
    invalidURLAlert,
    isARDBCusReqTabActive,
    isEmptyObject,
    overViewTabAtom,
    pageLoadingAtom,
    paramsFromURL,
    useRecoilState,
    useRecoilValue,
    useSetRecoilState,
} from "../../Heplers";
import {DataListingHeaderComp} from "./Components";
import axiosInstance from "../../../Services/AxiosInstance";

import CusReqFilterOptions from "./Components/PreparationForm/CusReqFilterOptions";
import CusReqListingPagi from "./Components/CusReqListingPagi";
import {PageLoadingElem, UnderDevAlert} from "../CustomizationRequest/Components";

// Other Compenent Using this func for datatable data refresh
export const APICallDataListing = async ({setLoading, setAtom, is_ardb}) => {

    const urlParams = paramsFromURL({linkToSplit: FIELDVISIT_LINK + "listing/"})

    if (urlParams === undefined || urlParams === null) {
        return null
    }
    const {
        paramId,
        paramId1,
        paramId2,
        paramId3,
        paramId4,
        paramId5,
        paramId6,
        paramId7,
        paramId8,
        paramId9,
        paramId10,
        paramId11
    } = urlParams

    const url = getDataListingAPIStage(paramId)

    const data = {
        is_ardb,


        limit: paramId1,
        offset: paramId2,
        searchtext: paramId3 == 'all' ? "" : paramId3, //"" is mandotory ilike where clause
        bucket: paramId4 == 'all' ? null : paramId4,//NULL is mandotory null is null or = is where clause
        state: paramId5 == 'all' ? null : paramId5,
        priority: paramId6 == 'all' ? null : paramId6,
        ageing: paramId7 == 'all' ? 999999 : paramId7,
        inputs_closed: paramId8 == 'all' ? null : paramId8,
        showstopper_audit: paramId9 == 'all' ? null : paramId9,
        showstopper_dayend: paramId10 == 'all' ? null : paramId10,
        assigned_to: paramId11 == 'all' ? null : paramId11,
    }

    // console.log({data}, paramId9, paramId10, paramId11)

    setLoading(true);

    axiosInstance({method: "post", url, data}).then(function (response) {
        setLoading(false)
        const obj = {
            records: JSON.parse(response.data.records),
            // reqData: JSON.parse(response.data.reqData),
            totalRecords: JSON.parse(response.data.totalRecords)
        }
        console.log('Datalisting', obj);
        setAtom(obj);
    })
        .catch(function (error) {
            setLoading(false)
            console.error(error);
        });
    // await new Promise((r) => setTimeout(r, 200));
};


export const getDataListingURL = (offset) => {

    const {
        paramId,
        paramId1,
        paramId2,
        paramId3,
        paramId4,
        paramId5,
        paramId6,
        paramId7,
        paramId8,
        paramId9,
        paramId10,
        paramId11
    } = paramsFromURL({linkToSplit: FIELDVISIT_LINK + "listing/"})
    // /paramID-StagesName/
    // paramId1-limit/
    // paramId2-offset/
    // paramId3-searchtext/
    // paramId4-bucket/
    // paramId5-state/
    // paramId6-priority/
    // paramId7-ageing/
    // paramId8-status/
    // paramId9-showstopper_dayend/
    // paramId10-showstopper_audit/
    // paramId11-assigned_to/
    let returnData = `/${FIELDVISIT_LINK + "listing/"}${paramId}/10/${offset}/${paramId3}/${paramId4}/${paramId5}/${paramId6}/${paramId7}/${paramId8}/${paramId9}/${paramId10}/${paramId11}/`

    return returnData
}

export const getDataListingAPIStage = (paramId) => {
    let returnData = "fetchPreparation_CusReq"

    // console.log("getDataListingAPIStage", { paramId });

    if (String(paramId).toLowerCase().indexOf('business') !== -1) {
        returnData = "fetchBRD_CusReq"
    } else if (String(paramId).toLowerCase().indexOf('development') !== -1) {
        returnData = "fetchDEV_CusReq"
    } else if (String(paramId).toLowerCase().indexOf('user') !== -1) {
        returnData = "fetchUAT_CusReq"
    }

    return returnData
}

export default function CustomizationRequestlisting() {
    const [PageLoading, setPageLoading] = useRecoilState(pageLoadingAtom);
    const [Atom, setAtom] = useRecoilState(cusReqDataListingAtom);

    const urlParams = paramsFromURL({linkToSplit: FIELDVISIT_LINK + "listing/"})


    const setFilterParamsAtom = useSetRecoilState(cusReqFilterFormAtom);

    const cusReqTabIndex = useRecoilValue(overViewTabAtom);

    useEffect(() => {
        // window.scrollTo({
        //   top: 0,
        //   left: 0,
        //   behavior: "smooth",
        // });


        // console.log('Listing', urlParams)
        if (urlParams.paramId !== undefined && urlParams.paramId != "") {
            // @ts-ignore
            if (isNaN(urlParams.paramId1) || isNaN(urlParams.paramId2)) {
                // Limit and Offset Check
                invalidURLAlert()
            } else {
                APICallDataListing({
                    setLoading: setPageLoading,
                    setAtom,
                    is_ardb: isARDBCusReqTabActive(cusReqTabIndex)
                });
            }
        }
        return () => {
            setPageLoading(false);

            // Clear filter Params Atom
            setFilterParamsAtom({});
            setAtom({});
        };
    }, []);


    const renderMainContent = () => {

        return <><Typography>Field Visit Data Listing in development</Typography></>
        return (
            <>

                <CusReqDatalisting/>

                <CusReqListingPagi/>

            </>

        );
    };

    return useMemo(() => {
        return (
            <div>
                <style>
                    {`
                  .css-10hburv-MuiTypography-root{
                    font-size:11px !important;
                    font-family: Poppins 
                  }
                  .css-yb0lig{
                    font-size:12px !important
                  }
                  `}
                </style>

                <Box sx={{display: "flex"}}>
                    <CssBaseline/>
                    {/* @ts-ignore*/}
                    <MainHeader/>
                    <DrawerComp listName={"Field Visit"}/>
                    <Box
                        component="main"
                        sx={{
                            flexGrow: 1,
                            backgroundColor: "#f4faf8",
                            px: 1,
                            // pr: 4,
                            // @ts-ignore
                            height: isEmptyObject(urlParams) ? "100vh" : "auto",
                        }}
                    >
                        <Toolbar/>

                        <UnderDevAlert />

                        <Grid
                            item
                            container
                            spacing={2}
                            xs={12}
                            sx={{
                                mt: "1.5%",
                                pl: "1.5%",
                            }}
                        >
                            <DataListingHeaderComp/>

                            <CusReqFilterOptions/>
                        </Grid>

                        <PageLoadingElem/>


                        <Grid
                            item
                            container
                            spacing={2}
                            xs={12}
                            sx={{
                                mt: "0.5%",
                                pl: "1.5%",
                                mb: 10
                            }}
                        >
                            {!PageLoading && renderMainContent()}
                        </Grid>
                    </Box>
                </Box>
            </div>
        );
    }, [PageLoading]);
}
