import {Grid, Paper, Typography} from "@mui/material";
import {
    cusReqMasterDataAtom, cusReqShowstopperListAtom,
    cusReqStateListAtom,
    ErrorLabelAtom,
    isEmptyObject,
    isObjectCus,
    renderInputErrorLabel,
    SubmitErrorAlertAtom,
    useRecoilState, yesNoArr
} from "../../../../Heplers";
import React, {useMemo} from "react";
import {CusReqDropdown, RadioYesNo} from "..";
import {CardGreenHeader} from "../../../CustomizationRequest/Components/CardGreenHeader";

export const InstitutionalEngagement = ({readOnly}) => {

    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);


    return useMemo(() => {
        return (
            <Paper elevation={2} sx={{mb: 2}} className={"greenBorder"}>
                <CardGreenHeader text={"Institutional Engagement"}/>

                <Grid p={2} spacing={2} container>

                    <Grid item xs={12} md={6}>
                        <RadioYesNo radioName={"InstEng1"} ddLabel={"Did any CSPCP official ever visit the PACS in this computerization context (AR/DR/DDM/DCCB/DEO/DCO etc)"} />
                    </Grid>
                    <Grid item xs={12} md={6}>
                        <RadioYesNo radioName={"InstEng2"} ddLabel={"If not, Did PACS try to reach out to DCCB or any other government official/CSPCP personnel including SI regarding issue in computerization"} />
                    </Grid>

                </Grid>
            </Paper>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
