import {Grid, Paper, Typography} from "@mui/material";
import {
    cusReqMasterDataAtom, cusReqShowstopperListAtom,
    cusReqStateListAtom,
    ErrorLabelAtom,
    isEmptyObject,
    isObjectCus,
    renderInputErrorLabel,
    SubmitErrorAlertAtom,
    useRecoilState, yesNoArr
} from "../../../../Heplers";
import React, {useMemo} from "react";
import {CusReqDropdown, RadioYesNo} from "..";
import {CardGreenHeader} from "../../../CustomizationRequest/Components/CardGreenHeader";

export const Support_System = ({readOnly}) => {

    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);


    return useMemo(() => {
        return (
            <Paper elevation={2} sx={{mb: 2}} className={"greenBorder"}>
                <CardGreenHeader text={"Support System"}/>

                <Grid p={2} spacing={2} container>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sup_sys1"} ddLabel={"Does he get peer support for his doubts/issues"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sup_sys2"} ddLabel={"Does PACS person who faces issue have access to SI ticketing tool"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sup_sys3"} ddLabel={"Does PACS person who faces issue have access to SI call center"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sup_sys4"} ddLabel={"Does PACS person know how to raise ticket in tool or call"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sup_sys5"} ddLabel={"Did he raise any ticket so far"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sup_sys6"} ddLabel={"How long did it take for the ticket to resolve"} />
                    </Grid>

                </Grid>
            </Paper>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
