import Timeline from "@mui/lab/Timeline";
import TimelineConnector from "@mui/lab/TimelineConnector";
import TimelineContent from "@mui/lab/TimelineContent";
import TimelineDot from "@mui/lab/TimelineDot";
import TimelineItem from "@mui/lab/TimelineItem";
import TimelineOppositeContent from "@mui/lab/TimelineOppositeContent";
import TimelineSeparator from "@mui/lab/TimelineSeparator";
import {
    Card,
    CardActionArea,
    CircularProgress,
    Divider,
    Grid,
    Paper,
    Typography,
} from "@mui/material";
import React, {useEffect, useMemo, useState} from "react";
import {
    CUIData, cusReqCUIMasterDetailsAtom,
    genUUID, isARDBCusReqTabActive, overViewTabAtom,
    paramsFromURL,
    URLParamsAtom,
    useRecoilState, useRecoilValue,
} from "../../../../Heplers";
import {NoteAlt, RadioButtonChecked} from "@mui/icons-material";
import axiosInstance from "../../../../../Services/AxiosInstance";
import moment from "moment";

export function TimelineComp({data}) {
    const [URLParams, setURLParams] = useRecoilState(URLParamsAtom);
    const cuiMasterAtom = useRecoilValue(cusReqCUIMasterDetailsAtom);
    const [TimelineData, setTimelineData] = useState([]);

    const APICall = async (reqData) => {
        axiosInstance({
            method: "post",
            url: "dataForTimeline",
            data: reqData,
        })
            .then(function (response) {
                console.log("dataForTimeline =>", response.data.data);
                setTimelineData(response.data.data);
            })
            .catch(function (error) {
                console.error(error);
            });
    };

    useEffect(() => {
        APICall({cui: URLParams.paramId});
        return () => {
        };
    }, []);

    const renderClosed = (d, middleData) => {
        // console.log("renderClosed", d, cuiMasterAtom);

        const isAllFourStageClosed = (
            cuiMasterAtom.pre.inputs_closed === 'Yes' &&
            (cuiMasterAtom.brd !== undefined && cuiMasterAtom.brd !== null && cuiMasterAtom.brd.inputs_closed !== undefined && cuiMasterAtom.brd.inputs_closed === 'Yes') &&
            (cuiMasterAtom.dev !== null && JSON.parse(cuiMasterAtom.dev.dev_reviews_ongoing).inputs_closed === 'Yes') &&
            (cuiMasterAtom.uat !== null && JSON.parse(cuiMasterAtom.uat.uat_feedback_on_going).inputs_closed === 'Yes')
        )

        const isRequestClosed = (
            Array.isArray(d) && d.length > 0 &&
            d[0].date !== undefined && isAllFourStageClosed
        );

        return (
            <TimelineItem key={genUUID()}>
                <TimelineOppositeContent
                    sx={{mt: 2}}
                    variant="body2"
                    color="text.primary"
                >
                    {isRequestClosed && moment(d[0].date, "YYYY-MM-DD").format("DD-MMM-YY")}
                </TimelineOppositeContent>
                <TimelineSeparator>
                    <TimelineDot
                        color={
                            isRequestClosed
                                ? "error"
                                : "success"
                        }
                    >
                        <RadioButtonChecked/>
                    </TimelineDot>
                    <TimelineConnector/>
                </TimelineSeparator>
                <TimelineContent key={genUUID()} sx={{py: "12px", px: 2}}>
                    <Typography sx={{fontWeight: 700, fontSize: 14}} component="span">
                        CUI: {URLParams.paramId}
                    </Typography>
                    <Typography sx={{fontWeight: 400, fontSize: 12}}>
                        {isRequestClosed
                            ? "Request Closed"
                            : "Open Request"}
                    </Typography>
                </TimelineContent>
            </TimelineItem>
        );
    };

    const renderOpen = (d, middleData) => {

        return !(Array.isArray(d) && d.length > 0) ? null : d.map((v, i) => {

            const filteredArr = v.datas.filter(
                (item) => item.field === "FIRST_ENTRY"
            );

            // console.log("renderOpen", d,filteredArr);

            return filteredArr.length === 0 ? null : (
                <TimelineItem key={genUUID()}>
                    <TimelineOppositeContent
                        sx={{
                            mt: 1,
                            display: "flex",
                            alignItems: "center",
                            // justifyContent: middleData.length % 2 ? "end" : "start" ,
                            justifyContent: middleData.length % 2 ? "start" : "end",
                        }}
                        variant="body2"
                        color="text.primary"
                    >
                        {d[i].date !== undefined &&
                            moment(d[i].date, "YYYY-MM-DD").format("DD-MMM-YY")}
                    </TimelineOppositeContent>
                    <TimelineSeparator>
                        <TimelineConnector/>
                        <TimelineDot color="primary">
                            <NoteAlt/>
                        </TimelineDot>
                    </TimelineSeparator>
                    <TimelineContent sx={{py: "12px", px: 2}}>
                        <Typography sx={{fontWeight: 700, fontSize: 14}} component="span">
                            CUI: {URLParams.paramId}
                        </Typography>
                        <Typography sx={{fontWeight: 400, fontSize: 12}}>
                            Request Entered By:{" "}
                            {d[i].datas !== undefined && filteredArr[0].created_by}
                        </Typography>
                    </TimelineContent>
                </TimelineItem>
            )

        })
    };

    const checkIfItStakeholderFeedback = (d) => {
        if (
            String(d.field).indexOf("PACS") !== -1 ||
            String(d.field).indexOf("SI") !== -1 ||
            String(d.field).indexOf("State") !== -1 ||
            String(d.field).indexOf("SPMU") !== -1 ||
            String(d.field).indexOf("RO") !== -1 ||
            String(d.field).indexOf("SLIMC") !== -1 ||
            String(d.field).indexOf("CPMU") !== -1 ||
            String(d.field).indexOf("NLPSV") !== -1 ||
            String(d.field).indexOf("HO") !== -1 ||
            String(d.field).indexOf("SCARDB") !== -1 ||
            String(d.field).indexOf("PCARDB") !== -1
        ) {
            return (
                <>
                    Status Updated: <b>{d.status}</b>
                </>
            );
        }

        return d.status;
    };

    const renderMiddle = (d) => {

        // console.log("renderMiddle", d);
        return !(Array.isArray(d) && d.length > 0)
            ? null
            : d.map((v, i) => {

                // Sorting if multiple remarks made in a single day by stakeholders
                const sortedArr = v.datas.sort(function (a, b) {
                    // Turn your strings into dates, and then subtract them
                    // to get a value that is either negative, positive, or zero.
                    return new Date(b.created_at) - new Date(a.created_at);
                });


                // Cleaning Duplicate Entries base on values... not created_at
                let sortedFilteredArr = sortedArr.filter((value, index) => {

                    // return true;

                    const _value = JSON.stringify({
                        created_by: value.created_by,
                        field: value.field,
                        inputs: value.inputs,
                        stage: value.stage,
                        status: value.status
                    });
                    return index === sortedArr.findIndex(obj => {
                        return JSON.stringify({
                            created_by: obj.created_by,
                            field: obj.field,
                            inputs: obj.inputs,
                            stage: obj.stage,
                            status: obj.status
                        }) === _value;
                    });
                });

                // Cleaning First_Entry if feedbacks recorded on first day
                sortedFilteredArr = sortedFilteredArr.filter(
                    (item) =>
                        // true
                        item.field !== "FIRST_ENTRY"
                );
                // console.log("renderMiddle, sortedFilteredArr", sortedFilteredArr)


                // Moving closed entry to top
                let firstEntry = "CLOSED_ENTRY";
                sortedFilteredArr = sortedFilteredArr.sort(function (x, y) {
                    return x.field == firstEntry ? -1 : y.field == firstEntry ? 1 : 0;
                });

                // However if REOPEN is there in Same Date then move PUSH_BACK_REOPEN entry to top
                firstEntry = "PUSH_BACK_REOPEN";
                sortedFilteredArr = sortedFilteredArr.sort(function (x, y) {
                    return x.field == firstEntry ? -1 : y.field == firstEntry ? 1 : 0;
                });

                const checkCommonStakeholder = (field) => {
                    console.log(cuiMasterAtom.pre, field)
                    if (cuiMasterAtom.pre.ardb_pacs === "Yes") {
                        // Renaming ARDB stakeholders
                        switch (field) {
                            case "PACS Inputs":
                               return "SCARDB SU Inputs"
                            case "StCB Inputs":
                                return "SCARDB HO Inputs"
                            case "NLPSV Inputs":
                                return "NUSV Inputs"
                            default:
                                return field
                        }
                    }
                    return field
                }

                return (
                    <TimelineItem key={genUUID()}>
                        <TimelineOppositeContent variant="body2" color="text.primary">
                            {moment(v.date, "YYYY-MM-DD").format("DD-MMM-YY")}
                        </TimelineOppositeContent>
                        <TimelineSeparator>
                            <TimelineDot/>
                            <TimelineConnector/>
                        </TimelineSeparator>
                        <TimelineContent>
                            <Paper elevation={1} sx={{p: 1, mb: 4}}>
                                {sortedFilteredArr.map((vv, ii) => {
                                    return (
                                        <span key={genUUID()}>
                                            <Grid container display={"flex"} direction={"row"}
                                                  justifyContent="space-between">
                                                <Typography sx={{fontWeight: "bold", fontSize: 14}}>
                                                    {checkCommonStakeholder(vv.field)}
                                                </Typography>
                                                <Typography
                                                    variant="body2"
                                                    sx={{
                                                        color: "text.secondary", fontSize: "0.5em", opacity: 0.7,
                                                        borderTop: `2px solid ${vv.stage == 'PREP' ? 'green' : vv.stage == 'BRF' ? 'orange' : vv.stage == 'DEV' ? 'yellow' : 'black'}`
                                                    }}
                                                >
                                                    {vv.stage}
                                                </Typography>
                                            </Grid>

                                            <Typography sx={{fontWeight: 400, fontSize: 12}}>
                                                {vv.inputs}
                                            </Typography>

                                            {vv.status !== null && (
                                                <>
                                                    <Typography
                                                        sx={{fontWeight: 400, fontSize: 12, mt: 1}}
                                                    >
                                                        {checkIfItStakeholderFeedback(vv)}
                                                    </Typography>
                                                </>
                                            )}

                                            <Divider
                                                sx={{
                                                    justifySelf: i % 2 === 0 ? "left" : "right",
                                                    width: "10%",
                                                    my: 1,
                                                }}
                                            />
                                            <Typography sx={{fontWeight: 400, fontSize: 10}}>
                                                Updated By:
                                                <span style={{fontWeight: "bold"}}>
                                                    {vv.created_by}
                          </span>
                                            </Typography>
                                            {sortedFilteredArr.length > ii + 1 && <Divider sx={{my: 1}}/>}
                                        </span>
                                    );
                                })}
                            </Paper>
                        </TimelineContent>
                    </TimelineItem>
                );
            });
    };

    return useMemo(() => {
        const grouped = TimelineData.reduce((acc, {date, ...data}) => {
            const existingGroup = acc.find((group) => group.date === date);
            if (existingGroup) existingGroup.datas.push(data);
            else
                acc.push({
                    date,
                    datas: [data],
                });
            return acc;
        }, []);

        console.log({grouped});

        // First
        const openData = grouped.filter((item) => {
            // return (item.datas[0].field === "FIRST_ENTRY")
            const nestedCheck = item.datas.filter((v) => v.field === "FIRST_ENTRY");
            // console.log({nestedCheck});

            return nestedCheck.length > 0;
        });

        // console.log({grouped});

        // Removing FIRST_ENTRY OR CLOSED OR LAST
        const middleData = grouped.filter((item) => {

            const nestedCheck = item.datas.filter((v) => v.field !== "FIRST_ENTRY" && v.field !== "CLOSED_ENTRY");
            // console.log({nestedCheck});

            return nestedCheck.length > 0;
        });

        // closed
        const closedData = grouped.filter((item) => {
            const nestedCheck = item.datas.filter((v) => v.field === "CLOSED_ENTRY");
            // console.log({nestedCheck});

            return nestedCheck.length > 0;
        });

        // console.log(grouped, closedData);

        return TimelineData.length === 0 ? <Grid display={'flex'} justifyContent={"center"}>
            <p style={{marginTop: 25, textAlign: "center"}}>Please Wait Loading Request Timeline... <CircularProgress
                size={16} color="success"/></p>
        </Grid> : (
            <Timeline key={genUUID()} position="alternate-reverse">
                {renderClosed(closedData, middleData)}

                {renderMiddle(middleData)}

                {renderOpen(openData, middleData)}
            </Timeline>
        );
    }, [URLParams, TimelineData]);
}
