import React from 'react';
import { useRecoilValue, useRecoilState } from 'recoil';
import { siTableDataAtom, siStateListAtom, genUUID } from '../../RAS_updates/Heplers';
import { Card, Divider, Chip } from '@mui/material';
import { Link } from 'react-router-dom';
import moment from 'moment';
import './SiTable.css';

export const SITable = ({ page = 0, size = 10 }) => {
  const tableData = useRecoilValue(siTableDataAtom);
  const [stateList] = useRecoilState(siStateListAtom);

  if (!Array.isArray(tableData) || tableData.length === 0) {
    return <p>No data submitted yet.</p>;
  }

  const getStateLabel = (stateId) => {
    const stateObj = stateList.find((s) => s.id === stateId);
    return stateObj
      ? `${stateObj.name} (${stateObj.short_name} - ${stateObj.code})`
      : '—';
  };

  const getStatusChip = (status) => {
    if (status === 'PAID') {
      return (
        <Chip
          label="PAID"
          size="small"
          className="greenBackground"
          sx={{
            borderRadius: '12px',
            fontWeight: 600,
            fontSize: '0.70rem',
            alignItems: 'center',
          }}
        />
      );
    }
    if (status === 'UNPAID') {
      return (
        <Chip
          label="UNPAID"
          size="small"
          className="redBackground"
          sx={{
            borderRadius: '12px',
            fontWeight: 600,
            fontSize: '0.70rem',
            alignItems: 'center',
          }}
        />
      );
    }
    return status ?? '—';
  };

  return (
    <div style={{ width: '100%' }}>
      <Card className="cusTable" sx={{mt:2}} >

        {/* Desktop Table */}
        <table className="desktopTable">
          <thead>
            <tr>
              <th>Sno.</th>
              <th style={{ minWidth: 160, width: '18%' }}>Invoice Number</th>
              <th>Inv. Date</th>
              <th style={{ minWidth: 80, width: '8%' }}>Inv. Amt (Cr)</th>
              <th style={{ minWidth: 80, width: '8%' }}>Disbursed Amt (Cr)</th>
              <th>State/UT</th>
              <th>SI Name</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {tableData.map((row, idx) => (
              <tr key={genUUID()}>
                <td>{page * size + idx + 1}</td>
                <td style={{ minWidth: 160, width: '18%' }}>
                  <Link
                    to={`/sipayments/update/${row.id}`}
                    className="dataListingCUI"
                  >
                    {row.invoiceNumber}
                  </Link>
                </td>
                <td>{row.billRaisedDate ? moment(row.billRaisedDate).format('MM/DD/YYYY') : '—'}</td>
                <td style={{ minWidth: 80, width: '10%', textAlign: 'right' }}>{row.invoiceAmount ?? '—'}</td>
                <td style={{ textAlign: 'right' }}>{row.paymentDisbursedAmt ?? '_'}</td>
                <td>{getStateLabel(row.stateUt)}</td>
                <td>{row.siname || '—'}</td>
                <td>{getStatusChip(row.status)}</td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Mobile stacked rows */}
        <div className="mobileTable">
          {tableData.map((row, idx) => (
            <div key={genUUID()} className="responsiveTableRow">
              <div className="rowItem">
                <span>Sno.</span>
                <span>{page * size + idx + 1}</span>
              </div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem">
                <span>Invoice Number</span>
                <span>
                  <Link
                    to={`/sipayments/update/${row.id}`}
                    className="dataListingCUI"
                  >
                    {row.invoiceNumber}
                  </Link>
                </span>
              </div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem">
                <span>Invoice Amount</span>
                <span>{row.invoiceAmount ?? '—'}</span>
              </div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem">
                <span>Invoice Date</span>
                <span>{row.billRaisedDate ? moment(row.billRaisedDate).format('MM/DD/YYYY') : '—'}</span>
              </div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem">
                <span>Payment Disbursed</span>
                <span>{row.paymentDisbursedAmt ?? '—'}</span>
              </div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem">
                <span>State/UT</span>
                <span>{getStateLabel(row.stateUt)}</span>
              </div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem">
                <span>SI Name/ SI type</span>
                <span>{getStateLabel(row.siname)}</span>
              </div>

              <Divider className="mobileRowDivider" />
              <div className="rowItem">
                <span>Status</span>
                <span >{getStatusChip(row.status)}</span>
              </div>
              <Divider className="mobileRowDivider" />
            </div>
          ))}
        </div>

      </Card>
    </div>
  );
};
