import {
    Button, Chip,
    Divider,
    Grid,
} from "@mui/material";
import React, { useMemo } from "react";
import {
    cusReqCUIMasterDetailsAtom, displayDownloadableFilesLinks,
    genUUID,
    useRecoilValue,
} from "../../../../Heplers";
import moment from "moment";
import { CardStagesHeader, createrArrOfInputs, inputsRender, pendingInputsRender, renderApprovedYesChips, systemCreationRender } from "./CusReqDetailsCard_Pre";
import { Link, useNavigate } from "react-router-dom";
import {chipSX} from "../CusReqDatalisting";


export function CusReqDetailsCard_UAT() {
    const Atom = useRecoilValue(cusReqCUIMasterDetailsAtom);

    const navigate = useNavigate();
    return useMemo(() => {
        const { uat, pre } = Atom;


        if (uat === null) {

            return <> {CardStagesHeader("User Acceptance Testing")}
                            <b>Not Started:</b>
                            
            
            {/* <Grid item>

                    <Link to={`/${CUSTOMIZATIONREQUEST_LINK}uat/${pre.cui}`}>
                        <Button sx={{ minWidth: "unset", borderRadius: 10, fontSize: 10, p: "0.2px 15px" }} size="small" variant="outlined" color="primary" disableElevation >Add User Acceptance Testing Details</Button>
                    </Link>

                </Grid> */}
                
                </>
        }


        const uat_feedback_on_going = uat.uat_feedback_on_going !== null ? JSON.parse(`[${uat.uat_feedback_on_going}]`) : []
        // console.log({ uat });

        const arr = (uat.brd_file !== undefined && uat.brd_file !== null && uat.brd_file.length > 0) ? uat.brd_file.split(',') : [];
        console.log(uat, arr)

        return (
            <span key={genUUID()}>

                {CardStagesHeader("User Acceptance")}

                <b>Started On:</b> {moment(uat.start_date, "YYYY-MM-DD").format("DD-MMM-YY")}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Status :</b> <br />
                {
                    uat_feedback_on_going[0].inputs_closed === 'Yes' ? <Chip size="small"  className="inputRecChip" label="Closed" color="success" sx={chipSX}/> : <Chip size="small" className="inputRecChip"  label="Pending" color="error" sx={{...chipSX, backgroundColor: "#B71C1C"}}/>
                }
                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Assigned To:</b><br /> {uat.assigned_to}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Compliance on BRD Points:</b> <br /> {uat.accepted_brd_points}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Ageing:</b> <br /> {uat.ageing}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>SI Acceptance:</b> <br /> {renderApprovedYesChips(uat.acceptance_si)}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>State Acceptance:</b> <br /> {renderApprovedYesChips(uat.acceptance_state)}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>RO Acceptance:</b> <br /> {renderApprovedYesChips(uat.acceptance_ro)}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Planned Go-Live Date:</b> <br /> {uat.go_live_date !== null && moment(uat.go_live_date, "YYYY-MM-DD").format("DD-MMM-YY")}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Actual Go-Live Date:</b> <br /> {uat.go_live_date !== null && moment(uat.actual_go_live_date, "YYYY-MM-DD").format("DD-MMM-YY")}

                {uat_feedback_on_going.map((v, i) => {
                    const pendingInputs = [];
                    const stakeholderInputs = [];

                    createrArrOfInputs(v, 'si', pendingInputs, stakeholderInputs);
                    createrArrOfInputs(v, 'state', pendingInputs, stakeholderInputs);
                    createrArrOfInputs(v, 'stcb', pendingInputs, stakeholderInputs);
                    createrArrOfInputs(v, 'ro', pendingInputs, stakeholderInputs);
                    createrArrOfInputs(v, 'nlpsv', pendingInputs, stakeholderInputs);

                    if(pre.ardb_pacs ===  "Yes"){
                        //     Only ARDB Stakeholder
                        createrArrOfInputs(pre, 'scardb_branch', pendingInputs, stakeholderInputs);
                        createrArrOfInputs(pre, 'pcardb_ho', pendingInputs, stakeholderInputs);
                        createrArrOfInputs(pre, 'pcardb_branch', pendingInputs, stakeholderInputs);

                        // Renaming replaced stakeholders
                        pendingInputs.forEach(function(value, index, theArray) {
                            switch (value.toUpperCase()){
                                case "PACS":
                                    theArray[index] = "SCARDB_SU";
                                    break;
                                case "STCB":
                                    theArray[index] = "SCARDB_HO";
                                    break;
                                case "NLPSV":
                                    theArray[index] = "NUSV";
                                    break;
                                default:
                                    break;
                            }
                        });

                        stakeholderInputs.forEach(function(value, index, theArray) {
                            switch (value.name.toUpperCase()){
                                case "PACS":
                                    theArray[index].name = "SCARDB_SU";
                                    break;
                                case "STCB":
                                    theArray[index].name = "SCARDB_HO";
                                    break;
                                case "NLPSV":
                                    theArray[index].name = "NUSV";
                                    break;
                                default:
                                    break;
                            }
                        });
                    }

                    // console.log({ pendingInputs, stakeholderInputs })
                    return <span key={genUUID()}>
                        <Divider sx={{ my: 1, width: "25%" }} />
                        {/*<b>{i + 1}: NLPSV Demo On:</b><br /> */}
                        <b>NLPSV Demo On:</b><br />
                        {moment(v.dod, "YYYY-MM-DD").format("DD-MMM-YY")}

                        {pendingInputsRender(pendingInputs, `Stakeholder Pending Inputs`, 0)}
                        {inputsRender(stakeholderInputs, `Stakeholder Inputs`, 0, "Personel")}
                    </span>
                })}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Uploaded Documents:</b> <br /> {displayDownloadableFilesLinks(arr)}

                {systemCreationRender(uat)}



            </span>
        );
    }, [])
}
