import React, { useState, useEffect } from "react";
import { Card, Grid, TextField, Button, Typography, Box } from "@mui/material";
import { useRecoilState, useSetRecoilState } from "recoil";
import {
  siTotalSancMasterAtom,
  siStateListAtom,
  siGlobalModeAtom,
  globalSiIdAtom,
  siTotalSancMasterTableAtom,
  siWOMasterTableAtom,
  siWOMasterAtom
} from "../../RAS_updates/Heplers";
import { useSuccessAndResetAlert, renderSubmitErrorAlert } from "../../RAS_updates/Heplers";
import { getCookie } from "../../Services/Cookies";
import axiosInstance from "../../Services/AxiosInstance";
import { SiTotalSancMasterTable } from "./SiTotalSancMasterTable";
import { CusReqDropdownSIPayment } from "../../Shobha_updates/SIPayments/CusReqDropdownSIPayment";
import { RestartAltRounded } from "@mui/icons-material";
import ManageSearchOutlinedIcon from "@mui/icons-material/ManageSearchOutlined";
import AutorenewIcon from '@mui/icons-material/Autorenew';
import SaveIcon from "@mui/icons-material/Save";
export default function SiTotalSancMasterForm() {
  const [form, setForm] = useRecoilState(siTotalSancMasterAtom);
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useRecoilState(siGlobalModeAtom);
  const [globalSiId, setGlobalSiId] = useRecoilState(globalSiIdAtom);
  const successAlertAndReset = useSuccessAndResetAlert(siTotalSancMasterAtom);
  const setTotalSancList = useSetRecoilState(siTotalSancMasterTableAtom);
  const setWOList = useSetRecoilState(siWOMasterTableAtom);
  const [SiTotalSancMaster, setSiTotalSancMaster] = useRecoilState(siTotalSancMasterAtom);
  const [siWoMaster, setSiWOMaster] = useRecoilState(siWOMasterAtom);
  // Clear form
  const handleClear = () => {
    setForm({
      siName: "",
      createdBy: 0,
      stateUt: null,
      id: 0,
      totalSancPACS: 0,
      siMasterId: 0,
      date: null
    });
    setMode("create");
  };

  // useEffect(() => {
  //   if (form.siMasterId) {
  //     setMode("edit");
  //   } else {
  //     setMode("create");
  //   }
  // }, [form.siMasterId, setMode]);

  // Handle field change
  const handleChange = (field) => (e) => {
    setForm((prev) => ({
      ...prev,
      [field]: e.target.value
    }));
  };

  // Save or Update
  const handleSaveOrUpdate = async (mode) => {
    const user_id = getCookie("resourceId");
    if (
      !form.stateUt ||
      !form.totalSancPACS 
    ) {
      renderSubmitErrorAlert("State and TotalSancPACS are required");
      return;
    }
    setLoading(true);
    try {
      const payload = {
        createdBy: user_id,
        stateUt: form.stateUt.id,
        totalSancPACS: form.totalSancPACS,
        id: form.id,
        date: form.date,
        siMasterId: globalSiId
      };
      const url = form.id ? "/siTotalSancMaster/update" : "/siTotalSancMaster/create";
      const res = await axiosInstance.post(url, payload);
      if (res.status === 200 && res.data.message) {
        successAlertAndReset(res.data.message);
      } else {
        renderSubmitErrorAlert(res.data.error || "Couldn't Update successfully");
      }


      try {
        const res = await axiosInstance.post(`/siMaster/SiSubClasses`, {}, // Empty body
          { params: { siId: globalSiId } });

        if (res.status === 200 && res.data?.siMaster) {
          // Set SI Card Atom
          setForm({
            siId: globalSiId,
            ...res.data.siMaster,
          });

          // Set Total Sanc List Atom
          // Set Total Sanc Master Atom with the first object
          if (res.data.siTotalSancList && res.data.siTotalSancList.length > 0) {
            // setSiTotalSancMaster(res.data.siTotalSancList[0]); // First object
            setTotalSancList(res.data.siTotalSancList); // Full array for table
          }

          // Set SI WO Master Atom with the first object
          if (res.data.siWOList && res.data.siWOList.length > 0) {
            // setSiWOMaster(res.data.siWOList[0]); // First object
            setWOList(res.data.siWOList); // Full array for table
          }

        } else {
          renderSubmitErrorAlert(res.data?.error || "Operation failed");
        }

      } catch (err) {
        console.error("Fetch error:", err);
        renderSubmitErrorAlert("Something went wrong");
      }

    } catch (err) {
      renderSubmitErrorAlert("Couldn't Update successfully");
    }
    setLoading(false);
  };

  return (
    <Grid item xs={12} sx={{ p:2}}>
      <Card sx={{ p: 3, width: "100%", mb: 2 }}>
        <Typography variant="h6" sx={{ mb: 2 }}>SI Total Sanctioned PACs</Typography>
        <Grid container spacing={2} sx={{ mb: 2 }}>
          <Grid item sm={12} md={4}>
            <CusReqDropdownSIPayment
              // @ts-ignore
              formDataAtom={siTotalSancMasterAtom}
              // @ts-ignore
              listDataAtom={siStateListAtom}
              ddLabel="State/ UT"
              dropdownName="stateUt"
              fetchMasterDataURL="fetchStateMasterData_CusReq"
              // @ts-ignore
              optionLabel={["StateNameAndCode", "name", "short_name", "code"]}
              defVal={form.stateUt}
              mode={mode}
              value={form.stateUt || ""}
              onChange={handleChange("stateUt")}
              required
            />
          </Grid>

          <Grid item sm={12} md={4}>
            <TextField
              label="Total Sanctioned PACs"
              type="number"
              value={form.totalSancPACS || ""}
              onChange={handleChange("totalSancPACS")}
              fullWidth
              required
            />
          </Grid>

          <Grid item sm={12} md={4}>
            <TextField
              fullWidth
              label="Date"
              type="date"
              value={form.date || ''}
              onChange={handleChange("date")}
              InputLabelProps={{ shrink: true }}
            />
          </Grid>
        </Grid>

        <Box sx={{ display: "flex", justifyContent: "flex-end", gap: 1 }}>
          <Button
            variant="contained"
            onClick={handleSaveOrUpdate}
            sx={{ mt: 1 }}
            color="success"
          >
            {form.id ? "Update" : "Save"}
            {form.id ? <AutorenewIcon sx={{ width: 20, ml: 1 }} /> : <SaveIcon sx={{ width: 20, ml: 1 }} />}
          </Button>
          <Button
            sx={{ mt: 1, mx: 1 }}
            variant="contained"
            color="warning"
            onClick={handleClear}
            disabled={loading}
          >
            Clear <RestartAltRounded sx={{ width: 20, ml: 1 }} />
          </Button>
        </Box>
      </Card>
      <SiTotalSancMasterTable />
    </Grid>
  );
}