import React, { useState } from "react";
import { useRecoilState, useSetRecoilState } from "recoil";
import {
  siFundTotalSancTableAtom,
  siFundTotalSancAtom
} from "../../RAS_updates/Heplers";
import { Card, Divider, Box } from "@mui/material";
import moment from "moment";
import "../SIPayments/SiTable.css";

const genUUID = () => Math.random().toString(36).substring(2, 10);

export const SiFundTransSancPACSTable = ({ page = 0, size = 10 }) => {
  const [tableData] = useRecoilState(siFundTotalSancTableAtom);
  const setSelectedRow = useSetRecoilState(siFundTotalSancAtom);
  const [isIdColumnVisible, setIsIdColumnVisible] = useState(false);

  const handleRowClick = (row) => {
     setSelectedRow({
    ...row,
    siName: row.siMasterdto
  });
  };

  if (!Array.isArray(tableData) || tableData.length === 0) {
    return <p style={{ padding: "20px" }}>No sanctioned PAC data available.</p>;
  }

  return (
     <Box sx={{ width: '100%', px: 2 }}>
    <Card className="cusTable" sx={{  overflowX: "auto" }}>
      <div style={{ minWidth: "700px" }}>
        <table className="desktopTable">
          <thead>
            <tr>
              <th>Sno.</th>
              <th>SI Name</th>
              <th>Total Sanctioned PACs</th>
              <th>Date</th>
              {isIdColumnVisible && <th>ID</th>}
            </tr>
          </thead>
          <tbody>
            {tableData.slice(page * size, page * size + size).map((row, idx) => (
              <tr key={genUUID()}>
                <td>{page * size + idx + 1}</td>
                <td>
                  <span
                    style={{
                      color: "#1976d2",
                      cursor: "pointer",
                      textDecoration: "underline"
                    }}
                    onClick={() => handleRowClick(row)}
                  >
                    {row.siMasterdto.name || "—"}
                  </span>
                </td>
                <td>{row.totalSancPACS ?? "—"}</td>
                <td>{row.date ? moment(row.date).format("MM/DD/YYYY") : "—"}</td>
                {isIdColumnVisible && <td>{row.id}</td>}
              </tr>
            ))}
          </tbody>
        </table>

        {/* Mobile stacked layout */}
        <div className="mobileTable">
          {tableData.slice(page * size, page * size + size).map((row, idx) => (
            <div
              key={genUUID()}
              className="responsiveTableRow"
              onClick={() => handleRowClick(row)}
            >
              <div className="rowItem">
                <span>Sno.</span>
                <span>{page * size + idx + 1}</span>
              </div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem">
                <span>SI Name</span>
                <span style={{ color: "#1976d2", textDecoration: "underline" }}>
                  {row.siMasterdto.name || "—"}
                </span>
              </div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem">
                <span>Total Sanctioned PACs</span>
                <span>{row.totalSancPACS ?? "—"}</span>
              </div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem">
                <span>Date</span>
                <span>{row.date ? moment(row.date).format("MM/DD/YYYY") : "—"}</span>
              </div>
              {isIdColumnVisible && (
                <>
                  <Divider className="mobileRowDivider" />
                  <div className="rowItem">
                    <span>ID</span>
                    <span>{row.id}</span>
                  </div>
                </>
              )}
            </div>
          ))}
        </div>
      </div>
    </Card>
    </Box>
  );
};
