export const capitalizeAllFirstLetter = (mySentence) => {
    return String(mySentence)
        .toLowerCase()
        .replace(/%20/g, " ")
        .split(" ")
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
        .join(" ");
};
export const capitalizeFirstLetter = (string) => {
    string = String(string).toLowerCase();
    return string.charAt(0).toUpperCase() + string.slice(1);
};

export const leadingZeroPad = (num, size = 6) => {
    num = num.toString();
    while (num.length < size) num = "0" + num;
    return num;
};

//Date
export const padTo2Digits = (num) => num.toString().padStart(2, "0");
export const formatDate = (date, type = "") => {
    try {
        if (String(date).length < 10) {
            return date;
        }

        if (type === "yyyymmdd2ddmmyyyy") {
            const datePart = date.match(/\d+/g),
                year = datePart[0],
                month = datePart[1],
                day = datePart[2];

            return day + "-" + month + "-" + year;
        }

        if (type === "yyyy") {
            const datePart = date.match(/\d+/g),
                year = datePart[0];
            return year;
        }

        if (type === "db-yyyy-mm-dd") {
            const extDate = new Date(date);

            // Extract day, month, and year
            let day = extDate.getDate();
            let month = extDate.getMonth() + 1;
            let year = extDate.getFullYear();

            // Add leading zero to day and month if needed
            // @ts-ignore
            day = day < 10 ? "0" + day : day;
            // @ts-ignore
            month = month < 10 ? "0" + month : month;

            const returnDate = `${year}-${month}-${day}`;
            // console.log({ returnDate });

            // Format the date as dd/mm/yyyy
            return returnDate;
        }

        return [
            date.getFullYear(),
            padTo2Digits(date.getMonth() + 1),
            padTo2Digits(date.getDate()),
        ].join("-");
    } catch (err) {
        return err;
    }
};

export const genUUID = () => {
    let d = new Date().getTime(),
        d2 = (performance && performance.now && performance.now() * 1000) || 0;
    return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
        let r = Math.random() * 16;
        if (d > 0) {
            r = (d + r) % 16 | 0;
            d = Math.floor(d / 16);
        } else {
            r = (d2 + r) % 16 | 0;
            d2 = Math.floor(d2 / 16);
        }
        return (c == "x" ? r : (r & 0x7) | 0x8).toString(16);
    });
};

export const isObjectCus = (A) => {
    if ((typeof A === "object" || typeof A === "function") && A !== null) {
        return true;
    }
};

export const isEmptyObject = (v) => {
    return Object.keys(v).length === 0 && v.constructor === Object;
};

export const paramsFromURL = ({
                                  linkToSplit = "/customizationrequestlisting/",
                                  limitOffsetFromUrl = true,
                              }) => {
    let paramsArr = window.location.href.split(linkToSplit);

    // console.log(paramsArr, window.location);
    if (paramsArr.length < 2) {
        return null;
    }


    paramsArr = paramsArr[1].split("/");
    return {
        // paramId means limit should be 10 as filter options is change
        paramId: limitOffsetFromUrl ? paramsArr[0] : 10, //paramsArr[0]
        // paramId means offset should be 0 as filter options is change
        paramId1: limitOffsetFromUrl ? paramsArr[1] : 0, //paramsArr[1]

        paramId2: paramsArr[2] === undefined ? " " : paramsArr[2],

        //THese all are dropped down
        paramId3: paramsArr[3] === undefined ? "all" : paramsArr[3],
        paramId4: paramsArr[4] === undefined ? "all" : paramsArr[4],
        paramId5: paramsArr[5] === undefined ? "all" : paramsArr[5],
        paramId6: paramsArr[6] === undefined ? "all" : paramsArr[6],
        paramId7: paramsArr[7] === undefined ? "all" : paramsArr[7],
        paramId8: paramsArr[8] === undefined ? "all" : paramsArr[8],
        paramId9: paramsArr[9] === undefined ? "all" : paramsArr[9],
        paramId10: paramsArr[10] === undefined ? "all" : paramsArr[10],
        paramId11: paramsArr[11] === undefined ? "all" : paramsArr[11],
        paramId12: paramsArr[12] === undefined ? "all" : paramsArr[12],
        paramId13: paramsArr[13] === undefined ? "all" : paramsArr[13],
        paramId14: paramsArr[14] === undefined ? "all" : paramsArr[14],
    };
};

export const renderInputErrorLabel = (ErrorLabelState, value, text) => {
    // console.log(ErrorLabelState, value, isObjectCus(value), !isEmptyObject(value), Object.keys(value).length)
    let returnData = null;
    if (
        (ErrorLabelState &&
            (value === undefined ||
                typeof value === "undefined" ||
                ((typeof value === "string" || typeof value === "number") &&
                    String(value).length === 0))) ||
        (ErrorLabelState && isObjectCus(value) && isEmptyObject(value))
    ) {
        returnData = (
            <FormHelperText sx={{my: 1}} error>
                {text}
            </FormHelperText>
        );
    }

    return returnData;
};

