import React from 'react';
import { useRecoilValue, useRecoilState } from 'recoil';
import { Card, Divider } from '@mui/material';
import { genUUID } from '../../RAS_updates/Heplers';
import { siFundsFilterTableAtom, siFundGlobatMasterIdAtom, siFundMasterAtom, siFundReleaseTableAtom, siFundTotalSancTableAtom, siNameListAtom, siFundSiNameListAtom } from '../../RAS_updates/Heplers';
import { useNavigate } from 'react-router-dom';
import axiosInstance from '../../Services/AxiosInstance';
import { renderSubmitErrorAlert } from '../../RAS_updates/Heplers'
import {useParams} from 'react-router-dom';

import '../SIPayments/SiTable.css';

export const SiFundTable = ({ page = 0, size = 10 }) => {
  const tableData = useRecoilValue(siFundsFilterTableAtom);
  const [globalFundId, setGlobalFundId] = useRecoilState(siFundGlobatMasterIdAtom);
  const [sifundReleaseTable, setSiFundReleaseTable] = useRecoilState(siFundReleaseTableAtom);
  const [siFundTotalSancsTable, setSiFundTotalSancsTable] = useRecoilState(siFundTotalSancTableAtom);
  const [form, setForm] = useRecoilState(siFundMasterAtom);
  const [siNameList,setSiNameList] =useRecoilState(siFundSiNameListAtom);
  const navigate = useNavigate();
  const params = useParams();

  if (!Array.isArray(tableData) || tableData.length === 0) {
    return <p>No fund data available.</p>;
  }


  const handleSiClick = async (row) => {
    navigate(`/sipaymentsfundsupdate/update/${row.FundMasterId}`);
    try {
      const res = await axiosInstance.post(`/siFundMaster/FundMasterSubClasses?fundMasterId=${row.FundMasterId}`);

      if (res.status === 200 && res.data?.fundMasterDetails.siFundMaster) {
        // Set SI Card Atom
        setForm({
          siId: row.FundMasterId,
          ...res.data.fundMasterDetails.siFundMaster,
        });
        setGlobalFundId(row.FundMasterId); // Set global SI ID atom
        setSiNameList(res.data.siMasters.sis);
        // Set Total Sanc List Atom
        // Set Total Sanc Master Atom with the first object
        if (res.data.fundMasterDetails.siFundReleaseList && res.data.fundMasterDetails.siFundReleaseList.length > 0) {
          // setSiTotalSancMaster(res.data.siTotalSancList[0]); // First object
          setSiFundReleaseTable(res.data.fundMasterDetails.siFundReleaseList); // Full array for table
        }

        // Set SI WO Master Atom with the first object
        if (res.data.fundMasterDetails.siTotalSancMasterList && res.data.fundMasterDetails.siTotalSancMasterList.length > 0) {
          // setSiWOMaster(res.data.siWOList[0]); // First object
          setSiFundTotalSancsTable(res.data.fundMasterDetails.siTotalSancMasterList); // Full array for table
        }

      } else {
        renderSubmitErrorAlert(res.data?.error || "Operation failed");
      }

    } catch (err) {
      console.error("Fetch error:", err);
      renderSubmitErrorAlert("Something went wrong");
    }

  };
console.log("siNameList",siNameList);
  return (
    <div style={{ width: '100%', marginTop: '16px' }}>
      <Card className="cusTable" >
        {/* Desktop Table */}
        <table className="desktopTable">
          <thead>
            <tr>
              <th>Sno.</th>
              <th>State/UT</th>
              <th>Fund Id</th>
              <th>Balance (Cr)</th>
              <th>Next Fund to Release (Cr)</th>
              <th>Total Fund Released (Cr)</th>
              <th>Total Sanc PACS</th>
              <th>Utilization %</th>
            </tr>
          </thead>
          <tbody>
            {tableData.map((row, idx) => (
              <tr key={genUUID()}>
                <td>{page * size + idx + 1}</td>
                <td>
                  <span
                    className="dataListingCUI"
                    style={{
                      color: '#1976d2',
                      cursor: 'pointer',
                      textDecoration: 'underline'
                    }}
                    onClick={() => handleSiClick(row)}
                  >
                    {row.state?.empty === true || row.state?.present === false
                      ? '—'
                      : row.state?.name ?? '—'}
                  </span></td>
                <td>{row.FundMasterId || '-'}</td>
                <td>{row.balance ?? '—'}</td>
                <td>{row.nextFundToBeRelease ?? '—'}</td>
                <td>{row.totalFundReleased ?? '—'}</td>
                <td>{row.totalSancPacs ?? '_'}</td>
                <td> {typeof row.utilizationPercent === 'number'
                  ? row.utilizationPercent.toFixed(2) + '%'
                  : '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Mobile View */}
        <div className="mobileTable">
          {tableData.map((row, idx) => (
            <div key={genUUID()} className="responsiveTableRow">
              <div className="rowItem"><span>Sno.</span><span>{page * size + idx + 1}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem">
                <span>State/UT</span>
                <span
                  className="dataListingCUI"
                  style={{
                    color: '#1976d2',
                    cursor: 'pointer',
                    textDecoration: 'underline'
                  }}
                  onClick={() => handleSiClick(row)}
                > {row.state?.empty === true || row.state?.present === false
                  ? '—'
                  : row.state?.name ?? '—'}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>Fund ID</span><span>{row.FundMasterId ?? '—'}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>Balance (Cr)</span><span>{row.balance ?? '—'}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>Next Fund</span><span>{row.nextFundToBeRelease ?? '—'}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>Total Released (Cr)</span><span>{row.totalFundReleased ?? '—'}</span></div>
              <Divider className="mobileRowDivider" />

              <div className="rowItem"><span> Total Sanc PACS (Cr)</span><span>{row.totalSancPacs ?? '_'}</span></div>
              <Divider className="mobileRowDivider" />
              <div className="rowItem"><span>Utilization %</span>
                <span> {typeof row.utilizationPercent === 'number'
                  ? row.utilizationPercent.toFixed(2) + '%'
                  : '—'}</span></div>
              <Divider className="mobileRowDivider" />

            </div>
          ))}
        </div>
      </Card>

    </div>

  );
};
