import {Grid, Typography,} from "@mui/material";
import React, {useMemo} from "react";

import {
    capitalizeAllFirstLetter,
    FIELDVISIT_LINK,
    overViewTabAtom,
    paramsFromURL,
    useRecoilValue
} from "../../../../Heplers";
import {NewCusReqButton} from "../OverViewTotal";

export const DataListingHeaderComp = () => {

    const urlParams = paramsFromURL({
        linkToSplit: `${FIELDVISIT_LINK}listing/`,
    })

    // console.log(urlParams);

    const cusReqTabIndex = useRecoilValue(overViewTabAtom);

    return useMemo(() => {
        return (
            <>            <Grid item sx={{zoom: 0.7}} alignItems={"center"} xs={6}>
                <Typography
                    variant="h4"
                    sx={{
                        color: "#00261C",
                        paddingTop: "1%",
                        fontWeight: "550",
                        lineHeight: "42px",
                    }}
                >
                   Field Visits Records
                </Typography>
                {/* <Typography
                    variant="h6"
                    sx={{
                      color: "#333333",
                      fontWeight: "700",
                      fontSize: "32px",
                      fontFamily: "poppins",
                    }}
                  >
                    {totalReq}
                  </Typography> */}
            </Grid>

                {
                    (urlParams.paramId !== undefined && urlParams.paramId === 'preparation') && <Grid
                        item
                        display={"flex"}
                        justifyContent={"right"}
                        alignItems={"center"}
                        xs={6}
                        sx={{zoom: 0.7}}
                    >
                        <NewCusReqButton/>
                    </Grid>
                }

            </>
        );
    }, []);
};
