import { useRecoilState, useResetRecoilState } from "recoil";
import {
  siFundMasterAtom,
  siFundReleaseAtom,
  siFundTotalSancAtom
} from "../../RAS_updates/Heplers";

import React, { useEffect, useState } from "react";
import {
  Box,
  Card,
  Grid,
  TextField,
  Button,
  Typography,
  MenuItem,
  CssBaseline,
  Toolbar
} from "@mui/material";
import DrawerComp from "../../Components/Drawer/drawer";
import MainHeader from "../../Components/Header/MainHeader";
import axiosInstance from "../../Services/AxiosInstance";
import {
  renderSubmitErrorAlert,
  successAndGoBackAlert,
  useSuccessAndResetAlert,
  showSimpleSuccessAlert,
  siStateListAtom,
  siNameListAtom
} from "../../RAS_updates/Heplers";
import { getCookie } from "../../Services/Cookies";
import { CusReqDropdownSIPayment } from "../SIPayments/CusReqDropdownSIPayment";
import ManageSearchOutlinedIcon from "@mui/icons-material/ManageSearchOutlined";
import { SiWOMasterUploadFile } from "../SiWorkOrder/SiWoMasterUploadFile";
import { RestartAltRounded } from "@mui/icons-material";
import { useNavigate } from "react-router-dom";
import { useDuplicateStateErrorAlert } from "./DuplicateStateErrorAlert";
export default function SiFundMasterForm() {
  const [mode, setMode] = useState("create");
  const [showSubForms, setShowSubForms] = useState(false);
  const successFundAlert = useSuccessAndResetAlert(siFundMasterAtom, "Fund", false);
  const successFundReleaseAlert = useSuccessAndResetAlert(siFundReleaseAtom, "Fund", false);
  const successTotalSancAlert = useSuccessAndResetAlert(siFundTotalSancAtom, "Fund", false);

  const [fundMaster, setFundMaster] = useRecoilState(siFundMasterAtom);
  const [fundRelease, setFundRelease] = useRecoilState(siFundReleaseAtom);
  const [totalSanc, setTotalSanc] = useRecoilState(siFundTotalSancAtom);
  const [isFundMasterDisabled, setIsFundMastereDisabled] = useState(false)
  const [isFundReleaseDisabled, setIsFundReleaseDisabled] = useState(false);
  const [isTotalSancDisabled, setIsTotalSancDisabled] = useState(false);
  const resetFundMaster = useResetRecoilState(siFundMasterAtom);
  const resetFundRelease = useResetRecoilState(siFundReleaseAtom);
  const resetTotalSanc = useResetRecoilState(siFundTotalSancAtom);
  const [siNameOptions, setSiNameOptions] = useRecoilState(siNameListAtom);
  const [siNameData, setSiNameData] = useState([]);
  const [globalFundMasterId, setGlobalFundMasterId] = useState([]);
  const [globalStateUt, setGlobalStateUt] = useState(0);
  const [errorMessage, setErrorMessage] = useState("");
  const [showAlert, setShowAlert] = useState(false);
  const user_id = getCookie("resourceId");
  const navigate = useNavigate();

  useDuplicateStateErrorAlert(errorMessage, showAlert, setShowAlert);

  const handleChange = (setter) => (field) => (e) => {
    const value = e?.target?.value ?? e;
    setter((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  useEffect(() => {
    resetFundMaster();
    resetFundRelease();
    resetTotalSanc();
    handleMasterClear();
    handleFundReleaseClear();
    handleSancPacsClear();
  }, []);

  const handleMasterClear = () => {
    setFundMaster({
      stateUt: "",
      utilized: "",
      balance: "",
      nextFundToBeRelease: "",
      centreShareInterestAmtYetToBeDeposit: "",
      siWODoc: "",
      deficitAmt: "",
    });
  };

  const handleFundMasterSave = async () => {
    const user_id = getCookie("resourceId");
    if (!fundMaster.stateUt) {
      alert("Please Enter State Details ");
    }
    try {
      const payload = {
        ...fundMaster,
        stateUt: fundMaster.stateUt?.id ?? fundMaster.stateUt,
        createdBy: user_id,
      };

      const res = await axiosInstance.post("/siFundMaster/create", payload);
      if (res.status === 200 && res.data.message) {
        setShowSubForms(true);
        setSiNameOptions(res.data.siName.sis);
        setFundRelease((prev) => ({
          ...prev,
          stateUt: payload.stateUt,
          fundMasterId: res.data.FundMasterId,
        }));
        setGlobalStateUt(res.data.stateUt.id)
        setGlobalFundMasterId(res.data.FundMasterId);
        successFundAlert(res.data.message);
        // showSimpleSuccessAlert();
        setIsFundMastereDisabled(true);
      }
      //  else if (res.status === 400) {
      //   // alert(res.data.errorMessage || "Fund Master creation failed");
      //   console.error("Error creating Fund Master:", res.data.errorMessage);
      //   setErrorMessage(res.data.errorMessage || "Fund Master creation failed");
      //   setShowSubForms(false);
      //   setShowAlert(true);

      // }
       else {
        alert(res.data.errorMessage || "Fund Master creation failed");  
      }
    } catch (err) {
      const status = err?.response?.status;
      const message =
        err?.response?.data?.errorMessage ||
        err?.response?.data?.message ||
        "Fund Master creation failed";

      console.error("Error creating Fund Master:", message);

      if (status === 400) {
        setErrorMessage(message);
        setShowSubForms(false);
        setShowAlert(true); // 🔔 Custom SweetAlert via hook
      } else {
        console.log(message); // 🧾 Normal alert for other errors
      }
    }
  };

  const handleFundReleaseSave = async () => {
    try {
      const res = await axiosInstance.post("/siFundReleased/create", {
        ...fundRelease,
        stateUt: globalStateUt,
        fundMasterId: globalFundMasterId
      });
      if (res.status === 200 && res.data.message) {
        successFundReleaseAlert(res.data.message);
        // showSimpleSuccessAlert();
        setIsFundReleaseDisabled(true);
      }
      else {
        alert(res.data.errorMessage || "Fund Release creation failed");
      }
    } catch (err) {
      const message = err?.response?.data?.errorMessage || err?.response?.data?.message || "Fund Release creation failed";
      alert(message);
    }
  };
  const handleFundReleaseClear = () => {
    setFundRelease({
      id: 0,
      centreShare: 0,
      stateShare: 0,
      date: "",
    });
    // resetFundRelease();
    setIsFundReleaseDisabled(false); // re-enable on clear
  };

  const handleTotalSancSave = async () => {
    try {
      const payload = {
        createdBy: user_id,
        siMasterId: totalSanc.siName.siId,
        stateUt: fundMaster.stateUt?.id ?? fundMaster.stateUt,
        totalSancPACS: totalSanc.totalSancPACS,
        date: totalSanc.date,
      };

      const res = await axiosInstance.post("/siTotalSancMaster/create", payload);
      if (res.status === 200 && res.data.message) {
        successTotalSancAlert(res.data.message);
        setIsTotalSancDisabled(true);
        handleSancPacsClear()
        handleClose();
      } else {
        alert(res.data.error || "Total Sanc creation failed");
        handleSancPacsClear();
      }
    } catch (err) {
      const message = err?.response?.data?.errorMessage || err?.response?.data?.message || "Total Sanc creation failed";
      alert(message);
      handleSancPacsClear();
    }
  };

  const handleSancPacsClear = () => {
    setTotalSanc({
      siName: "",
      totalSancPACS: 0,
      date: ""
    });
    setIsTotalSancDisabled(false); // re-enable on clear
  };

  const handleClose = () => {
    navigate(-1);
  }
  // console.log("siNameOptions", siNameOptions);
  // console.log("siNameListAtom", siNameListAtom);
  console.log("show Alert ", showAlert);
  return (
    <div style={{ overflowX: "hidden" }}>
      <style>
        {`
               .css-10hburv-MuiTypography-root{
                 font-size:11px !important;
                 font-family: Poppins 
               }
               .css-yb0lig{
                 font-size:12px !important
               }
               `}
      </style>
      <Box sx={{ display: "flex" }}>
        <CssBaseline />
        <MainHeader />
        <DrawerComp listName={"SI Funds"} />
        <Box
          component="main"
          sx={{
            flexGrow: 1,
            backgroundColor: "#f4faf8",
          }}>
          <Toolbar />

          {/* {showAlert && (
            DuplicateStateErrorAlert(errorMessage);
           )}  */}
          <Grid container sx={{ p: 2 }}>
            {/* Fund Master */}
            <Card sx={{ p: 2, mb: 3 }}>
              <Typography variant="h6" sx={{ mb: 2 }}>SI Fund Master</Typography>
              <Grid container spacing={2}>
                <Grid item xs={12} md={4}>
                  <CusReqDropdownSIPayment
                    ddLabel="State/ UT"
                    dropdownName="stateUt"
                    //@ts-ignore
                    formDataAtom={siFundMasterAtom}
                    listDataAtom={siStateListAtom}
                    fetchMasterDataURL="fetchStateMasterData_CusReq"
                    // @ts-ignore
                    optionLabel={["StateNameAndCode", "name", "short_name", "code"]}
                    value={fundMaster.stateUt}
                    onChange={handleChange(setFundMaster)("stateUt")}
                    readOnly={isFundMasterDisabled}
                    required
                  />
                </Grid>
                <Grid item xs={12} md={4}>
                  <TextField
                    label="Utilized"
                    type="Number"
                    value={fundMaster.utilized}
                    onChange={handleChange(setFundMaster)("utilized")}
                    fullWidth
                    disabled={isFundMasterDisabled}
                  />
                </Grid>
                <Grid item xs={12} md={4}>
                  <TextField
                    label="Balance"
                    type="Number"
                    value={fundMaster.balance}
                    onChange={handleChange(setFundMaster)("balance")}
                    fullWidth
                    disabled={isFundMasterDisabled}
                  />
                </Grid>
                <Grid item xs={12} md={4}>
                  <TextField
                    label="Next Fund To Be Released"
                    type="Number"
                    value={fundMaster.nextFundToBeRelease}
                    onChange={handleChange(setFundMaster)("nextFundToBeRelease")}
                    fullWidth
                    disabled={isFundMasterDisabled}
                  />
                </Grid>
                <Grid item xs={12} md={4}>
                  <TextField
                    label="Centre Share Interest Yet To Be Deposit"
                    type="Number"
                    value={fundMaster.centreShareInterestAmtYetToBeDeposit}
                    onChange={handleChange(setFundMaster)("centreShareInterestAmtYetToBeDeposit")}
                    fullWidth
                    disabled={isFundMasterDisabled}
                  />
                </Grid>
                <Grid item xs={12} md={4}>
                  <TextField
                    label="Deficit Amount"
                    type="Number"
                    value={fundMaster.deficitAmt}
                    onChange={handleChange(setFundMaster)("deficitAmt")}
                    fullWidth
                    disabled={isFundMasterDisabled}
                  />
                </Grid>
                <Grid item xs={12} md={8}>
                  <SiWOMasterUploadFile formAtom={siFundMasterAtom} />
                </Grid>
              </Grid>
              <Box sx={{ mt: 2, display: "flex", justifyContent: "flex-end", gap: 1 }}>
                <Button
                  variant="contained"
                  onClick={handleFundMasterSave}
                  color="success"
                >
                  Save <ManageSearchOutlinedIcon sx={{ width: 20, ml: 1 }} />
                </Button>
                <Button
                  variant="contained"
                  color="warning"
                  onClick={handleMasterClear}
                  disabled={isFundMasterDisabled}
                >
                  Clear <RestartAltRounded sx={{ width: 20, ml: 1 }} />
                </Button>
              </Box>

            </Card>

            {showSubForms && (
              <Grid container spacing={3} >
                {/* Fund Release */}
                <Grid item xs={12}>
                  <Card sx={{ p: 2, mb: 3 }}>
                    <Typography variant="h6" sx={{ mb: 2 }}>SI Fund Released</Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={4}>
                        <TextField
                          label="Centre Share"
                          type="Number"
                          value={fundRelease.centreShare}
                          onChange={handleChange(setFundRelease)("centreShare")}
                          fullWidth
                          disabled={isFundReleaseDisabled}
                        />
                      </Grid>
                      <Grid item xs={12} md={4}>
                        <TextField
                          label="State Share"
                          type="Number"
                          value={fundRelease.stateShare}
                          onChange={handleChange(setFundRelease)("stateShare")}
                          fullWidth
                          disabled={isFundReleaseDisabled}
                        />
                      </Grid>
                      <Grid item xs={12} md={4}>
                        <TextField
                          label="Date"
                          type="date"
                          value={fundRelease.date}
                          onChange={handleChange(setFundRelease)("date")}
                          InputLabelProps={{ shrink: true }}
                          fullWidth
                          disabled={isFundReleaseDisabled}
                        />
                      </Grid>
                    </Grid>
                    <Box sx={{ mt: 2, textAlign: "right" }}>
                      <Button
                        variant="contained"
                        onClick={handleFundReleaseSave}
                        color="success"
                        sx={{ mr: 2 }}>
                        Save <ManageSearchOutlinedIcon sx={{ width: 20, ml: 1 }} />
                      </Button>
                      <Button
                        variant="contained"
                        color="warning"
                        onClick={handleFundReleaseClear}
                        disabled={isFundReleaseDisabled}
                      >
                        Clear <RestartAltRounded sx={{ width: 20, ml: 1 }} />
                      </Button>
                    </Box>
                  </Card>
                </Grid>

                {/* Total Sanctions */}
                <Grid item xs={12}>
                  <Card sx={{ p: 2 }}>
                    <Typography variant="h6" sx={{ mb: 2 }}>SI Total Sanctioned PACs</Typography>
                    <Grid container spacing={2}>
                      {/* SI Name */}
                      <Grid item xs={12} md={4}>
                        {/* @ts-ignore */}
                        <CusReqDropdownSIPayment
                          // @ts-ignore
                          formDataAtom={siFundTotalSancAtom}
                          // @ts-ignore
                          listDataAtom={siNameListAtom}
                          ddLabel="SI Name"
                          dropdownName="siName"
                          optData={siNameOptions}
                          // @ts-ignore
                          // fetchMasterDataURL="/si-payments/siswithStates"
                          // @ts-ignore
                          optionLabel={["sis", "state", "siId"]}
                          value={totalSanc.siName || ""}
                          onChange={handleChange(setTotalSanc)("siName")}
                          readOnly={isTotalSancDisabled}
                        />

                      </Grid>
                      <Grid item xs={12} md={4}>
                        <TextField
                          label="Total Sanctioned PACs"
                          type="Number"
                          value={totalSanc.totalSancPACS}
                          onChange={handleChange(setTotalSanc)("totalSancPACS")}
                          fullWidth
                          disabled={isTotalSancDisabled}
                        />
                      </Grid>
                      <Grid item xs={12} md={4}>
                        <TextField
                          label="Date"
                          type="date"
                          value={totalSanc.date}
                          onChange={handleChange(setTotalSanc)("date")}
                          InputLabelProps={{ shrink: true }}
                          fullWidth
                          disabled={isTotalSancDisabled}
                        />
                      </Grid>
                    </Grid>
                    <Box sx={{ mt: 2, textAlign: "right" }}>
                      <Button variant="contained" onClick={handleTotalSancSave} color="success" sx={{ mr: 2 }}>
                        Save <ManageSearchOutlinedIcon sx={{ width: 20, ml: 1 }} />
                      </Button>
                      <Button
                        variant="contained"
                        color="warning"
                        onClick={handleSancPacsClear}
                        sx={{ mr: 2 }}
                      >
                        Clear <RestartAltRounded sx={{ width: 20, ml: 1 }} />
                      </Button>
                      <Button
                        variant="outlined"
                        color="error"
                        onClick={handleClose}
                      >
                        Close
                      </Button>
                    </Box>
                  </Card>
                </Grid>
              </Grid>
            )}
          </Grid>
        </Box>
      </Box>
    </div>
  );
}
