import {
    Card,
    CardActionArea,
    CardContent,
    Divider,
} from "@mui/material";
import React, { useMemo } from "react";
import {
    cusReqCUIMasterDetailsAtom, isARDBCusReqTabActive, overViewTabAtom,
    useRecoilValue,
} from "../../../../Heplers";
import moment from "moment";
import { CusReqDetailsCard_Pre } from "./CusReqDetailsCard_Pre";
import { CusReqDetailsCard_BRD } from "./CusReqDetailsCard_BRD";
import { CusReqDetailsCard_UAT } from "./CusReqDetailsCard_UAT";
import { CusReqDetailsCard_Dev } from "./CusReqDetailsCard_Dev";


export function CusReqDetailsCard() {
    const Atom = useRecoilValue(cusReqCUIMasterDetailsAtom);

    return useMemo(() => {

        const { pre } = Atom;
        console.log({pre});
        return (Atom.pre !== undefined && Atom.pre.cui !== undefined) && (

            <Card>
                <CardActionArea
                    sx={{
                        backgroundColor: "#065036",
                        color: "#FFF",
                        borderRadius: "unset",
                        px: 2,
                        fontSize: 14,
                        // fontWeight: "bold",
                    }}
                >
                    <p>
                        <span style={{ fontWeight: 600 }}>
                            {pre.ardb_pacs ===  "Yes" ? "ARDB" : "PACS"}
                            <br />
                            Customization Unique Identification (CUI):
                            <br />
                        </span>
                        <b>{pre.cui}</b>
                    </p>
                </CardActionArea>

                <CardContent sx={{ fontSize: 13 }}>
                    {pre.old_uic !== null && <><b>OLD UIC:</b><br /> {pre.old_uic}<Divider sx={{ my: 1, width: "25%" }} /></>}

                    <b>Customization Category:</b><br /> {pre.bucket}

                    <Divider sx={{ my: 1, width: "25%" }} />
                    <b>Customization Description:</b> <br /> {pre.descrip}

                    <Divider sx={{ my: 1, width: "25%" }} />
                    <b>State/ UT:</b> <br /> {pre.state}

                    <Divider sx={{ my: 1, width: "25%" }} />
                    <b>Date of Request:</b> <br /> {pre.dor !== null && moment(pre.dor, "YYYY-MM-DD").format("DD-MMM-YY")}

                    <Divider sx={{ my: 1, width: "25%" }} />
                    <b>Expected Date of Resolution:</b> <br /> {pre.edorf !== null && moment(pre.edorf, "YYYY-MM-DD").format("DD-MMM-YY")}

                    <CusReqDetailsCard_Pre />

                    <CusReqDetailsCard_BRD />

                    <CusReqDetailsCard_Dev />

                    <CusReqDetailsCard_UAT />

                </CardContent>
            </Card>
        );
    }, []);
}
