export default function ReportDownloadCusReq() {
  const [RGDate, setRGDate] = React.useState(currentDate);
  const filterAtom = useRecoilValue(cusReqFilterFormAtom);

  const cusReqTabIndex = useRecoilValue(overViewTabAtom);

  const downloadCusReq = (v, setProcessing) => {
    setProcessing(true);

    // console.log(ReportCardsArr);
    console.log(filterAtom, filterAtom.state);
    // return;

    let contentType =
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

    const state_code = (filterAtom.state !== undefined && filterAtom.state.code !== undefined && !isNaN(filterAtom.state.code)) ? filterAtom.state.code : null;

    const stateName = (filterAtom.state !== undefined && filterAtom.state.code !== undefined && !isNaN(filterAtom.state.code)) ? `_${filterAtom.state.name.replace(/ /g, '_')}` : "";

    const is_ardb = isARDBCusReqTabActive(cusReqTabIndex);

    const ori_date = RGDate;

    // This to include current in between clause in the query
    const date = moment(RGDate).add(1, 'days').format("YYYY-MM-DD");

    // Default filename if server dooesn't provide one
    // let fileName = `${v.downloadFileName}_${moment(new Date()).format("DD_MM_YYYY")}`;
    let fileName = `${v.downloadFileName}${stateName}_${cusReqTabIndex.replace('_tab', '').toUpperCase()}_${moment(RGDate).format("DD_MM_YYYY")}_ePACSPMC.co.in`;

    // If the report is new, we will use the new file name
    const oldReport =  v.newreport === undefined

    // console.log({oldReport})
    const config = {
      method: "post",

      // Dynamic Check
      url: `${API_Endpoint()}/file/download/${v.endpoint}`,
      // url: `${API_Endpoint()}/cusreqsummaryexcel`,

      // headers: {
      //   email: getCookie("email2"),
      //   "access-token": getCookie("token"),
      //   Authorization: `Bearer ${getCookie("token")}`,
      //   "Content-Type": "application/json",
      // },
      responseType: oldReport ? "blob" : "json", // Important for downloading files
      data: {
        fileName,
        date,
        is_ardb,
        state_code,
        ori_date
      }
    };

    // IMPORTANT USE NAKED AXIOS FROM LIBRABY
    // @ts-ignore
    axios(config)
        .then((res) => {
          if (res.status === 200 && res.data !== null) {
            setProcessing(false);

            if(oldReport){
              // Check if Content-Disposition header exists
              const contentDisposition = res.headers["content-disposition"];
              if (contentDisposition) {
                // Extract filename from Content-Disposition header
                const matches = contentDisposition.match(/filename="(.+?)"/);
                if (matches) {
                  fileName = matches[1]; // Set filename dynamically
                }
              }

              // Create a URL for the blob
              const blob = new Blob([res.data], { type: contentType });
              const link = document.createElement("a");
              link.href = window.URL.createObjectURL(blob);
              link.download = fileName;
              document.body.appendChild(link);
              link.click();
              document.body.removeChild(link);
            } else {
                // For new report, download the file directly

              console.log("new report link", res);

              if(String(res.data).indexOf("BackDatedReportDoesn'tExist") !== -1){
                return invalidURLAlert("Error", "Report doesn't exist for the selected date, please try again with different date", "", false);
              }

              const link = document.createElement("a");

              // /var/www/html/report_gen/Cus_Req_Brief_Excel_Summary_ePACS_PMC_16_06_2025.xlsx

              let linkUrl = res.data;
              if(String(window.location.hostname).toLocaleLowerCase() === 'epacspmc.co.in'){
                linkUrl = "https://epacspmc.co.in//prod_backend_media/" + res.data.replace('/var/www/html/', '');
              }
              // else {
              //  //Doesn't work in local
              //   window.location.href = linkUrl;
              // }

              link.href = linkUrl;
              link.target = "_blank";
              document.body.appendChild(link);
              link.click();
              document.body.removeChild(link);
            }

            // alert("Excel downloaded successfully.");

            successAndGoBackAlert(
                "Report Generated",
                v.detail + " downloading will start shortly, please check browser downloads",
                false
            );
          }
          else {
              invalidURLAlert("Error", "Unable to generated report, please try again later", "", false);
          }
        })
        .catch((err) => {
          console.log(err);
          if (err.response.status === 404) {
            alert("Error: Expired or invalid JWT token");
            // setProcessing(false);
          }
        });
  };
  const ReportCardComp = ({ v }) => {
    const [processing, setProcessing] = React.useState(false);

    // console.log({ v, RGDate })

    return useMemo(() => {
      // console.log("rendering", ReportCardsArr);
      // console.log("rendering", ReportCardsArr);
      // console.log("rendering", ReportCardsArr);

      return (
          <Grid item xs={12} md={4}>
            <Paper elevation={3} sx={{ px: 2, color: "#065036" }}>
              <Grid
                  display="flex"
                  direction="row"
                  container
                  alignItems="center"
              >
                {processing ? (
                    <CardContent sx={{ p: 4 }}>
                      Downloading ... <CircularProgress size="1rem" />
                    </CardContent>
                ) : (
                    <Grid container  display="flex"
                           direction="row" onClick={() => downloadCusReq(v, setProcessing)} className="cursorPoint">

                      <CardContent sx={{ py: 1 }}>
                        <Grid container display="flex"
                              direction="row">
                          <Typography gutterBottom variant="h6" component="div">
                            {v.name}
                          </Typography><CloudDownload sx={{ color: "#065036",  ml: 1, mt: 0.5 }} />

                        </Grid>
                        <Typography variant="body2" sx={{ color: "text.secondary" }}>
                          {v.detail}
                        </Typography>
                      </CardContent>
                    </Grid>
                )}
              </Grid>
            </Paper>
          </Grid>
      );
    }, [processing]);
  };

  return useMemo(() => {
    // console.log("rendering", ReportCardsArr);

    return (
      <>
        <Divider
          sx={{ my: 2 }}
          className="OverviewCardTableCellStages"
          textAlign="left"
        >
          {cusReqTabIndex.replace('_tab', '').toUpperCase()} Customization Request Reports
        </Divider>

        {/*{*/}
        {/*  Number(getCookie("resourceId")) === 44 && <a target={"_blank"}*/}

        {/*        // href="https://epacspmc.co.in/prod_backend_media/report_gen/Cus_Req_Excel_Summary_ePACS_PMC_16_06_2025.xlsx"*/}

        {/*        // href="https://epacspmc.co.in/prod_backend_media/report_gen/Cus_Req_Brief_Excel_Summary_ePACS_PMC_16_06_2025.xlsx"*/}

        {/*        // href="https://epacspmc.co.in/prod_backend_media/report_gen/Pending_Closed_State_Wise_Cus_Req_ePACS_PMC_16_06_2025.xlsx"*/}


        {/*                                               href="https://epacspmc.co.in/prod_backend/api/v1/nabard/downloadlargefile"*/}
        {/*    >Test download sheet</a>*/}
        {/*}*/}


        <Grid container justifyContent={"end"} pb={2}  spacing={2} columns={12}>
          <Grid item md={3} xs={12}>
            <CusReqDropdown
                // @ts-ignore
                formDataAtom={cusReqFilterFormAtom}
                listDataAtom={cusReqStateListAtom}
                ddLabel="State/ UT/ HO"
                dropdownName={"state"}
                fetchMasterDataURL={isARDBCusReqTabActive(cusReqTabIndex) === 'Yes'? 'fetchStateARDBMasterData_CusReq' : 'fetchStateMasterData_CusReq'}
                // @ts-ignore
                optionLabel={["StateNameAndCode", "name", "short_name", "code"]}

            />
          </Grid>
          <Grid item md={3} xs={12}>
            <TextField
                label="Report Generation as on"
                variant="outlined"
                type="date"

                defaultValue={RGDate}
                fullWidth
                InputLabelProps={{
                  shrink: true,
                }}
                InputProps={{inputProps: { min: "2025-07-27", max: currentDate } }}
                onChange={(e) => setRGDate(e.target.value)}

            />
          </Grid>
        </Grid>

        <Grid container spacing={2} pb={10}>
          {ReportCardsArr.map((v) => (
            <ReportCardComp key={genUUID()} v={v} date={RGDate} />
          ))}
        </Grid>
      </>
    );
  }, [RGDate, filterAtom]);
}
