import { Divider, Grid, TextField, Typography } from "@mui/material";
import {
  SubmitErrorAlertAtom,
  useRecoilState,
  ErrorLabelAtom,
  isEmptyObject,
  formatDate,
  StakeholderStatusArr,
  cusReqStCBStatusListAtom,
  isObjectCus, isARDBCusReqTabActive, useRecoilValue, overViewTabAtom, currentDate
} from "../../../../Heplers";
import React, { useEffect, useMemo } from "react";
import { CusReqDropdown, defTextFieldOnChange } from "..";
import {getCookie} from "../../../../../Services/Cookies";

export const StCBInputs = ({ formAtom, md, readOnly }) => {

  const [Atom, setAtom] = useRecoilState(formAtom);
  // forCheckingInputErrorLabelOnlyAfterSubmit
  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);

  const defTextFieldOnChangeComParams = {
    setAtom, SubmitErrorAlert, setSubmitErrorAlert
  }

  useEffect(() => {
    // Setting Default Value
    // console.log(Atom)
    // For Update Form
    if (!isEmptyObject(Atom)) {
      typeof Atom.stcb_inputs === 'string' && defTextFieldOnChange(Atom.stcb_inputs, "stcb_inputs", defTextFieldOnChangeComParams);
      // Some API key name is nlpsv_inputs & some nlpsv_inputs
      typeof Atom.stcb_inputs === 'string' && defTextFieldOnChange(Atom.stcb_inputs, "stcb_inputs", defTextFieldOnChangeComParams);
      typeof Atom.stcb_date === 'number' && defTextFieldOnChange(formatDate(Atom.stcb_date, 'db-yyyy-mm-dd'), "stcb_date", defTextFieldOnChangeComParams);
    }
  }, []);

  // PACS - ARDB Common Stakeholder
  if(
      getCookie("userRole").replace(/_/g, " ").toUpperCase() === "STCB" ||
      getCookie("userRole").replace(/_/g, " ").toUpperCase() === "SCARDB HO"
  ){
    readOnly = false;
  }

  const cusReqTabIndex = useRecoilValue(overViewTabAtom);

  return useMemo(() => {
    return (

      <Grid item spacing={2} xs={12} md={md} container direction={'column'}>

        <Grid item>
          <Divider textAlign="left" sx={{ width: "50%", my: 2 }}>
            <Typography className={'greenText'} fontSize={13} fontWeight="700">{isARDBCusReqTabActive(cusReqTabIndex) ===  "Yes" ? "SCARDB HO" : "StCB"}</Typography>
          </Divider>
          <TextField
            label="Date"
            variant="outlined"
            type="date"
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? formatDate(Atom.stcb_date, 'db-yyyy-mm-dd') : null}
            fullWidth

            InputProps={{inputProps: { max: currentDate } }}
            InputLabelProps={{
              shrink: true,
            }}
            onChange={(e) => readOnly ? null :defTextFieldOnChange(e.target.value, "stcb_date", defTextFieldOnChangeComParams)}

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
        </Grid>

        <Grid item>
          <CusReqDropdown
            // @ts-ignore
            formDataAtom={formAtom}
            listDataAtom={cusReqStCBStatusListAtom}
            ddLabel="Status"
            dropdownName={"stcb_status"}
            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? (Atom.stcb_status === null ? Atom.stcb_status : Atom.stcb_status) : null}
            optData={StakeholderStatusArr}

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
          {/* @ts-ignore */}
        </Grid>

        <Grid item>
          <TextField
            label="Remarks"
            multiline
            variant="outlined"
            rows={4}
            fullWidth
            InputLabelProps={{
              shrink: true,
            }}
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.stcb_inputs : null}
            onChange={(e) => readOnly ? null :defTextFieldOnChange(e.target.value, "stcb_inputs", defTextFieldOnChangeComParams)}

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}

          />
        </Grid>
      </Grid>


    );
  }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
