import React, { useEffect, useState } from 'react';
import { useRecoilState, useSetRecoilState } from 'recoil';
import { siTotalSancMasterTableAtom, siTotalSancMasterAtom, siStateListAtom, modeSiTotalSancMasterAtom } from '../../RAS_updates/Heplers';
import { Card, Divider } from '@mui/material';
import axiosInstance from '../../Services/AxiosInstance';
import { genUUID } from '../../RAS_updates/Heplers';
import '../SIPayments/SiTable.css';
import moment from 'moment';

export const SiTotalSancMasterTable = ({ page = 0, size = 10 }) => {
  const [tableData, setTableData] = useRecoilState(siTotalSancMasterTableAtom);
  const [stateList] = useRecoilState(siStateListAtom);
  const [form, setForm] = useRecoilState(siTotalSancMasterAtom);
  const setMode = useSetRecoilState(modeSiTotalSancMasterAtom);
  const [isIdColumnVisible, setIsIdColumnVisible] = useState(false);
  // useEffect(() => {
  //   const fetchData = async () => {
  //     try {
  //       const res = await axiosInstance.post('/siTotalSancMaster/all');
  //       if (res.status === 200) {
  //         setTableData(res.data.data);
  //       }
  //     } catch (err) {
  //       console.error('Failed to fetch data:', err);
  //     }
  //   };
  //   fetchData();
  // }, [setTableData]);

  if (!Array.isArray(tableData) || tableData.length === 0) {
    return <p>No data submitted yet.</p>;
  }

  const getStateLabel = (stateUtObj) => {
    if (stateUtObj && typeof stateUtObj === "object") {
      return `${stateUtObj.name} (${stateUtObj.short_name} - ${stateUtObj.code})`;
    }
    return "—";
  };

  const handleSiNameClick = (row) => {
    setForm({
      createdBy: row.createdBy,
      siName: row.siName,
      id: row.id,
      stateUt: row.stateUt,
      totalSancPACS: row.totalSancPACS,
      siMasterId: row.siMasterId,
      date: row.date
    });
    setMode('edit');
  };

  return (
    <div style={{ width: '100%' }}>
      <Card className="cusTable" sx={{ mt: 2 }}>
        <table className="desktopTable">
          <thead>
            <tr>
              <th>Sno.</th>
              <th>State/UT</th>
              <th>Total Sanc PACs</th>
              <th>Date</th>
              {isIdColumnVisible && <th>Id</th>}
            </tr>
          </thead>
          <tbody>
            {tableData.map((row, idx) => (
              <tr key={genUUID()}>
                <td>{page * size + idx + 1}</td>
                <td>
                  <span
                    className="dataListingCUI"
                    style={{ color: '#1976d2', cursor: 'pointer', textDecoration: 'underline' }}
                    onClick={() => handleSiNameClick(row)}
                  >{getStateLabel(row.stateUt)}
                  </span></td>
                <td>{row.totalSancPACS ?? '—'}</td>
                <td>{row.date ? moment(row.date).format('MM/DD/YYYY') : '—'}</td>
                {isIdColumnVisible && <td>{row.id}</td>}
              </tr>
            ))}
          </tbody>
        </table>

        <div className="mobileTable">
          {tableData.slice(page * size, page * size + size).map((row, idx) => (
            <div key={genUUID()} className="responsiveTableRow">
              <div className="rowItem">
                <span>Sno.</span>
                <span>{page * size + idx + 1}</span>
              </div>
              <Divider className="mobileRowDivider" />

              <div className="rowItem"
                onClick={() => handleSiNameClick(row)}>
                <span>State/UT</span>
                <span>{getStateLabel(row.stateUt)}</span>
              </div>
              <Divider className="mobileRowDivider" />

              <div className="rowItem">
                <span>Total Sanc PACs</span>
                <span>{row.totalSancPACS ?? '—'}</span>
              </div>
              <Divider className="mobileRowDivider" />

              <div className="rowItem">
                <span>Date</span>
                <span>{row.date ? moment(row.date).format('MM/DD/YYYY') : '—'}</span>
              </div>
              <Divider className="mobileRowDivider" />
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
};
