import {Grid, Paper, Typography} from "@mui/material";
import {
    cusReqMasterDataAtom, cusReqShowstopperListAtom,
    cusReqStateListAtom,
    ErrorLabelAtom, genUUID,
    isEmptyObject,
    isObjectCus,
    renderInputErrorLabel,
    SubmitErrorAlertAtom,
    useRecoilState, yesNoArr
} from "../../../../Heplers";
import React, {useMemo} from "react";
import {CusReqDropdown, RadioYesNo} from "..";
import {CardGreenHeader} from "../../../CustomizationRequest/Components/CardGreenHeader";

export const Stability_N_Accessibility = ({readOnly}) => {

    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);


    return useMemo(() => {
        return (
            <Paper elevation={2} sx={{mb: 2}} className={"greenBorder"}>
                <CardGreenHeader text={"Software Stability & Language Accessibility"}/>

                <Grid p={2} spacing={2} container>

                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sta_acc1"} ddLabel={"Software Loading Time"} YesValue={"Opens Quickly"} NoValue={"Latency Issues"}  defVal={"Opens Quickly"} />
                    </Grid>

                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sta_acc2"} ddLabel={"Ease of useability"} YesValue={"User Friendly"} NoValue={"Not User Friendly"} defVal={"User Friendly"}  />
                    </Grid>

                    <Grid item xs={12} md={4}></Grid>

                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sta_acc3"} ddLabel={"Is the software available in local language"} />
                    </Grid>

                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sta_acc4"} ddLabel={"Is the PACS personnel able to enter data in local language"} />
                    </Grid>

                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"sta_acc5"} ddLabel={"Is the support center, ticketing tool available in local language"} />
                    </Grid>

                </Grid>
            </Paper>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
