import React, { useState, useEffect } from 'react';
import Chart from 'react-apexcharts';
import { Box, Tabs, Tab, Typography, Stack, TextField, MenuItem } from '@mui/material';
import { getCookie } from '../../Services/Cookies';
import axiosInstance from '../../Services/AxiosInstance';
import './fundsBalance.css';

const StateBarChart = () => {
  const [tab, setTab] = useState(0);
  const [selectedState, setSelectedState] = useState('');
  const [stateNames, setStateNames] = useState([]);
  const [stateData, setStateData] = useState({});
  const [topUtilizedData, setTopUtilizedData] = useState({});
  const [singleStateData, setSingleStateData] = useState(null);
  const [topBalanceData, setTopBalanceData] = useState({});

  const config = {
    headers: {
      email: getCookie("email2"),
      "access-token": getCookie("token"),
      Authorization: `Bearer ${getCookie("token")}`,
    },
  };

  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: 'smooth' });

    const fetchStateSummary = async () => {
      try {
        const res = await axiosInstance.post('/siFundMastergraph/state-wise-summary', config);
        if (res.status === 200) {
          setStateData(res.data);
          setStateNames(Object.keys(res.data));
        }
      } catch (err) {
        console.error("Error fetching state summary data:", err);
      }
    };

    fetchStateSummary();
  }, []);

  useEffect(() => {
    const fetchSingleState = async () => {
      if (!selectedState) return;
      try {
        const res = await axiosInstance.post(
          `/siFundMastergraph/state?stateName=${encodeURIComponent(selectedState)}`,
          config
        );
        if (res.status === 200 && res.data[selectedState]) {
          setSingleStateData(res.data[selectedState]);
        }
      } catch (err) {
        console.error("Error fetching single state data:", err);
      }
    };

    if (tab === 3) fetchSingleState();
  }, [selectedState, tab]);

  useEffect(() => {
    const fetchTopUtilized = async () => {
      if (tab !== 1) return;
      try {
        const res = await axiosInstance.post('/siFundMastergraph/top-utilized-states', config);
        if (res.status === 200) {
          setTopUtilizedData(res.data);
        }
      } catch (err) {
        console.error("Error fetching top utilized data:", err);
      }
    };
    fetchTopUtilized();
  }, [tab]);

  useEffect(() => {
    const fetchTopBalance = async () => {
      if (tab !== 0) return;
      try {
        const res = await axiosInstance.post('/siFundMastergraph/top5-balance', config);
        if (res.status === 200) {
          setTopBalanceData(res.data);
        }
      } catch (err) {
        console.error("Error fetching top 5 balance data:", err);
      }
    };
    fetchTopBalance();
  }, [tab]);

  const prepareSeries = () => {
    if (tab === 3) {
      if (singleStateData) {
        return [
          { name: 'Total Funds', data: [singleStateData.total ?? 0] },
          { name: 'Utilized Funds', data: [singleStateData.utilized ?? 0] },
          { name: 'Balance Funds', data: [singleStateData.balance ?? 0] },
        ];
      } else {
        // No state selected, show empty chart
        return [
          { name: 'Total Funds', data: [] },
          { name: 'Utilized Funds', data: [] },
          { name: 'Balance Funds', data: [] },
        ];
      }
    }
    if (tab === 0) {
      return [
        { name: 'Total Funds', data: Object.values(topBalanceData).map(d => d.total) },
        { name: 'Utilized Funds', data: Object.values(topBalanceData).map(d => d.utilized) },
        { name: 'Balance Funds', data: Object.values(topBalanceData).map(d => d.balance) },
      ];
    }
    if (tab === 1) {
      return [
        { name: 'Total Funds', data: Object.values(topUtilizedData).map(d => d.total) },
        { name: 'Utilized Funds', data: Object.values(topUtilizedData).map(d => d.utilized) },
        { name: 'Balance Funds', data: Object.values(topUtilizedData).map(d => d.balance) },
      ];
    }
    if (tab === 2) {
      return [
        { name: 'Total Funds', data: Object.values(stateData).map(d => d.total) },
        { name: 'Utilized Funds', data: Object.values(stateData).map(d => d.utilized) },
        { name: 'Balance Funds', data: Object.values(stateData).map(d => d.balance) },
      ];
    }
    return [];
  };

  const isHorizontal = tab === 2;
  const chartOpts = {
    chart: { type: 'bar', background: '#D9D9D980' },
    plotOptions: {
      bar: {
        horizontal: isHorizontal,
        columnWidth: isHorizontal ? undefined : '80%',
        barHeight: isHorizontal ? '70%' : undefined,
        borderRadius: 4,
        dataLabels: { position: 'center' },
      },
    },
    xaxis: {
      categories: (() => {
        if (tab === 3) {
          return (selectedState && singleStateData) ? [selectedState] : [];
        } else if (tab === 0) {
          return Object.keys(topBalanceData);
        } else if (tab === 1) {
          return Object.keys(topUtilizedData);
        } else if (tab === 2) {
          return Object.keys(stateData);
        }
        return [];
      })(),
      labels: {
        style: {
          fontSize: '12px',
          fontFamily: 'Poppins',
          colors: ['#000'],
        },
      },
    },
    dataLabels: {
      enabled: true,
      formatter: (val) => `${val} Cr`, 
      style: {
        fontSize: '12px',
        colors: ['#808080'],
        Padding: '4px',
      },
      offsetX: isHorizontal ? -6 : 0,
      offsetY: isHorizontal ? 0 : -8,
      orientation: isHorizontal ? 'horizontal' : 'vertical',
      textAnchor: 'middle',
    },
    legend: { position: 'bottom' },
  };

  const dynamicHeight = () => {
    if (tab === 2) {
      const itemCount = Object.keys(stateData).length;
      return Math.max(400, itemCount * 55); // At least 400px
    }
    return 300;
  };

  return (
    <Box sx={{
      overflowX: tab === 2 ? 'auto' : 'hidden',
      overflowY: tab === 2 ? 'auto' : 'hidden',
      maxHeight: tab === 2 ? '600px' : 'auto',
      padding: 2,
      backgroundColor: '#f4f4f4',
      borderRadius: '8px',
    }}>
      <Typography
        sx={{
          fontSize: '18px',
          fontWeight: 600,
          fontFamily: 'Poppins',
          marginBottom: 2,
          textAlign: 'left',
          color: '#333'
        }}
      >
        State Based Funds Report
      </Typography>
      <Tabs
        value={tab}
        onChange={(_, v) => {
          setTab(v);
          setSingleStateData(null); // Reset state data when switching tabs
        }}
        sx={{ mb: 2 }}
      >
        <Tab label="Top 5 Balance" />
        <Tab label="Top 5 Utilized" />
        <Tab label="All States" />
        <Tab label="Search by State" />
      </Tabs>
      {tab === 3 && (
        <Stack direction="row" alignItems="center" spacing={2} sx={{ mb: 2 }}>
          <TextField
            select
            label="Search by State"
            value={selectedState}
            onChange={e => setSelectedState(e.target.value)}
            sx={{ minWidth: 220 }}
            placeholder="Search by State"
          >
            {stateNames.map((state, idx) => (
              <MenuItem key={state} value={state}>
                {state}
              </MenuItem>
            ))}
          </TextField>
        </Stack>
      )}

      <Chart
        options={chartOpts}
        series={prepareSeries()}
        type="bar"
        width="100%"
        height={dynamicHeight()}
        className={`state-bar-chart ${tab === 2 ? 'horizontal-mode' : ''}`}
      />
    </Box>
  );
};

export default StateBarChart;