import {Card, Grid, Pagination} from "@mui/material";
import React, {useEffect, useMemo} from "react";
import {useNavigate} from "react-router-dom";

import {
    cusReqDataListingAtom,
    CUSTOMIZATIONREQUEST_LINK,
    dataListingLoadingAtom,
    isARDBCusReqTabActive,
    overViewTabAtom,
    paramsFromURL,
    useRecoilState,
    useRecoilValue,
    useSetRecoilState
} from "../../../Heplers";
import {APICallDataListing, getDataListingURL} from "../CustomizationRequestListing";

export default function CusReqListingHeader() {

    const setLoading = useSetRecoilState(dataListingLoadingAtom);
    const [Atom, setAtom] = useRecoilState(cusReqDataListingAtom);

    useEffect(() => {
    }, []);


    const navigate = useNavigate();

    const cusReqTabIndex = useRecoilValue(overViewTabAtom);

    // const navigate = useHistory();
    return useMemo(() => {

        const urlParams = paramsFromURL({linkToSplit: CUSTOMIZATIONREQUEST_LINK + "listing/"})


        // @ts-ignore
        const limit = Number(urlParams.paramId1)
        let totalRecords = limit;
        let pagiCount = 1
        while (totalRecords < Number(Atom.totalRecords)) {
            // console.log('totalRecords % limit', totalRecords % limit, totalRecords, limit)
            if (totalRecords % limit === 0) {
                ++pagiCount
            }
            totalRecords = totalRecords + limit
        }

        // console.log('pagiCount', pagiCount, limit, totalRecords, Atom.totalRecords, urlParams.paramId1)
        return (<Grid container direction={"row"} justifyContent={"right"}><Card sx={{py: 1}}>

                <Pagination onChange={(e, page) => {

                    // console.log(urlParams)

                    const offset = limit * --page
                    // @ts-ignore
                    navigate(getDataListingURL(offset), {replace: true})
                    // @ts-ignore
                    APICallDataListing({setLoading, setAtom, is_ardb: isARDBCusReqTabActive(cusReqTabIndex)});
                }

                } count={pagiCount}
                />
            </Card>
            </Grid>);
    }, [Atom.totalRecords]);
}
