import {Divider, Grid, TextField, Typography} from "@mui/material";
import {
  currentDate,
  cusReqStateStatusListAtom,
  ErrorLabelAtom,
  formatDate,
  isEmptyObject,
  isObjectCus,
  StakeholderStatusArr,
  SubmitErrorAlertAtom,
  useRecoilState
} from "../../../../Heplers";
import React, {useEffect, useMemo} from "react";
import {CusReqDropdown, defTextFieldOnChange} from "..";
import {getCookie} from "../../../../../Services/Cookies";

export const ScardbBranchInputs = ({ formAtom, md, readOnly }) => {

  const [Atom, setAtom] = useRecoilState(formAtom);
  // forCheckingInputErrorLabelOnlyAfterSubmit
  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);

  const defTextFieldOnChangeComParams = {
    setAtom, SubmitErrorAlert, setSubmitErrorAlert
  }

  useEffect(() => {
    // Setting Default Value
    // console.log(Atom)
    // For Update Form
    if (!isEmptyObject(Atom)) {
      typeof Atom.scardb_branch_inputs === 'string' && defTextFieldOnChange(Atom.scardb_branch_inputs, "scardb_branch_inputs", defTextFieldOnChangeComParams);

      typeof Atom.scardb_branch_date === 'number' && defTextFieldOnChange(formatDate(Atom.scardb_branch_date, 'db-yyyy-mm-dd'), "scardb_branch_date", defTextFieldOnChangeComParams);
    }
  }, []);

  if(getCookie("userRole").replace(/_/g, " ").toUpperCase() === "SCARDB BRANCH"){
    readOnly = false;
  }

  return useMemo(() => {
    return (

      <Grid item spacing={2} xs={12} md={md} container direction={'column'}>

        <Grid item>
          <Divider textAlign="left" sx={{ width: "50%", my: 2 }}>
            <Typography className={'greenText'} fontSize={13} fontWeight="700">SCARDB Branch</Typography>
          </Divider>
          <TextField
            label="Date"
            variant="outlined"
            type="date"
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? formatDate(Atom.scardb_branch_date, 'db-yyyy-mm-dd') : null}
            fullWidth

            InputProps={{inputProps: { max: currentDate } }}
            InputLabelProps={{
              shrink: true,
            }}
            onChange={(e) => readOnly ? null :defTextFieldOnChange(e.target.value, "scardb_branch_date", defTextFieldOnChangeComParams)}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
        </Grid>

        <Grid item>
          <CusReqDropdown
            // @ts-ignore
            formDataAtom={formAtom}
            listDataAtom={cusReqStateStatusListAtom}
            ddLabel="Status"
            dropdownName={"scardb_branch_status"}
            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? (Atom.scardb_branch_status === null ? Atom.scardb_branch_status : Atom.scardb_branch_status) : null}
            optData={StakeholderStatusArr}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
        </Grid>

        <Grid item>
          <TextField
            label="Remarks"
            multiline
            variant="outlined"
            rows={4}
            fullWidth
            InputLabelProps={{
              shrink: true,
            }}
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.scardb_branch_inputs : null}
            onChange={(e) => readOnly ? null :defTextFieldOnChange(e.target.value, "scardb_branch_inputs", defTextFieldOnChangeComParams)}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}

          />
        </Grid>
      </Grid>


    );
  }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
