import {Box, Divider, Grid, Paper, Typography} from "@mui/material";
import CssBaseline from "@mui/material/CssBaseline";
import Toolbar from "@mui/material/Toolbar";
import React, {useEffect, useMemo} from "react";
import DrawerComp from "../../../Components/Drawer/drawer";
import MainHeader from "../../../Components/Header/MainHeader";
import {
  BRFUploadFile,
  CPMUInputs,
  HeaderMasterComp,
  HOInputs,
  InputsFirstRowMasterData,
  InputsSecondRowMasterData,
  InputsThirdRowMasterData,
  MasterDataSubmit,
  NLPSVInputs,
  PACSInputs,
  PageLoadingElem,
  ROInputs,
  SIInputs,
  SPMUInputs,
  StateInputs
} from "./Components";
import {
  cusReqMasterDataAtom, CUSTOMIZATIONREQUEST_LINK,
  ErrorLabelAtom,
  invalidURLAlert, isARDBCusReqTabActive,
  NAWarningLabel, overViewTabAtom,
  pageLoadingAtom,
  paramsFromURL,
  SubmitErrorAlertAtom,
  useRecoilState, useRecoilValue
} from "../../Heplers";
import axiosInstance from "../../../Services/AxiosInstance";

import {useNavigate} from "react-router-dom";
import {SLIMCInputs} from "./Components/PreparationForm/SLIMCInputs";
import {StCBInputs} from "./Components/PreparationForm/StCBInputs";
import {getCookie} from "../../../Services/Cookies";
import {ScardbBranchInputs} from "./Components/PreparationForm/ScardbBranchInputs";
import {PcardbBranchInputs} from "./Components/PreparationForm/PcardbBranchInputs";
import {PcardbHOInputs} from "./Components/PreparationForm/PcardbHOInputs";

export default function CustomizationRequestEntryForm() {

  const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
  const navigate = useNavigate();

  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);
  const APICall = async (reqData) => {
    setPageLoading(true);
    axiosInstance({
      method: "post",
      url: "fetchCUIPreparation_CusReq",
      data: reqData,
    }).then(function (response) {
      // console.log('Data =>', response.data[0]);
      if (response.data[0] === null) {
        return invalidURLAlert(`CUI: ${reqData.cui}`, "Invalid Customization Unique Identification Number")
      } else {
        setPageLoading(false)
        setAtom(response.data[0])
      }

    })
      .catch(function (error) {
        setPageLoading(false)
        console.error(error);
      });

  };

  const URLParams = paramsFromURL({
    linkToSplit: CUSTOMIZATIONREQUEST_LINK + "/",
  })

  const [PageLoading, setPageLoading] = useRecoilState(pageLoadingAtom);
  useEffect(() => {
    window.scrollTo({
      top: 0,
      left: 0,
      behavior: "smooth",
    });




    // console.log('Listing', URLParams)
    if (URLParams.paramId !== undefined && URLParams.paramId != "") {
      //For Update Form 

      // @ts-ignore
      // if (isNaN(URLParams.paramId)) {
      if (URLParams.paramId.length < 6) {
        invalidURLAlert(`CUI: ${URLParams.paramId}`, "Invalid Customization Unique Identification Number")
      } else {
        APICall({ cui: URLParams.paramId });
      }
    } else {
      //For New Form 
      setPageLoading(false)
    }
    return () => {
      // Clearing Page Used Variables

      // @ts-ignore
      setAtom({})
      setPageLoading(false)

      setSubmitErrorAlert(false);
      setErrorLabel(false);
    };

  }, []);

  // console.log("getCookie(\"userRole\")", getCookie("userRole"))
  const readOnly = (getCookie("userRole") !== "SPMU" && getCookie("userRole") !== "CPMU");

  // TODO:STAKESHOLDER NAMES
  // PACS TABS #### - ARDB TABS #### --------
  // PACS           - SCARDB SU
  // SI             -
  // StCB           - SCARDB HO
  // State          -
  // SLIMC          -
  // SPMU           -
  // RO             -
  // CPMU           -
  // NLPSV          - NUSV
  // HO             -
  // MOC            -
  // NLPSV          -
  //                - SCARDB BRANCH
  //                - PCARDB BRANCH
  //                - PCARDB HO


  const cusReqTabIndex = useRecoilValue(overViewTabAtom);
  const renderMainContent = () => {
    return <>
      <HeaderMasterComp URLParams={URLParams} />
      <Paper elevation={2} sx={{ mb: 4, mt: 1 }}>

        <Grid p={2} container>
          <InputsFirstRowMasterData readOnly={readOnly} />

          <InputsSecondRowMasterData readOnly={readOnly} />

          <InputsThirdRowMasterData readOnly={readOnly} />

          {/* Added with Third Row Showstopper Audit and Dayend */}
          {/* <InputsFourthRowMasterData formAtom={cusReqMasterDataAtom} /> */}

          {/*TODO: MULTI DROPDOWN*/}
          {/*<MultiProductDropdown />*/}

          <Grid direction={"column"} container mt={1}>
            {!readOnly && <BRFUploadFile formAtom={cusReqMasterDataAtom} />}
          </Grid>

          <Grid item xs={12} mt={4}>
            <Divider textAlign="left">
              <Typography className={'greenText'} fontSize={14} fontWeight="bold">Stakeholder Inputs</Typography>
            </Divider>

            {NAWarningLabel()}
          </Grid>

          <Grid container spacing={2} direction={"row"}>
            <PACSInputs formAtom={cusReqMasterDataAtom} readOnly={readOnly}/>

            <SIInputs formAtom={cusReqMasterDataAtom} md={4}  readOnly={readOnly}/>

            <StCBInputs formAtom={cusReqMasterDataAtom} md={4}  readOnly={readOnly}/>
          </Grid>

          <Grid container spacing={2} direction={"row"}>
            <StateInputs formAtom={cusReqMasterDataAtom} md={4}  readOnly={readOnly}/>

            <SPMUInputs formAtom={cusReqMasterDataAtom} md={4}  readOnly={readOnly}/>

            <ROInputs formAtom={cusReqMasterDataAtom} md={4}  readOnly={readOnly}/>

          </Grid>


          {/*Only ARDB Stakeholders*/}
          {isARDBCusReqTabActive(cusReqTabIndex) === "Yes" && <Grid container spacing={2} direction={"row"}>
            <ScardbBranchInputs formAtom={cusReqMasterDataAtom} md={4} readOnly={readOnly}/>

            <PcardbBranchInputs formAtom={cusReqMasterDataAtom} md={4} readOnly={readOnly}/>

            <PcardbHOInputs formAtom={cusReqMasterDataAtom} md={4} readOnly={readOnly}/>

          </Grid>}


          <Grid container spacing={2} direction={"row"}>
            <SLIMCInputs formAtom={cusReqMasterDataAtom} md={4}  readOnly={readOnly}/>

            <CPMUInputs formAtom={cusReqMasterDataAtom} md={4}  readOnly={readOnly}/>

            <NLPSVInputs formAtom={cusReqMasterDataAtom} md={4} edodInput={false} edorfInput={true} plannedGoLive={false} readOnly={readOnly}/>
          </Grid>

          <Grid container spacing={2} direction={"row"}>

            <Grid item spacing={2} xs={12} md={4} container direction={'column'}></Grid>
            <Grid item spacing={2} xs={12} md={4} container direction={'column'}></Grid>
            <HOInputs formAtom={cusReqMasterDataAtom} md={4} readOnly={readOnly} />
          </Grid>

          <MasterDataSubmit />
        </Grid>
      </Paper></>
  }

  return useMemo(() => {
    return (
      <div>
        <style>
          {`
                    .css-10hburv-MuiTypography-root{
                      font-size:11px !important;
                      font-family: Poppins 
                    }
                    .css-yb0lig{
                      font-size:12px !important
                    }
                    `}
        </style>

        <Box sx={{ display: "flex", mt: 5 }}>
          <CssBaseline />
          {/* @ts-ignore*/}
          <MainHeader />
          <DrawerComp listName={"Customization Request"} />
          <Box
            component="main"
            sx={{
              flexGrow: 1,
              backgroundColor: "#f4faf8",
              px: 1,
              // pr: 4,
              // @ts-ignore
              // height: isEmptyObject(URLParams) ? "100vh" : "auto",
            }}
          >
            <Toolbar />

            {/*<UnderDevAlert />*/}

            <PageLoadingElem />

            {!PageLoading && renderMainContent()}


          </Box>
        </Box>
      </div>
    )
  }, [PageLoading]);
}
