import {Grid, TextField} from "@mui/material";
import {
    cusReqMasterDataAtom,
    SubmitErrorAlertAtom,
    useRecoilState,
    renderInputErrorLabel,
    ErrorLabelAtom,
    cusReqDeviationListAtom,
    cusReqShowstopperListAtom,
    yesNoArr,
    isEmptyObject,
    isObjectCus,
    invalidURLAlert,
    cusReqAssignedToListAtom,
    stakeholderArr,
    integrationType,
    cusReqIntegrationTypeListAtom,
    yesNoMBArr,
    cusReqARDBPACSListAtom,
    isARDBCusReqTabActive, useRecoilValue, stakeholderArrARDB, overViewTabAtom,
} from "../../../../Heplers";
import React, {useEffect, useMemo} from "react";
import {CusReqDropdown, defTextFieldOnChange, InputsFourthRowMasterData} from "..";

export const InputsThirdRowMasterData = ({readOnly}) => {
    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);

    const defTextFieldOnChangeComParams = {
        setAtom,
        SubmitErrorAlert,
        setSubmitErrorAlert,
    };

    useEffect(() => {
        // Setting Default Value
        // console.log(Atom)
        // For Update Form
        if (!isEmptyObject(Atom)) {
            defTextFieldOnChange(
                Atom.showstopper_pacs_no,
                "showstopper_pacs_no",
                defTextFieldOnChangeComParams
            );
        }
    }, []);


    const cusReqTabIndex = useRecoilValue(overViewTabAtom);

    return useMemo(() => {

        // console.log(isObjectCus(Atom) && !isEmptyObject(Atom),Atom, isObjectCus(Atom), !isEmptyObject(Atom));

        console.log(Atom)

        return (
            <Grid spacing={2} container mt={0.3}>

                <Grid item xs={12} md={4}>
                    <CusReqDropdown
                        // @ts-ignore
                        formDataAtom={cusReqMasterDataAtom}
                        listDataAtom={cusReqAssignedToListAtom}
                        ddLabel="Assigned To"
                        dropdownName={"assigned_to"}
                        required
                        optData={isARDBCusReqTabActive(cusReqTabIndex) === 'Yes' ? stakeholderArrARDB : stakeholderArr}
                        defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.assigned_to : null}

                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                    {renderInputErrorLabel(ErrorLabel, Atom.assigned_to, "Required")}
                </Grid>


                {/*// New TABS logic introduced so fixing the parameter data*/}
                {/*<Grid item xs={12} md={4}>*/}
                {/*    <CusReqDropdown*/}
                {/*        // @ts-ignore*/}
                {/*        formDataAtom={cusReqMasterDataAtom}*/}
                {/*        listDataAtom={cusReqARDBPACSListAtom}*/}
                {/*        ddLabel="Is this for ARDB"*/}
                {/*        dropdownName={"ardb_pacs"}*/}
                {/*        required*/}
                {/*        optData={yesNoArr}*/}
                {/*        defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.ardb_pacs : null}*/}

                {/*        disabled={readOnly}*/}
                {/*        aria-readonly={readOnly}*/}
                {/*        readOnly={readOnly}*/}
                {/*        className={`${readOnly && 'readonlyStyle'}`}*/}
                {/*    />*/}
                {/*    {renderInputErrorLabel(ErrorLabel, Atom.ardb_pacs, "Required")}*/}
                {/*</Grid>*/}


                <Grid item xs={12} md={4}>
                    <CusReqDropdown
                        // @ts-ignore
                        formDataAtom={cusReqMasterDataAtom}
                        listDataAtom={cusReqDeviationListAtom}
                        ddLabel="Is deviated from regulation"
                        dropdownName={"deviation"}
                        required
                        optData={yesNoMBArr}
                        defVal={
                            isObjectCus(Atom) && !isEmptyObject(Atom) ? Atom.deviation : null
                        }

                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                    {renderInputErrorLabel(ErrorLabel, Atom.deviation, "Required")}
                </Grid>

                <Grid item xs={12} md={4}>
                    <CusReqDropdown
                        // @ts-ignore
                        formDataAtom={cusReqMasterDataAtom}
                        listDataAtom={cusReqShowstopperListAtom}
                        ddLabel="Is Showstopper"
                        dropdownName={"showstopper"}
                        required
                        optData={yesNoArr}
                        defVal={
                            isObjectCus(Atom) && !isEmptyObject(Atom)
                                ? Atom.showstopper
                                : null
                        }

                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                    {renderInputErrorLabel(ErrorLabel, Atom.showstopper, "Required")}
                </Grid>

                {Atom.showstopper !== undefined &&
                    Atom.showstopper.id !== undefined &&
                    Atom.showstopper.id == "Yes" && (
                        <Grid item xs={12} md={4}>
                            <TextField
                                label={`No of ${isARDBCusReqTabActive(cusReqTabIndex) === 'Yes'? 'ARDB' : 'PACS'} Impacted if Showstopper`}
                                variant="outlined"
                                fullWidth
                                type="number"
                                id="showstopper_pacs_no"
                                InputLabelProps={{
                                    shrink: true,
                                }}
                                onChange={(e) => {
                                    if (readOnly)
                                        return null


                                    // if (Number(e.target.value) < 1) {
                                    if (isNaN(e.target.value)) {
                                        // invalidURLAlert(
                                        //   "Error Input",
                                        //   "Min value should be 1 or Select Showstopper No",
                                        //   "",
                                        //   false
                                        // );

                                        invalidURLAlert(
                                            "Error Input",
                                            "No of Showstopper PACS should be of number",
                                            "",
                                            false
                                        );

                                        document.getElementById("showstopper_pacs_no").value = 0;
                                        defTextFieldOnChange(
                                            1,
                                            "showstopper_pacs_no",
                                            defTextFieldOnChangeComParams
                                        );
                                    } else {
                                        defTextFieldOnChange(
                                            e.target.value,
                                            "showstopper_pacs_no",
                                            defTextFieldOnChangeComParams
                                        );
                                    }
                                }}
                                // @ts-ignore
                                defaultValue={
                                    isObjectCus(Atom) &&
                                    !isEmptyObject(Atom) &&
                                    !isNaN(Atom.showstopper_pacs_no)
                                        ? Atom.showstopper_pacs_no
                                        : 0
                                }

                                disabled={readOnly}
                                aria-readonly={readOnly}
                                readOnly={readOnly}
                                className={`${readOnly && 'readonlyStyle'}`}
                            />
                        </Grid>
                    )}

                {Atom.showstopper !== undefined &&
                    Atom.showstopper.id !== undefined &&
                    Atom.showstopper.id == "Yes" && (
                        <Grid item xs={12} md={4}>
                            <CusReqDropdown
                                // @ts-ignore
                                formDataAtom={cusReqMasterDataAtom}
                                listDataAtom={cusReqShowstopperListAtom}
                                ddLabel="Is Showstopper For Audit"
                                dropdownName={"showstopper_audit"}
                                optData={yesNoArr}
                                defVal={
                                    isObjectCus(Atom) && !isEmptyObject(Atom) && Atom.showstopper_audit !== undefined
                                        ? Atom.showstopper_audit
                                        : "Yes"
                                }

                                disabled={readOnly}
                                aria-readonly={readOnly}
                                readOnly={readOnly}
                                className={`${readOnly && 'readonlyStyle'}`}

                            />
                        </Grid>
                    )}

                {Atom.showstopper !== undefined &&
                    Atom.showstopper.id !== undefined &&
                    Atom.showstopper.id == "Yes" && (
                        <Grid item xs={12} md={4}>
                            <CusReqDropdown
                                // @ts-ignore
                                formDataAtom={cusReqMasterDataAtom}
                                listDataAtom={cusReqShowstopperListAtom}
                                ddLabel="Is Showstopper For Dayend"
                                dropdownName={"showstopper_dayend"}
                                optData={yesNoArr}
                                defVal={
                                    isObjectCus(Atom) && !isEmptyObject(Atom) && Atom.showstopper_dayend !== undefined
                                        ? Atom.showstopper_dayend
                                        : "Yes"
                                }

                                disabled={readOnly}
                                aria-readonly={readOnly}
                                readOnly={readOnly}
                                className={`${readOnly && 'readonlyStyle'}`}
                            />
                        </Grid>
                    )}


                {Atom.bucket !== undefined &&
                    Atom.bucket.id !== undefined &&
                    (Atom.bucket.id == 2) && (
                        <Grid item xs={12} md={4}>
                            <CusReqDropdown
                                // @ts-ignore
                                formDataAtom={cusReqMasterDataAtom}
                                listDataAtom={cusReqIntegrationTypeListAtom}
                                ddLabel="Integration Type"
                                dropdownName={"integration_type"}
                                optData={integrationType}
                                defVal={
                                    isObjectCus(Atom) && !isEmptyObject(Atom) && Atom.integration_type !== undefined
                                        ? Atom.integration_type
                                        : "NA"
                                }

                                disabled={readOnly}
                                aria-readonly={readOnly}
                                readOnly={readOnly}
                                className={`${readOnly && 'readonlyStyle'}`}
                            />
                        </Grid>
                    )}

                {Atom.bucket !== undefined &&
                    Atom.bucket.id !== undefined &&
                    (Atom.bucket.id == 2 || Atom.bucket.id == 3) && (
                        <Grid item xs={12} md={4}>
                            <TextField
                                label="Name of the portal to be integrated"
                                variant="outlined"
                                fullWidth
                                id="portal_name_int"
                                InputLabelProps={{
                                    shrink: true,
                                }}
                                onChange={(e) => readOnly ? null : defTextFieldOnChange(
                                    e.target.value,
                                    "portal_name_int",
                                    defTextFieldOnChangeComParams
                                )}

                                // @ts-ignore
                                defaultValue={
                                    isObjectCus(Atom) &&
                                    !isEmptyObject(Atom) &&
                                    Atom.portal_name_int !== undefined
                                        ? Atom.portal_name_int
                                        : null
                                }

                                disabled={readOnly}
                                aria-readonly={readOnly}
                                readOnly={readOnly}
                                className={`${readOnly && 'readonlyStyle'}`}
                            />
                        </Grid>
                    )}

            </Grid>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
