import {Grid, Paper, Typography} from "@mui/material";
import {
    cusReqMasterDataAtom, cusReqShowstopperListAtom,
    cusReqStateListAtom,
    ErrorLabelAtom,
    isEmptyObject,
    isObjectCus,
    renderInputErrorLabel,
    SubmitErrorAlertAtom,
    useRecoilState, yesNoArr
} from "../../../../Heplers";
import React, {useMemo} from "react";
import {CusReqDropdown, RadioYesNo} from "..";
import {CardGreenHeader} from "../../../CustomizationRequest/Components/CardGreenHeader";

export const Knowledge_Training = ({readOnly}) => {

    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);


    return useMemo(() => {
        return (
            <Paper elevation={2} sx={{mb: 2}} className={"greenBorder"}>
                <CardGreenHeader text={"Knowledge & Training"}/>

                <Grid p={2} spacing={2} container>

                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"kno_train1"} ddLabel={"Does he know the software"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"kno_train2"} ddLabel={"Is the guide book / User manual available for PACS personnel"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"kno_train3"} ddLabel={"Did he attend any trainings"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"kno_train4"} ddLabel={"Does he need additional training, Offline? Online?"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"kno_train5"} ddLabel={"Can he navigate through a learning management system?"} />
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <RadioYesNo radioName={"kno_train6"} ddLabel={"Can/Did PACS refer to YouTube videos to learn operating ePACS"} />
                    </Grid>

                </Grid>
            </Paper>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
