import {Button, Divider, Grid, Paper, TextField} from "@mui/material";

import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import {
    currentDate,
    currentDatePlus14,
    cusReqAddViaListAtom,
    cusReqMasterDataAtom,
    ErrorLabelAtom,
    formatDate,
    isEmptyObject,
    isObjectCus,
    renderInputErrorLabel,
    SubmitErrorAlertAtom,
    useRecoilState
} from "../../../../Heplers";
import React, {useEffect, useMemo} from "react";
import {CusReqDropdown} from "..";
import {CardGreenHeader} from "../../../CustomizationRequest/Components/CardGreenHeader";
import {BRFUploadFile, defTextFieldOnChange} from "../../../CustomizationRequest/Components";

const vertiInputsPadding = {
    pb: {xs: 2},
};

function createData(name, calories, fat, carbs, protein) {
    return { name, calories, fat, carbs, protein };
}

const rows = [
    createData('1', "Rajiv Sharma", "PwC", "Sr. Con", 4.0),
    createData('2', "John Doe", "RO, NABARD", "DDM", 4.3),
    createData('3', "Abishek Rao", "SI, West Bengal", "PM", 6.0),
];

export const PlanInputs = ({readOnly}) => {

    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);

    const defTextFieldOnChangeComParams = {
        setAtom, SubmitErrorAlert, setSubmitErrorAlert
    }

    useEffect(() => {
        // Setting Default Value
        // console.log(Atom)
        // For Update Form
        if (!isEmptyObject(Atom)) {
            // console.log("Sett params", Atom.edor, formatDate(Atom.edor, 'db-yyyy-mm-dd'))
            defTextFieldOnChange(formatDate(Atom.dor, 'db-yyyy-mm-dd'), "dor", defTextFieldOnChangeComParams);
            defTextFieldOnChange(formatDate(Atom.edor, 'db-yyyy-mm-dd'), 'edor', defTextFieldOnChangeComParams);
            defTextFieldOnChange(Atom.descrip, "descrip", defTextFieldOnChangeComParams);
            defTextFieldOnChange(Atom.addto, "addto", defTextFieldOnChangeComParams);
        } else {
            // console.log(" New Form Default Set like dates");

            defTextFieldOnChange(currentDate, "dor", defTextFieldOnChangeComParams);
            defTextFieldOnChange(currentDatePlus14, "edor", defTextFieldOnChangeComParams);
        }
    }, []);

    return useMemo(() => {
        return (
            <Paper elevation={2} sx={{mb: 2}} className={"greenBorder"}>
                <CardGreenHeader text={"Plan Details"}/>

                <Grid container p={2} spacing={2} columns={12}>
                    <Grid item md={3} xs={12}>
                        <Grid item sx={{...vertiInputsPadding, pt: {md: 1}}}>
                            <TextField
                                label="Date of Visit"
                                variant="outlined"
                                type="date"
                                defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom) && formatDate(Atom.dor, 'db-yyyy-mm-dd') !== undefined) ? formatDate(Atom.dor, 'db-yyyy-mm-dd') : currentDate}
                                fullWidth
                                required

                                InputProps={{inputProps: {max: currentDate}}}
                                InputLabelProps={{
                                    shrink: true,
                                }}
                                onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "dor", defTextFieldOnChangeComParams)
                                }

                                disabled={readOnly}
                                aria-readonly={readOnly}
                                readOnly={readOnly}
                                className={`${readOnly && 'readonlyStyle'}`}


                            />
                            {renderInputErrorLabel(ErrorLabel, Atom.dor, "Required")}
                        </Grid>


                        <style>
                            {`
                              .css-8ewcdo-MuiInputBase-root-MuiOutlinedInput-root{
                                padding: 19.5px 14px !important
                              }
                            `}
                        </style>
                        <TextField
                            label="Objective of Visit"
                            multiline
                            variant="outlined"
                            rows={7}
                            fullWidth
                            required
                            InputLabelProps={{
                                shrink: true,
                            }}
                            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.descrip : null}
                            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "descrip", defTextFieldOnChangeComParams)}

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}
                        />
                        {renderInputErrorLabel(ErrorLabel, Atom.descrip, "Required")}

                    </Grid>


                    <Divider orientation="vertical" flexItem sx={{ml: 2, mt:3, borderRightWidth: "thin", borderColor: "#065036", display: { xs: 'none', md: "block" }}} />

                    <Grid item md={12} xs={12} sx={{display: { xs: 'block', md: "none" }}}><Divider sx={{borderBottomWidth: "thin", borderColor: "#065036"}} /></Grid>


                    <Grid item md={2.9} xs={12}>
                        <Grid item sx={{...vertiInputsPadding, pt: {md: 1}}}>
                            <TextField
                                label={`Personnel Visited`}
                                variant="outlined"
                                fullWidth
                                InputLabelProps={{shrink: true}}
                                defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.addto : null}
                                onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "addto", defTextFieldOnChangeComParams)}
                                required

                                disabled={readOnly}
                                aria-readonly={readOnly}
                                readOnly={readOnly}
                                className={`${readOnly && 'readonlyStyle'}`}
                            />
                        </Grid>

                        <Grid item sx={{...vertiInputsPadding}}>
                            <CusReqDropdown
                                // @ts-ignore
                                formDataAtom={cusReqMasterDataAtom}
                                listDataAtom={cusReqAddViaListAtom}
                                ddLabel="Designation"
                                dropdownName={"addvia"}
                                fetchMasterDataURL="fetchAddViaMasterData_CusReq"
                                required
                                defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.addvia : null}

                                disabled={readOnly}
                                aria-readonly={readOnly}
                                readOnly={readOnly}
                                className={`${readOnly && 'readonlyStyle'}`}
                            />
                        </Grid>

                        <Grid item sx={{...vertiInputsPadding}}>
                            <CusReqDropdown
                                // @ts-ignore
                                formDataAtom={cusReqMasterDataAtom}
                                listDataAtom={cusReqAddViaListAtom}
                                ddLabel="Department/ Organization"
                                dropdownName={"addvia"}
                                fetchMasterDataURL="fetchAddViaMasterData_CusReq"
                                required
                                defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.addvia : null}

                                disabled={readOnly}
                                aria-readonly={readOnly}
                                readOnly={readOnly}
                                className={`${readOnly && 'readonlyStyle'}`}
                            />
                        </Grid>

                        <Grid item display={"flex"} justifyContent={"flex-end"} sx={{...vertiInputsPadding}}>

                            <Button
                                onClick={() => alert("Added")}
                                sx={{mt: 1, textTransform: 'none'}}
                                variant="outlined"
                                color="success"
                                size={"small"}
                            >
                                Add Personnel
                            </Button>

                        </Grid>

                    </Grid>

                    <Grid item md={5.8} xs={12}>


                        <TableContainer component={Paper}>
                            <Table sx={{ minWidth: 250 }} aria-label="simple table">
                                <TableHead className={"greenBackground"} sx={{  }}>
                                    <TableRow>
                                        <TableCell style={{ width: 20, color: "#fff", padding: "8px" }} align="right">#</TableCell>
                                        <TableCell style={{ color: "#fff", padding: "8px" }}>Personnel Name</TableCell>
                                        <TableCell style={{ color: "#fff", padding: "8px" }}>Dept./ Org.</TableCell>
                                        <TableCell style={{ color: "#fff", padding: "8px" }}>Designation</TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {rows.map((row) => (
                                        <TableRow
                                            key={row.name}
                                            sx={{ '&:last-child td, &:last-child th': { border: 0 } }}
                                        >
                                            <TableCell component="th" scope="row" align="right">
                                                {row.name}
                                            </TableCell>
                                            <TableCell>{row.calories}</TableCell>
                                            <TableCell>{row.fat}</TableCell>
                                            <TableCell>{row.carbs}</TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </TableContainer>


                    </Grid>


                    <Grid direction={"column"} container mt={1} pl={2}>
                        {!readOnly && <BRFUploadFile formAtom={cusReqMasterDataAtom}
                                                     labelText={"Upload Field Order/ Reference Document Here"}
                        />}
                    </Grid>

                </Grid>

            </Paper>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
