import {Divider, Grid, TextField, Typography} from "@mui/material";
import {
  currentDate,
  cusReqPACSStatusListAtom,
  ErrorLabelAtom,
  formatDate,
  isARDBCusReqTabActive,
  isEmptyObject,
  isObjectCus,
  overViewTabAtom,
  StakeholderStatusArr,
  SubmitErrorAlertAtom,
  useRecoilState,
  useRecoilValue
} from "../../../../Heplers";
import React, {useEffect, useMemo} from "react";
import {CusReqDropdown, defTextFieldOnChange} from "..";
import {getCookie} from "../../../../../Services/Cookies";

export const PACSInputs = ({readOnly, formAtom}) => {

  const [Atom, setAtom] = useRecoilState(formAtom);
  // forCheckingInputErrorLabelOnlyAfterSubmit
  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);

  const defTextFieldOnChangeComParams = {
    setAtom, SubmitErrorAlert, setSubmitErrorAlert
  }

  useEffect(() => {
    // Setting Default Value
    // console.log(Atom)
    // For Update Form
    if (!isEmptyObject(Atom)) {
      typeof Atom.pacs_inputs === 'string' && defTextFieldOnChange(Atom.pacs_inputs, "pacs_inputs", defTextFieldOnChangeComParams);
      typeof Atom.pacs_date === 'number' && defTextFieldOnChange(formatDate(Atom.pacs_date, 'db-yyyy-mm-dd'), "pacs_date", defTextFieldOnChangeComParams);
    }
  }, []);

  // PACS - ARDB Common Stakeholder
  if(
      getCookie("userRole").replace(/_/g, " ").toUpperCase() === "PACS" ||
      getCookie("userRole").replace(/_/g, " ").toUpperCase() === "SCARDB SU"
  ){
    readOnly = false;
  }


  const cusReqTabIndex = useRecoilValue(overViewTabAtom);

  return useMemo(() => {

    // console.log('Atom.pacs_inputs', Atom.pacs_inputs);

    return (

      <Grid item spacing={2} xs={12} md={4} container direction={'column'}>

        <Grid item>
          <Divider textAlign="left" sx={{ width: "50%", my: 2 }}>
            <Typography className={'greenText'} fontSize={13} fontWeight="700">{isARDBCusReqTabActive(cusReqTabIndex) ===  "Yes" ? "SCARDB SU" : "PACS"}</Typography>
          </Divider>
          <TextField
            label="Date"
            variant="outlined"
            type="date"
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? formatDate(Atom.pacs_date, 'db-yyyy-mm-dd') : null}
            fullWidth

            InputProps={{inputProps: { max: currentDate } }}
            InputLabelProps={{
              shrink: true,
            }}

            InputProps={{inputProps: { max: currentDate } }}

            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "pacs_date", defTextFieldOnChangeComParams)}

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
        </Grid>

        <Grid item>
          <CusReqDropdown
            // @ts-ignore
            formDataAtom={formAtom}
            listDataAtom={cusReqPACSStatusListAtom}
            ddLabel="Status"
            dropdownName={"pacs_status"}
            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.pacs_status : null}
            optData={StakeholderStatusArr}

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
        </Grid>

        <Grid item>
          <TextField
            label="Remarks"
            multiline
            variant="outlined"
            rows={4}
            fullWidth
            InputLabelProps={{
              shrink: true,
            }}
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.pacs_inputs : null}
            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "pacs_inputs", defTextFieldOnChangeComParams)}

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
        </Grid>
      </Grid>


    );
  }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
