import {Box, Button, Chip, Grid, LinearProgress} from "@mui/material";
import CssBaseline from "@mui/material/CssBaseline";
import Toolbar from "@mui/material/Toolbar";
import React, {useEffect, useMemo} from "react";
import DrawerComp from "../../../Components/Drawer/drawer";
import MainHeader from "../../../Components/Header/MainHeader";
import {
    confirmationWithRemark,
    cusReqCUIMasterDetailsAtom, cusReqDeleteAccessible, CUSTOMIZATIONREQUEST_LINK,
    invalidURLAlert,
    isEmptyObject,
    isObjectCus,
    pageLoadingAtom,
    paramsFromURL, successAndGoBackAlert,
    timelineData,
    URLParamsAtom,
    useRecoilState,
} from "../../Heplers";
import {
    UnderDevAlert,
    TimelineComp,
    CusReqDetailsCard,
    PageLoadingElem,
} from "./Components";
import {isObject} from "@mui/x-data-grid/internals";
import axiosInstance from "../../../Services/AxiosInstance";
import Swal from "sweetalert2";
import {getCookie} from "../../../Services/Cookies";

export default function CusReqTimline() {
    const [URLParams, setURLParams] = useRecoilState(URLParamsAtom);

    const [Atom, setAtom] = useRecoilState(cusReqCUIMasterDetailsAtom);
    const [PageLoading, setPageLoading] = useRecoilState(pageLoadingAtom);

    const APICall = async (reqData) => {
        setPageLoading(true);
        axiosInstance({
            method: "post",
            url: "fetchCUIMasterData",
            data: reqData,
        })
            .then(function (response) {
                // console.log('fetchCUIMasterData Data =>', response.data);
                if (!isObject(response.data) || isEmptyObject(response.data)) {
                    invalidURLAlert(
                        `CUI: ${reqData.cui}`,
                        "Invalid Customization Unique Identification Number"
                    );
                } else {
                    setAtom({
                        pre: JSON.parse(response.data.pre),
                        brd: JSON.parse(response.data.brd),
                        dev: JSON.parse(response.data.dev),
                        uat: JSON.parse(response.data.uat),
                    });
                    setPageLoading(false);
                }

            })
            .catch(function (error) {
                setPageLoading(false);
                console.error(error);
            });
    };

    useEffect(() => {
        window.scrollTo({
            top: 0,
            left: 0,
            behavior: "smooth",
        });

        const urlParams = paramsFromURL({
            linkToSplit: `${CUSTOMIZATIONREQUEST_LINK}timeline/`,
        });
        setURLParams(urlParams);


        if (urlParams.paramId !== undefined && urlParams.paramId != "") {
            // @ts-ignore
            // if (isNaN(URLParams.paramId)) {
            if (urlParams.paramId.length < 6) {
                invalidURLAlert(
                    `CUI: ${urlParams.paramId}`,
                    "Invalid Customization Unique Identification Number"
                );
            } else {
                APICall({cui: urlParams.paramId});
            }
        }
        return () => {
            setURLParams({});
        };
    }, []);

    const pushBackAPI = (v) => {
        // console.log("pushBackAPI")
        Swal.fire({
            title: "Processing ...",
            html: "Please wait processing your push-back/ reopen request",
            timerProgressBar: true,
            didOpen: () => {
                Swal.showLoading();
            }
        })


        axiosInstance({
            method: "post",
            url: "cusReqReopen",
            data: {
                cui: URLParams.paramId, remark: v, userid: Number(getCookie("resourceId"))
            },
        })
            .then(function (response) {
                console.log('cusReqReopen =>', response);
                Swal.close();

                Number(response.data) === 1 && successAndGoBackAlert("Success", "Request successfully Pushed-back/ Reopened.", true);
            })
            .catch(function (error) {
                Swal.close();
                console.error(error);
            });


    };


    const deleteRequestAPI = (v) => {
        Swal.fire({
            title: `Are you sure you want to delete CUI: ${URLParams.paramId} request ?`,
            // showDenyButton: true,
            showCancelButton: true,
            confirmButtonText: "Yes, delete it",
            // denyButtonText: `Don't save`
        }).then((result) => {
            /* Read more about isConfirmed, isDenied below */
            if (result.isConfirmed) {
                Swal.fire({
                    title: "Processing ...",
                    html: "Please wait processing your deletion request",
                    timerProgressBar: true,
                    didOpen: () => {
                        Swal.showLoading();
                    }
                })

                axiosInstance({
                    method: "post",
                    url: "cusReqInactiveStatus",
                    data: {
                        cui: URLParams.paramId, userid: Number(getCookie("resourceId"))
                    },
                })
                    .then(function (response) {
                        console.log('cusReqInactiveStatus =>', response);
                        Swal.close();

                        response.data === "Success" && successAndGoBackAlert("Success", "Request successfully deleted.", true);
                    })
                    .catch(function (error) {
                        Swal.close();
                        console.error(error);
                    });
            }
            // else if (result.isDenied) {
            //     Swal.fire("Changes are not saved", "", "info");
            // }
        });
    }

    const renderMainContent = () => {

        // console.log('Push Back test',Atom)
        return (
            <Grid container spacing={1}>
                <Grid item md={4} xs={12} marginTop={2}>
                    <CusReqDetailsCard/>
                </Grid>
                <Grid item md={8} xs={12} marginTop={2}>

                    <Grid textAlign={"right"}>
                        {
                            (
                                (getCookie("userRole") === "CPMU" || Number(getCookie("resourceId")) === 44)

                                //     This is commented because we are now reopening on Prep stage not BRF Stage
                                // && (Atom.brd !== undefined && Atom.brd !== null && Atom.brd.inputs_closed !== undefined && Atom.brd.inputs_closed === 'Yes')

                                && (Atom.pre !== undefined && Atom.pre !== null && Atom.pre.inputs_closed !== undefined && Atom.pre.inputs_closed === 'Yes')

                            ) && (
                                <Button
                                    onClick={() => confirmationWithRemark(URLParams.paramId, pushBackAPI)}
                                    sx={{mt: 1, mr: 1, textTransform: "none"}}
                                    variant="contained"
                                    color="info"
                                >
                                    Push Back/ Reopen
                                </Button>
                            )
                        }

                        {
                            cusReqDeleteAccessible() && (
                                <Button
                                    onClick={() => deleteRequestAPI()}
                                    sx={{mt: 1, mr: 1, textTransform: "none"}}
                                    variant="contained"
                                    color="error"
                                >
                                    Delete
                                </Button>
                            )
                        }
                    </Grid>


                    {<TimelineComp data={timelineData}/>}
                </Grid>
            </Grid>
        );
    };

    return useMemo(() => {
        return (
            <div>
                <style>
                    {`
            .css-10hburv-MuiTypography-root{
              font-size:11px !important;
              font-family: Poppins 
            }
            .css-yb0lig{
              font-size:12px !important
            }
          `}
                </style>

                <Box sx={{display: "flex", mt: 5}}>
                    <CssBaseline/>
                    {/* @ts-ignore*/}
                    <MainHeader/>
                    <DrawerComp listName={"Customization Request"}/>
                    <Box
                        component="main"
                        sx={{
                            flexGrow: 1,
                            backgroundColor: "#f4faf8",
                            px: 1,
                            // pr: 4,
                            // @ts-ignore
                            // height: isEmptyObject(URLParams) ? "100vh" : "auto",
                        }}
                    >
                        <Toolbar/>

                        {/*<UnderDevAlert />*/}

                        <PageLoadingElem/>

                        {!PageLoading && renderMainContent()}
                    </Box>
                </Box>
            </div>
        );
    }, [PageLoading]);
}
