import React, { useState, useEffect } from 'react';
import Box from "@mui/material/Box";
import CssBaseline from "@mui/material/CssBaseline";
import DrawerComp from "../Components/Drawer/drawer";
import Header from "../Components/Header/MainHeader";
import axiosInstance from "../Services/AxiosInstance";
import {
  CircularProgress,
  Table,
  TableHead,
  TableBody,
  TableCell,
  TableContainer,
  TableRow,
  TextField,
  Pagination,
  Autocomplete
} from "@mui/material";
import moment from "moment";
import {getCookie} from "../Services/Cookies";

export const UserAuditLogs = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [emailFilter, setEmailFilter] = useState("");
  const [roleFilter, setRoleFilter] = useState("");
  const [emailOptions, setEmailOptions] = useState([]); // For dropdown
  const [selectedUserId, setSelectedUserId] = useState(""); // For API param
  const recordsPerPage = 10;

  const roles = [
    "PACS",
    "SI",
    "State",
    "StCB",
    "SLIMC",
    "SPMU",
    "RO",
    "CPMU",
    "NLPSV",
    "HO",
    "MoC",
    "CLIENT",
  ];


  useEffect(() => {
    window.scrollTo({
      top: 0,
      left: 0,
      behavior: "smooth",
    });
  }, []);

  useEffect(() => {
    const fetchEmails = async () => {
      try {
        const response = await axiosInstance.post("/emails");
        // Assuming response.data is an array of { userId, email }
        response && setEmailOptions(response.data);
        response && setTotalPages(Math.ceil(response.data.totalRecords / recordsPerPage));

      } catch (error) {
        console.error("Error fetching emails:", error);
      }
    };
    fetchEmails();
  }, []);

  // When email is selected, set the associated userId
  const handleEmailChange = (event, value) => {
    setRoleFilter("");
    setEmailFilter(value ? value.email : "");
    setSelectedUserId(value ? value.userId : "");
    setPage(0);
  };


  useEffect(() => {
    fetchData(page, roleFilter, selectedUserId, recordsPerPage);
  }, [page, emailFilter, roleFilter, selectedUserId, recordsPerPage]);


  const fetchData = async (pageNumber, role, userId, recordsPerPage) => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      params.append("page", pageNumber);
      if (role) params.append("userRole", role);
      if (userId) params.append("userId", userId);
      if (recordsPerPage) params.append("size", recordsPerPage);

      params.append("sort", ["id,desc"]);

      const response = await axiosInstance.post(`/login-audit?${params}`);
      setData(response.data.data); // `response.data.data` for the records array
      setTotalPages(Math.ceil(response.data.totalRecords / recordsPerPage)); // Calculate total pages
    } catch (error) {
      console.error("Error fetching data:", error);
    } finally {
      setLoading(false);
    }
  };

  const formatTimestamp = (timestamp) => {
    if (!timestamp) return "Online/ Session Expired";
    const date = moment(timestamp);
    if (!date.isValid()) return timestamp; // fallback if invalid
    return `${date.format("hh:mm A")} ${date.format("DD/MM/YYYY")}`;
  };



  return (getCookie("userRole") !== "CPMU" && Number(getCookie('resourceId')) !== 44) ? null : (
    <div
      style={{
        overflowX: "hidden",
        fontFamily: "Poppins",
        overflowY: "hidden",
      }}
    >
      <style>
        {`
              .css-10hburv-MuiTypography-root{
                  font-size:11px !important;
                  font-family: Poppins 
              }
              .css-yb0lig{
                font-size:12px !important
              }
              `}
      </style>
      <Box sx={{ display: "flex" }}>
        <CssBaseline />
        <Header />
        <DrawerComp listName={"User Login Audit"} />
        <Box
          component="main"
          sx={{ flexGrow: 1, p: { xs: 0, md: 3 }, backgroundColor: "#f4faf8", marginTop: "90px", }}
        >
          <Box sx={{ display: "flex", gap: 2, mb: 2, mt: 3 }}>
            <Autocomplete
              options={emailOptions}
              getOptionLabel={(option) => option.email || ""}
              value={emailOptions.find(opt => opt.email === emailFilter) || null}
              onChange={handleEmailChange}
              renderInput={(params) => (
                <TextField
                  {...params}
                  label="Filter by Email"
                  variant="outlined"
                  size="small"
                  sx={{ minWidth: 250 }}
                />
              )}
              isOptionEqualToValue={(option, value) => option.email === value.email}
              clearOnEscape
            />
            <Autocomplete
              options={roles}
              getOptionLabel={(option) => option}
              value={roleFilter || ""}
              onChange={(event, newValue) => {
                setRoleFilter(newValue || "");
                setEmailFilter("");
                setSelectedUserId("");
                setPage(0);
              }}
              renderInput={(params) => (
                <TextField
                  {...params}
                  label="Filter by Role"
                  variant="outlined"
                  size="small"
                  sx={{ minWidth: 150 }}
                />
              )}
              clearOnEscape
              freeSolo // allows typing custom value if needed
            />
          </Box>
          {loading ? (
            <Box sx={{ display: "flex", justifyContent: "center", mt: 5 }}>
              <CircularProgress />
            </Box>
          ) : (
            <>
              <TableContainer>
                <Table>
                  <TableHead
                    sx={{
                      backgroundColor: " rgb(234, 234, 234)", // Light background for header
                    }}>
                    <TableRow>
                      <TableCell sx={{ fontWeight: "bold" }}>ID</TableCell>
                      {/*<TableCell sx={{ fontWeight: "bold" }}>User ID</TableCell>*/}
                      <TableCell sx={{ fontWeight: "bold" }}>User Name</TableCell>
                      <TableCell sx={{ fontWeight: "bold" }}>Email</TableCell>
                      <TableCell sx={{ fontWeight: "bold" }}>User Role</TableCell>
                      <TableCell sx={{ fontWeight: "bold" }}>Login Timestamp</TableCell>
                      <TableCell sx={{ fontWeight: "bold" }}>Logout Timestamp</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {data.map((row,index) => (
                      <TableRow key={row.id}>
                        {/*<TableCell>{index+1}</TableCell>*/}

                        <TableCell>{(index+1) + (page * recordsPerPage)}</TableCell>
                        {/*<TableCell>{row.userId}</TableCell>*/}
                        <TableCell>{row.userName}</TableCell>
                        <TableCell>{row.email}</TableCell>
                        <TableCell>{row.userRole}</TableCell>
                        <TableCell>{formatTimestamp(row.loginTimestamp)}</TableCell>
                        <TableCell>{formatTimestamp(row.logoutTimestamp)}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
              <Box sx={{ display: "flex", justifyContent: "flex-end", mt: 2 }}>
                <Pagination
                  count={totalPages}
                  page={page + 1}
                  onChange={(event, value) => setPage(value - 1)}
                  color="primary"
                  shape="rounded"
                />
              </Box>
            </>
          )}
        </Box>
      </Box>
    </div>
  );
}