import { Grid } from "@mui/material";
import {
  cusReqMasterDataAtom,
  SubmitErrorAlertAtom,
  useRecoilState,
  renderInputErrorLabel,
  ErrorLabelAtom,
  cusReqPortalListAtom,
  cusReqModuleListAtom,
  cusReqThemeListAtom,
  isEmptyObject,
  isObjectCus
} from "../../../../Heplers";
import React, { useMemo } from "react";
import { CusReqDropdown } from "..";

export const InputsSecondRowMasterData = ({readOnly}) => {

  const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
  // forCheckingInputErrorLabelOnlyAfterSubmit
  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);


  return useMemo(() => {
    return (
      <Grid spacing={2} container>

        <Grid item xs={12} md={4}>
          <CusReqDropdown
            // @ts-ignore
            formDataAtom={cusReqMasterDataAtom}
            listDataAtom={cusReqPortalListAtom}
            ddLabel="Portal/ Product"
            dropdownName={"portal"}
            required
            fetchMasterDataURL="fetchPortalMasterData_CusReq"
            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.portal : null}
            // defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? [Atom.portal] : []}
            // defVal={[{id: 1},{id: 2}]}
            // multiple={true}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
          {renderInputErrorLabel(ErrorLabel, Atom.portal, "Required")}
        </Grid>

        <Grid item xs={12} md={4}>
          <CusReqDropdown
            // @ts-ignore
            formDataAtom={cusReqMasterDataAtom}
            listDataAtom={cusReqModuleListAtom}
            ddLabel="Module"
            dropdownName={"module"}
            required
            fetchMasterDataURL="fetchModuleMasterData_CusReq"
            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.module : null}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
          {renderInputErrorLabel(ErrorLabel, Atom.module, "Required")}
        </Grid>

        <Grid item xs={12} md={4}>
          <CusReqDropdown
            // @ts-ignore
            formDataAtom={cusReqMasterDataAtom}
            listDataAtom={cusReqThemeListAtom}
            ddLabel="Theme/ Type of Change"
            dropdownName={"type_of_change"}
            required
            fetchMasterDataURL="fetchThemeMasterData_CusReq"
            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.type_of_change : null}

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
          {renderInputErrorLabel(ErrorLabel, Atom.type_of_change, "Required")}
        </Grid>
      </Grid>
    );
  }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
