import { Grid, TextField } from "@mui/material";
import {
  cusReqMasterDataAtom,
  SubmitErrorAlertAtom,
  useRecoilState,
  renderInputErrorLabel,
  ErrorLabelAtom,
  cusReqDeviationListAtom,
  cusReqShowstopperListAtom,
  yesNoArr,
  isEmptyObject,
  isObjectCus,
  invalidURLAlert,
  stakeholderArr,
  cusReqAssignedToListAtom, useRecoilValue, overViewTabAtom, isARDBCusReqTabActive, stakeholderArrARDB
} from "../../../../Heplers";
import React, { useEffect, useMemo } from "react";
import { CusReqDropdown, defTextFieldOnChange } from "..";

export const InputsFourthRowMasterData = ({formAtom, md=4, mt =0.3, readOnly}) => {

  const [Atom, setAtom] = useRecoilState(formAtom);
  // forCheckingInputErrorLabelOnlyAfterSubmit
  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);

  const defTextFieldOnChangeComParams = {
    setAtom, SubmitErrorAlert, setSubmitErrorAlert
  }

  useEffect(() => {
    // Setting Default Value
    // console.log(Atom)
    // For Update Form
  }, []);

  const condMt = mt === 0 ? {} : {
    mt: mt
  }

  const cusReqTabIndex = useRecoilValue(overViewTabAtom);

  return useMemo(() => {
    return (

      <Grid spacing={2} container {...condMt} >
        <Grid item xs={12} md={md}>
          <CusReqDropdown
            // @ts-ignore
            formDataAtom={formAtom}
            listDataAtom={cusReqAssignedToListAtom}
            ddLabel="Assigned To"
            dropdownName={"assigned_to"}
            required
            optData={isARDBCusReqTabActive(cusReqTabIndex) === 'Yes' ? stakeholderArrARDB : stakeholderArr}
            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.assigned_to : null}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
          {renderInputErrorLabel(ErrorLabel, Atom.assigned_to, "Required")}
        </Grid>


      </Grid>
    );
  }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
