import React, { useEffect, useMemo, useState, useCallback } from 'react';
import { Grid, Card, FormControl, InputLabel, Select, MenuItem, Button, Typography, RadioGroup, FormControlLabel, Radio, TextField } from "@mui/material";
import { useRecoilState } from 'recoil';
import { RestartAltRounded } from "@mui/icons-material";
import ManageSearchOutlinedIcon from "@mui/icons-material/ManageSearchOutlined";
import Pagination from '@mui/material/Pagination';
import { SITable } from './SiTable';
import { siTableDataAtom } from '../../RAS_updates/Heplers';
import { siSearchFieldsAtom, siStateListAtom, siNameListAtom, siPaymentMilestoneListAtom, totalRecordsAtom } from '../../RAS_updates/Heplers/siFormRecoil';
import { useNavigate, useLocation } from 'react-router-dom';
import axiosInstance from '../../Services/AxiosInstance';
import { PageLoadingElem, DataListingLoadingElem } from '../../RAS_updates/Pages/CustomizationRequest/Components';
import { CusReqDropdownSIPayment } from "./CusReqDropdownSIPayment";
import { set } from 'date-fns';

export default function SearchComponent() {
  const [Atom, setAtom] = useRecoilState(siSearchFieldsAtom);
  const [tableData, setTableData] = useRecoilState(siTableDataAtom);
  const [page, setPage] = React.useState(0);
  const [size, setSize] = React.useState(10);
  const [totalRecords, setTotalRecords] = useRecoilState(totalRecordsAtom);
  const [siNameOptions, setSiNameOptions] = useRecoilState(siNameListAtom);
  const [loading, setLoading] = useState(false);
  const [hasMounted, setHasMounted] = useState(false);
  const [siNameData, setSiNameData] = useState([]);
  const [siType, setSiType] = React.useState('');
  const [resetTriggered, setResetTriggered] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    axiosInstance.post('/si-payments/siswithStates').then(res => {
      if (res.data && Array.isArray(res.data)) {
        setSiNameData(res.data);
      }
    });
  }, []);

  useEffect(() => {
    // Only run if state is selected and siNameData is loaded
    if (Atom.state && Atom.state.id) {
      const match = siNameData.find(
        (item) => item.stateId === Atom.state.id
      );
      console.log("Matched state data", match);
      setSiNameOptions(match && Array.isArray(match.sis) ? match.sis : []);
    } else {
      setSiNameOptions([]); // No state selected, clear options
    }
  }, [Atom.state, siNameData, setSiNameOptions]);

  // Build query params from atom
  const buildQueryParams = () => {
    const params = {};
    if (Atom.siType) params.siType = Atom.siType;
    if (Atom.state) params.stateId = Atom.state.id || Atom.state;
    if (Atom.siName) params.siId = Atom.siName.siId || Atom.siName;
    if (Atom.paymentMilestone) params.paymentMilestone = Atom.paymentMilestone.id || Atom.paymentMilestone;
    if (Atom.status) params.status = Atom.status;
    if (Atom.invoiceNumber) params.invoiceNumber = Atom.invoiceNumber;
    params.page = page;
    params.size = size;
    params.sort = "createdAt,desc"; // Default sorting
  
    return params;
  };

  useEffect(() => {
    filterDataListing();
  }, [page]);
  // API call function
  useEffect(() => {
    if (resetTriggered) {
      filterDataListing(false); // Call after reset is applied
      setResetTriggered(false); // Reset the flag
    }
  }, [resetTriggered]);
  const filterDataListing = useCallback((reset = false) => {
    if (reset) {
      setResetTriggered(true);
      setAtom({
        state: null,
        siName: null,
        paymentMilestone: null,
        siType: '',
        status: '',
      });
      setPage(0);
      setSize(size);
      navigate({ search: '' });

      return;
    }

    const searchParams = new URLSearchParams();

    if (Atom.state) searchParams.set('stateId', String(Atom.state.id));
    if (Atom.siName) searchParams.set('siId', String(Atom.siName.siId));
    if (Atom.paymentMilestone) searchParams.set('paymentMilestone', String(Atom.paymentMilestone.id));
    if (Atom.siType) searchParams.set('siType', String(Atom.siType));
    if (Atom.status) searchParams.set('status', String(Atom.status));
    if (Atom.invoiceNumber) searchParams.set('invoiceNumber', String(Atom.invoiceNumber));

    navigate({ search: searchParams.toString() });

    setLoading(true);

    const params = buildQueryParams();
    axiosInstance.post('si-payments/filterPg', {}, { params })
      .then(res => {
        setTableData(res.data?.data || []);
        setTotalRecords(res.data?.totalRecords || 0);
      })
      .catch(() => {
        setTableData([]);
        setTotalRecords(0);
      })
      .finally(() => {
        setLoading(false);
      });
  }, [Atom, page]);


  // Handle field change
  const handleChange = (field) => (eventOrValue) => {
    let value = eventOrValue?.target ? eventOrValue.target.value : eventOrValue;
    setAtom((prev) => ({
      ...prev,
      [field]: value,
    }));
  };


  return (
    <Grid item container sx={{ width: "100%" }}>
      <Card sx={{ pt: 2, width: "100%" }}>
        {/* search fields */}
        <Grid item container spacing={2} sx={{ padding: "1%" }}>
          {/* State Dropdown */}
          <Grid item xs={12} sm={4}>
            {/* @ts-ignore */}
            <CusReqDropdownSIPayment
              // @ts-ignore
              formDataAtom={siSearchFieldsAtom}
              // @ts-ignore
              listDataAtom={siStateListAtom}
              ddLabel="State/ UT"
              dropdownName="state"
              fetchMasterDataURL="fetchStateMasterData_CusReq"
              // @ts-ignore
              optionLabel={["StateNameAndCode", "name", "short_name", "code"]}
            />
          </Grid>
          {/* SI Name Dropdown */}
          <Grid item xs={12} sm={4}>
            {/* @ts-ignore */}
            <CusReqDropdownSIPayment
              // @ts-ignore
              formDataAtom={siSearchFieldsAtom}
              // @ts-ignore
              listDataAtom={siNameListAtom}
              ddLabel="SI Name"
              dropdownName="siName"
              // @ts-ignore
              optionLabel={["sis", "state", "siId"]}
            />
          </Grid>
          {/* Payment Milestone Dropdown */}
          <Grid item xs={12} sm={4}>
            {/* @ts-ignore */}
            <CusReqDropdownSIPayment
              // @ts-ignore
              formDataAtom={siSearchFieldsAtom}
              // @ts-ignore
              listDataAtom={siPaymentMilestoneListAtom}
              ddLabel="Payment Milestone"
              dropdownName="paymentMilestone"
              fetchMasterDataURL="milestone/getmilestones"
              // @ts-ignore
              optionLabel={["name", "id"]}
            />
          </Grid>
          {/* Invoice Number */}
          <Grid item xs={12} sm={4} pb={2}>
            <TextField
              fullWidth
              label="Invoice Number"
              type="string"
              value={Atom.invoiceNumber || ''}
              onChange={handleChange('invoiceNumber')}
              InputLabelProps={{ shrink: true }}
              required
            />
          </Grid>
          {/* SI Type Number */}
          <Grid item xs={12} sm={4}>
            <FormControl fullWidth>
              <InputLabel id="si-type-label">SI Type</InputLabel>
              <Select
                labelId="si-type-label"
                id="si-type-select"
                value={Atom.siType || ''}
                label="Si Type"
                onChange={handleChange('siType')}
              >
                <MenuItem value="Hardware">Hardware</MenuItem>
                <MenuItem value="Digitisation">Digitisation</MenuItem>
              </Select>

            </FormControl>
          </Grid>
          <Grid item xs={12} sm={4}>
            <Typography style={{
              fontSize: "small",
              opacity: 0.7,
              fontWeight: 400
            }}>Status <span
              aria-hidden="true"
              className="MuiFormLabel-asterisk MuiInputLabel-asterisk css-wgai2y-MuiFormLabel-asterisk"> *</span></Typography>
            <RadioGroup
              row
              value={Atom.status || ''}
              onChange={handleChange('status')}
              aria-required={true}
            >
              <FormControlLabel value="PAID" control={<Radio />} label="Paid" />
              <FormControlLabel value="UNPAID" control={<Radio />} label="Unpaid" />
            </RadioGroup>
          </Grid>
        </Grid>

        <Grid
          container
          item
          sx={{ padding: "1%" }}
          justifyContent="space-between"
          alignItems="center"
        >
          {/* Left: Total Records */}
          <Grid
              container
              item
              md={6}
              sx={{p: 1}}
              display="flex"
              direction={"row"}
              justifyContent="flex-start"
              alignItems="end"
          >
            <Typography color={'GrayText'} fontSize={11} fontWeight="bold">
              Total Records:</Typography>
            <Typography fontSize={12} className="fontGreenTheme bold">{totalRecords}</Typography>
          </Grid>

          {/* Right: Buttons */}
          <Grid item display="flex" alignItems="center">
            <Button
              onClick={() => filterDataListing(true)}
              sx={{ mt: 1, mx: 1 }}
              variant="contained"
              color="warning"
            >
              Reset <RestartAltRounded sx={{ width: 20, ml: 1 }} />
            </Button>
            <Button
              onClick={() => {
                setPage(0); // Reset to first page before search
                filterDataListing();
              }}
              sx={{ mt: 1 }}
              variant="contained"
              color="success"
            >
              Search <ManageSearchOutlinedIcon sx={{ width: 20, ml: 1 }} />
            </Button>
          </Grid>
        </Grid>

      </Card>

      {/* Table data */}
      {loading ? <PageLoadingElem /> : <SITable page={page} size={size} />}
      {/* Pagination */}
      <Grid item xs={12} sx={{ mt: 2 }} display="flex" justifyContent="flex-end">
        <Pagination
          count={Math.ceil(totalRecords / size)}
          page={page + 1}
          onChange={(_, value) => setPage(value - 1)}
          color="primary"
          shape="rounded"
        />
      </Grid>
    </Grid>
  );
}